/**
 * Module-level single-flight state for auth-token refresh (SGVS-1921).
 *
 * Kept outside `useAuth()` so every caller shares the same in-flight promise,
 * and every refresh that races with a sign-out is suppressed. Exporting the
 * primitive makes the behavior unit-testable without a Nuxt runtime.
 */

type RefreshRunner<T> = () => Promise<T>;

let _inFlight: Promise<unknown> | null = null;
let _signingOut = false;

export function pendingRefresh<T = unknown>(): Promise<T> | null {
  return _inFlight as Promise<T> | null;
}

export function isSigningOut(): boolean {
  return _signingOut;
}

export function setSigningOut(value: boolean): void {
  _signingOut = value;
}

/**
 * Await the in-flight refresh, swallowing rejection. No-op if nothing is in
 * flight.
 *
 * Used by `signOut()` to drain a refresh that's already past the
 * `singleFlightRefresh` gate so its `setToken()` lands BEFORE the caller
 * clears tokens — otherwise the refresh resurrects the access token after
 * the clear and leaves a usable session in memory.
 *
 * Pair with `setSigningOut(true)` BEFORE calling: that blocks any new refresh
 * from starting, so once this resolves no further `setToken()` calls can come
 * from this module.
 */
export async function drainPendingRefresh(): Promise<void> {
  if (!_inFlight) return;
  try {
    await _inFlight;
  } catch {
    // Refresh failure is irrelevant to ordering-only callers.
  }
}

/**
 * Run `run()` at most once at a time. Concurrent callers receive the same
 * in-flight promise. When the promise settles (success OR failure) the slot
 * is cleared so the next call triggers a fresh run. Returns `undefined`
 * synchronously when a sign-out is in progress.
 */
export function singleFlightRefresh<T>(run: RefreshRunner<T>): Promise<T | undefined> {
  if (_signingOut) return Promise.resolve(undefined);
  if (!_inFlight) {
    _inFlight = run().finally(() => {
      _inFlight = null;
    });
  }
  return _inFlight as Promise<T>;
}

/**
 * Test-only helper. Do not call from application code.
 */
export function __resetForTests(): void {
  _inFlight = null;
  _signingOut = false;
}
