import type { HttpOptions } from '@capacitor/core';
import type { MobileWorkShiftResumeRequest, MobileWorkShiftResumeResponse, ResumeWorkShiftData } from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function resumeWorkShift(payload: MobileWorkShiftResumeRequest): Promise<MobileWorkShiftResumeResponse> {
  const url: ResumeWorkShiftData['url'] = '/api/mobile/work_shift/resume';
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<MobileWorkShiftResumeResponse>(options, 'WorkShift|Resume');
}
