import { Preferences } from '@capacitor/preferences';
import { prefetchOfflineData } from '~/utils/prefetchOfflineData';
import { PREFETCH_INTERVAL } from '~/config/cache';

const PREF_KEY = 'offline-prefetch-last';

async function getLastPrefetch(): Promise<number> {
  const { value } = await Preferences.get({ key: PREF_KEY });
  return value ? Number(value) : 0;
}

export async function markPrefetched(): Promise<void> {
  await Preferences.set({ key: PREF_KEY, value: String(Date.now()) });
}

async function prefetchIfStale(): Promise<void> {
  const { isAuthenticated } = useUserRole();
  if (!isAuthenticated.value) return;

  const last = await getLastPrefetch();
  if (Date.now() - last < PREFETCH_INTERVAL) return;

  prefetchOfflineData();
  await markPrefetched();
}

let _visibilityListenerAdded = false;

export default defineNuxtPlugin((nuxtApp) => {
  nuxtApp.hook('app:mounted', () => {
    prefetchIfStale().catch(() => {});

    if (!_visibilityListenerAdded) {
      _visibilityListenerAdded = true;
      const handler = () => {
        if (document.visibilityState === 'visible') {
          prefetchIfStale().catch(() => {});
        }
      };
      document.addEventListener('visibilitychange', handler);
      // Clean up on HMR
      if (import.meta.hot) {
        import.meta.hot.dispose(() => document.removeEventListener('visibilitychange', handler));
      }
    }
  });
});
