import type { TypedNuxtLink } from '#build/typed-router/typed-router';
import {
  journeyGroupKey,
  NAV_JOURNEY_STATE_KEY,
  NAV_JOURNEY_STORAGE_KEY,
  parseStoredJourney,
  type JourneyEntry,
} from '~/utils/navJourney';

export function useNavJourney() {
  // Sole owner of the journey state: initialize from sessionStorage here so the plugin
  // and every component share one source of truth (no competing useState initializers).
  const journey = useState<JourneyEntry[]>(NAV_JOURNEY_STATE_KEY, () =>
    import.meta.client ? parseStoredJourney(sessionStorage.getItem(NAV_JOURNEY_STORAGE_KEY)) : []
  );

  const router = useRouter();

  // Group of the page currently displayed. A recorded page sits on top of the stack;
  // a skipNavJourney page (create/import forms) is never recorded, so it is absent.
  const currentGroup = computed<string | undefined>(() => {
    const route = router.currentRoute.value;
    if (!route?.name) return undefined;
    return journeyGroupKey(String(route.name), route.params, route.meta?.backGroup);
  });

  const parent = computed<JourneyEntry | undefined>(() => {
    const stack = journey.value;
    if (stack.length === 0) return undefined;
    // When the current page was recorded it IS the stack top, so the back target is the
    // entry beneath it. When the current page is skipped (skipNavJourney), the top already
    // is the page we came from — the back target — so use it directly. Without this branch,
    // Back on a create/import page points one step too far back (to the grandparent).
    const topIsCurrent = stack[stack.length - 1].group === currentGroup.value;
    const index = stack.length - (topIsCurrent ? 2 : 1);
    return index >= 0 ? stack[index] : undefined;
  });

  const navigateBack = (fallbackTo?: TypedNuxtLink['to']) => {
    if (parent.value) {
      const target = {
        name: parent.value.name,
        params: parent.value.params,
        query: parent.value.query,
      } as TypedNuxtLink['to'];
      try {
        // Throws for a stale journey entry (route removed/renamed after a deploy, or now
        // missing a required param). Fall through to fallbackTo instead of crashing on click.
        router.resolve(target);
        return navigateTo(target);
      } catch {
        // stale/unresolvable parent — use the fallback below
      }
    }
    return navigateTo(fallbackTo);
  };

  return { journey, parent, navigateBack };
}
