/**
 * Check if a JWT token is expired by decoding its `exp` claim.
 * Returns true if expired or unparseable.
 *
 * `now` is injectable so callers can either share a single clock reading
 * across multiple helper calls (`computeProactiveRefreshDelayMs`) or apply
 * a forward-looking clock-skew buffer by passing `Date.now() + bufferMs`
 * (the pre-request interceptor uses this to treat about-to-expire tokens
 * as already expired and refresh proactively).
 */
export function isTokenExpired(token: string | null | undefined, now: number = Date.now()): boolean {
  if (!token) return true;
  try {
    const payload = JSON.parse(atob(token.split('.')[1]));
    return payload.exp * 1000 < now;
  } catch {
    return true;
  }
}

/**
 * Return the absolute expiry time (Unix ms) from a JWT's `exp` claim.
 * Returns null if the token is missing or unparseable.
 */
export function getTokenExpiryMs(token: string | null | undefined): number | null {
  if (!token) return null;
  try {
    const payload = JSON.parse(atob(token.split('.')[1]));
    if (typeof payload.exp !== 'number') return null;
    return payload.exp * 1000;
  } catch {
    return null;
  }
}
