<template>
  <NuxtLayout :name="layout">
    <AppError
      v-if="error"
      :error="error"
      :title="title"
      :message="error.statusMessage || 'Sorry, something went wrong.'"
      :to="{ name: 'index' }"
      action-text="Go Home"
    />
  </NuxtLayout>
</template>

<script setup lang="ts">
import type { NuxtError } from '#app';

const props = defineProps({
  error: {
    type: Object as () => NuxtError,
    required: true,
  },
});

const route = useRoute();
const { isAuthenticated } = useUserRole();

const layout = computed(() => {
  const metaLayout = route.meta.layout;
  // A 404 (unmatched route) has no layout, so NuxtLayout would fall back to the
  // auth-only `default` sidebar. Use the public `share` shell when the user isn't
  // authenticated — this also covers an auth-only layout reached while logged out
  // (e.g. a 500 on a protected page). For an unauthenticated user a missing,
  // `false`, or `default` layout all fall back to `share`; an explicit non-default
  // layout (e.g. `login`) is kept. Authenticated users always keep `route.meta.layout`.
  if (!isAuthenticated.value && (!metaLayout || metaLayout === 'default')) {
    return 'share';
  }
  return metaLayout;
});

const title = props.error.statusCode === 404 ? 'Page Not Found' : 'An error occurred';

useHead({
  title: `${title} | Patriot Grassroots App`,
});
</script>
