import { pauseWorkShift } from '~/mutations/mobile/pauseWorkShift';
import { resumeWorkShift } from '~/mutations/mobile/resumeWorkShift';
import { deletePayloadsByIds } from '~/utils/useDb';

export type ShiftBreakRow = {
  _rowId: number;
  type: 'pause' | 'resume';
  work_shift_id?: string;
  [key: string]: unknown;
};

// Pause/resume events must be uploaded in row-ID order to preserve causality.
// Each record is deleted individually so a partial failure safely retries only remaining rows.
// A 400/404 means the event is no longer applicable (events arrived out of order or the
// payload is malformed). Drop the offending row and continue — otherwise it would jam every
// future tick and block shift_end uploads for the same shift.
export async function uploadShiftBreakEventBatch(rows: ShiftBreakRow[]): Promise<number> {
  let uploaded = 0;
  for (const { _rowId, type, ...data } of rows) {
    try {
      if (type === 'pause') {
        await pauseWorkShift(data as Parameters<typeof pauseWorkShift>[0]);
      } else {
        await resumeWorkShift(data as Parameters<typeof resumeWorkShift>[0]);
      }
    } catch (err: any) {
      const status = err?.statusCode ?? err?.status;
      if (status === 400 || status === 404) {
        console.error(
          `[Uploader] Dropping shift_break_event row ${_rowId} (type=${type}, status=${status}, work_shift_id=${data.work_shift_id}): ${err?.message ?? err}`
        );
        await deletePayloadsByIds([_rowId]);
        continue;
      }
      throw err;
    }
    await deletePayloadsByIds([_rowId]);
    uploaded++;
  }
  return uploaded;
}
