import { Capacitor } from '@capacitor/core';
import { AudioManager } from 'audio-manager-plugin';
import type { AudioSessionUnavailableReason } from 'audio-manager-plugin';
import type { SelectorProjectItem } from '~/client';
import { projectRequiresAudio } from '~/composables/mobile/useMobilePermissions';

export class AudioSessionBusyError extends Error {
  constructor(public reason: AudioSessionUnavailableReason) {
    super(`Audio session busy: ${reason}`);
    this.name = 'AudioSessionBusyError';
  }
}

export function audioBusyToastMessage(reason: AudioSessionUnavailableReason): string {
  if (reason === 'on_call') return 'You are on a call. End the call and tap Start Shift again.';
  return 'Another app is using audio. Close it and tap Start Shift again.';
}

export async function ensureAudioSessionAvailable(project: SelectorProjectItem | null | undefined): Promise<void> {
  if (!Capacitor.isNativePlatform()) return;
  if (!projectRequiresAudio(project)) return;

  const res = await AudioManager.checkAudioSessionAvailable();
  if (!res.available) {
    throw new AudioSessionBusyError(res.reason ?? 'other_audio');
  }
}
