import { sendUpdateDeviceInfo } from '~/utils/mobile/updateDeviceInfo';

// Single-flight: all concurrent callers await the same registration request.
let linkPromise: Promise<void> | null = null;

/**
 * Ensures the current device is registered and linked to the signed-in user
 * (via /mobile/device/update_info) exactly once per session.
 *
 * Mobile events (app_state, data_upload, ...) are rejected by the backend with
 * a 403 until the device→user link exists. Awaiting this before sending the
 * first event guarantees the link is created up front, removing the race where
 * an event reaches the backend before the periodic device-info poll has run.
 *
 * Safe to call from many places concurrently — they share one in-flight request.
 * On failure the cache is cleared so the next caller retries.
 *
 * Once resolved, the cached promise lives until resetDeviceLink() (logout). If the
 * backend link is deactivated out-of-band, this path won't re-link on its own — but
 * the 5-min sendUpdateDeviceInfo() poll in app.vue re-registers the device directly,
 * keeping the backend link alive. That poll bypasses this cache, so it does not
 * refresh linkPromise; the only cost is one redundant /update_info on the first
 * event after login, which is the accepted trade-off for the "once per session" guard.
 */
export function ensureDeviceLinked(): Promise<void> {
  if (!linkPromise) {
    linkPromise = sendUpdateDeviceInfo().catch((error) => {
      linkPromise = null; // allow a later retry
      throw error;
    });
  }
  return linkPromise;
}

/**
 * Clears the cached registration so the next user on this device re-links.
 * Call on logout, after the backend link has been deactivated.
 */
export function resetDeviceLink(): void {
  linkPromise = null;
}
