export function createMutex() {
  let tail = Promise.resolve();
  const locked = ref(false);
  return {
    async run<T>(op: () => Promise<T>): Promise<T> {
      let release: () => void;
      const gate = new Promise<void>((r) => {
        release = r;
      });
      const prev = tail;
      tail = gate;
      await prev;
      locked.value = true;
      try {
        return await op();
      } finally {
        locked.value = false;
        release!();
      }
    },
    get isLocked() {
      return locked;
    },
  };
}
