import type { QueryData, PostgrestError } from '@supabase/supabase-js';
import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

type GetChatListCursorArgs = Database['private']['CompositeTypes']['get_user_chats_cursor_input'];

export const useGetChatCursorList = async (data: GetChatListCursorArgs) => {
  return withSupabase((supabase) => supabase.rpc('get_user_chats_cursor', { input: data }));
};

type GetChatListCursorAtArgs = Database['private']['CompositeTypes']['get_user_chats_cursor_at_input'];

export const useGetChatListCursorAt = async (data: GetChatListCursorAtArgs) => {
  return withSupabase((supabase) => supabase.rpc('get_user_chats_cursor_at', { input: data }));
};

export type GetChatListResponse = QueryData<ReturnType<typeof useGetChatCursorList>>;
export type ChatItem = Database['private']['Functions']['get_user_chats_cursor']['Returns'][number];

export type ChatsData = {
  items: GetChatListResponse;
  error: PostgrestError | null;
  oldestId: number | null;
  newestId: number | null;
  hasOlder: boolean;
  hasNewer: boolean;
};
