import type { HttpOptions } from '@capacitor/core';
import type {
  MobileDeviceEventSendData,
  MobileDeviceEventSendRequest,
  MobileDeviceEventSendResponse,
  MobileDeviceEventBatchSendData,
  MobileDeviceEventBatchSendRequest,
  MobileDeviceEventBatchSendResponse,
} from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function sendEvent(payload: MobileDeviceEventSendRequest): Promise<MobileDeviceEventSendResponse> {
  const url: MobileDeviceEventSendData['url'] = '/api/mobile/device/event/send';
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<MobileDeviceEventSendResponse>(options, 'SendEvent');
}

export async function sendEventBatch(
  payload: MobileDeviceEventBatchSendRequest
): Promise<MobileDeviceEventBatchSendResponse> {
  const url: MobileDeviceEventBatchSendData['url'] = '/api/mobile/device/event/batch_send';
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<MobileDeviceEventBatchSendResponse>(options, 'SendEventBatch');
}
