import { getDB, initDb, isDbInitialized, tables } from '~/utils/dbManager';

import { getCurrentWorkShiftId } from '~/composables/mobile/shift/useMobileShift';
import { type AppConfig, DefaultAppConfig } from '~/types/database/config';
import type { payloadDataType } from '~/types/database/payload';
import type { MobileLocation } from '~/types/mobile/location';
import { MESSAGE_TYPES } from '~/types/mobile/trackingSensors';

let userId: ComputedRef<string | undefined>;

export const { payloads, cachedAudio, cachedWakeWordClips, settings, recentLocations } = tables;

export const RECENT_LOCATION_LIMIT = 20;

// Expected on the login page: app-lifecycle listeners fire before initDB() ever runs.
const DB_NOT_INITIALIZED_MSG = 'Database not yet initialized. Skipping payload write.';

export async function initConfigTable() {
  const db = await getDB();
  const { values } = await db.query(`SELECT COUNT(*) as count FROM ${settings.name} WHERE ${settings.cols.id} = 1;`);
  const count = (values?.[0] as any)?.count ?? 0;
  if (count === 0) {
    await db.run(`INSERT INTO ${settings.name} (${settings.cols.id}, ${settings.cols.config}) VALUES (1, ?);`, [
      JSON.stringify(DefaultAppConfig),
    ]);
  }
}

export async function initDB(userID: ComputedRef<string | undefined>, environment: string) {
  userId = userID;
  await initDb(environment);
  await initConfigTable();
}

export async function addPayload(dataType: payloadDataType, payload: any) {
  // Fired from app-lifecycle listeners (e.g. app_state mobile events) regardless of auth.
  // On the login page the DB was never initialized and the userId ref is unset, so bail out
  // before touching userId.value or getDB. Use debug, not warn: this is the expected
  // pre-login state and app_state events fire on every foreground/background toggle.
  if (!isDbInitialized()) {
    console.debug(DB_NOT_INITIALIZED_MSG);
    return;
  }
  const shiftId = await getCurrentWorkShiftId();
  if (!shiftId) {
    console.warn("Workshift is ended or didn't start properly. Skipping data collection.");
    return;
  }
  if (!userId.value) {
    console.warn('User id is missing (logged out?). Skipping payload write.');
    return;
  }
  const db = await getDB();
  const payloadJson = JSON.stringify(payload);

  await db.run(
    `INSERT INTO ${payloads.name} (${payloads.cols.dataType}, ${payloads.cols.payload}, ${payloads.cols.userId}) VALUES (?, ?, ?);`,
    [dataType, payloadJson, userId.value]
  );
}

export async function saveAudio(metadata: any, path: string) {
  const db = await getDB();
  const metadataString = JSON.stringify(metadata);

  await db.run(
    `INSERT INTO ${cachedAudio.name} (${cachedAudio.cols.metadata}, ${cachedAudio.cols.createdAt}, ${cachedAudio.cols.audioPath}) VALUES (?, ?, ?);`,
    [metadataString, new Date().valueOf(), path]
  );
}

export async function fetchCachedAudioItems(columns: string[]): Promise<any[] | null> {
  const db = await getDB();

  if (!columns.length) return null;

  const colsSql = columns.join(', ');

  const res = await db.query(`
    SELECT ${colsSql}
    FROM ${cachedAudio.name} ORDER BY ${cachedAudio.cols.createdAt} ASC;
  `);

  if (!res.values?.length) return null;

  return res.values.map((row) => {
    const item: Record<string, any> = {};

    columns.forEach((col) => {
      const value = row[col];

      if (col === cachedAudio.cols.metadata && value) {
        Object.assign(item, JSON.parse(value));
      } else {
        item[col] = value;
      }
    });

    return item;
  });
}

export async function deleteCachedAudioByIds(ids: number[]) {
  if (!ids.length) return;
  const db = await getDB();
  const placeholders = ids.map(() => '?').join(',');
  await db.run(`DELETE FROM ${cachedAudio.name} WHERE ${cachedAudio.cols.id} IN (${placeholders});`, ids);
}

