export async function addPayloadReturningId(dataType: payloadDataType, payload: any): Promise<number> {
  if (!isDbInitialized()) {
    console.debug(DB_NOT_INITIALIZED_MSG);
    return -1;
  }
  const shiftId = await getCurrentWorkShiftId();
  if (!shiftId) {
    console.warn("Workshift is ended or didn't start properly. Skipping data collection.");
    return -1;
  }
  if (!userId.value) {
    console.warn('User id is missing (logged out?). Skipping payload write.');
    return -1;
  }
  const db = await getDB();
  const result = await db.run(`INSERT INTO payloads (data_type, payload, user_id) VALUES (?, ?, ?);`, [
    dataType,
    JSON.stringify(payload),
    userId.value,
  ]);
  return result.changes?.lastId ?? -1;
}

export async function getMaxPayloadId(): Promise<number> {
  const db = await getDB();
  const res = await db.query(
    `SELECT MAX(${payloads.cols.id}) as maxId FROM ${payloads.name} WHERE ${payloads.cols.userId} = ?;`,
    [userId.value]
  );
  return (res.values?.[0] as any)?.maxId ?? 0;
}

export async function getPendingPayloadCount(maxId: number): Promise<number> {
  const db = await getDB();
  const res = await db.query(
    `SELECT COUNT(*) as count FROM ${payloads.name} WHERE ${payloads.cols.userId} = ? AND ${payloads.cols.id} <= ?;`,
    [userId.value, maxId]
  );
  return (res.values?.[0] as any)?.count ?? 0;
}

export async function getAllByType(dataType: payloadDataType, limit: number = 100, maxId?: number) {
  const db = await getDB();
  const hasMaxId = maxId != null;
  const res = await db.query(
    `SELECT ${payloads.cols.id}, ${payloads.cols.payload}
     FROM ${payloads.name}
     WHERE ${payloads.cols.dataType} = ? AND ${payloads.cols.userId} = ?${hasMaxId ? ` AND ${payloads.cols.id} <= ?` : ''}
     LIMIT ?;`,
    hasMaxId ? [dataType, userId.value, maxId, limit] : [dataType, userId.value, limit]
  );
  return (res.values ?? []).map((row) => ({
    _rowId: row.id,
    ...JSON.parse(row.payload),
  }));
}

export async function getAllByWorkShift(workshiftId: string, limit: number = 100) {
  const db = await getDB();
  const res = await db.query(
    `SELECT ${payloads.cols.id}, ${payloads.cols.payload}
     FROM ${payloads.name}
     WHERE json_extract(${payloads.cols.payload}, '$.work_shift_id') = ?
       AND ${payloads.cols.userId} = ?
       AND ${payloads.cols.dataType} != ?
     LIMIT ?;`,
    [workshiftId, userId.value, MESSAGE_TYPES.shift_end, limit]
  );
  return (res.values ?? []).map((row) => ({
    _rowId: row.id,
    ...JSON.parse(row.payload),
  }));
}

export async function deletePayloadsByIds(ids: number[]) {
  if (!ids.length) return;
  const db = await getDB();
  const placeholders = ids.map(() => '?').join(',');
  await db.run(`DELETE FROM ${payloads.name} WHERE ${payloads.cols.id} IN (${placeholders});`, ids);
}

export async function getConfig(): Promise<AppConfig> {
  const db = await getDB();
  const res = await db.query(`SELECT ${settings.cols.config} FROM ${settings.name} WHERE ${settings.cols.id} = 1;`);
  const json = res.values?.[0]?.config;
  return json ? JSON.parse(json) : { ...DefaultAppConfig };
}

export async function updateConfigValue<K extends keyof AppConfig>(key: K, value: AppConfig[K]) {
  const current = await getConfig();
  current[key] = value;
  await updateConfig(current);
}

export async function updateConfig(config: AppConfig): Promise<void> {
  const db = await getDB();
  await db.run(`UPDATE ${settings.name} SET ${settings.cols.config} = ? WHERE ${settings.cols.id} = 1;`, [
    JSON.stringify(config),
  ]);
}

export async function saveRecentLocation(loc: MobileLocation): Promise<void> {
  try {
    const db = await getDB();
    await db.run(
      `INSERT INTO ${recentLocations.name} (${recentLocations.cols.timestamp}, ${recentLocations.cols.location}) VALUES (?, ?);`,
      [loc.timestamp, JSON.stringify(loc)]
    );
    await db.run(
      `DELETE FROM ${recentLocations.name}
       WHERE ${recentLocations.cols.id} NOT IN (
         SELECT ${recentLocations.cols.id} FROM ${recentLocations.name}
         ORDER BY ${recentLocations.cols.id} DESC
         LIMIT ?
       );`,
      [RECENT_LOCATION_LIMIT]
    );
  } catch (e) {
    console.warn('[useDb] saveRecentLocation failed:', e);
  }
}

export async function getRecentLocations(limit: number = RECENT_LOCATION_LIMIT): Promise<MobileLocation[]> {
  try {
    const db = await getDB();
    const res = await db.query(
      `SELECT ${recentLocations.cols.location}
       FROM ${recentLocations.name}
       ORDER BY ${recentLocations.cols.id} DESC
       LIMIT ?;`,
      [limit]
    );
    return (res.values ?? []).map((row) => JSON.parse(row.location) as MobileLocation);
  } catch (e) {
    console.warn('[useDb] getRecentLocations failed:', e);
    return [];
  }
}

export async function getLatestRecentLocation(): Promise<MobileLocation | null> {
  const [latest] = await getRecentLocations(1);
  return latest ?? null;
}

export async function clearRecentLocations(): Promise<void> {
  try {
    const db = await getDB();
    await db.run(`DELETE FROM ${recentLocations.name};`);
  } catch (e) {
    console.warn('[useDb] clearRecentLocations failed:', e);
  }
}

export async function checkForUnsyncedData(): Promise<string[]> {
  const currentShiftId = await getCurrentWorkShiftId();
  const db = await getDB();

  const res = await db.query(
    `SELECT DISTINCT json_extract(${payloads.cols.payload}, '$.work_shift_id') AS workShiftId
     FROM ${payloads.name}
     WHERE ${payloads.cols.userId} = ?
       AND json_extract(${payloads.cols.payload}, '$.work_shift_id') IS NOT NULL
       AND ${payloads.cols.dataType} != ?;`,
    [userId.value, MESSAGE_TYPES.shift_end]
  );

  return (res.values ?? [])
    .map((row) => row.workShiftId)
    .filter((id): id is string => Boolean(id) && id !== currentShiftId);
}
