import type { HttpOptions } from '@capacitor/core';
import type { CheckWorkShiftStatusV2Data, CheckWorkShiftStatusV2Response } from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function getWorkShiftStatus(): Promise<CheckWorkShiftStatusV2Response | null> {
  const url: CheckWorkShiftStatusV2Data['url'] = '/api/mobile/work_shift/status_v2';
  const options: HttpOptions = { url };
  try {
    return await doNativeRequest<CheckWorkShiftStatusV2Response>(options, 'Work_Shift|Status_v2');
  } catch (err: any) {
    console.error('Failed to get work shift status\n' + err);
    return null;
  }
}
