// A deep link and an SMS short-link target both arrive as absolute URLs on the public web host, but the
// native WebView is served from its own origin, so only the path can be handed to the router. Returns null
// rather than a fallback path so the caller can tell an unparseable URL apart from a real "/" target.
export function routePathFromUrl(url: string): string | null {
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      const hostPart = parsed.hostname ? '/' + parsed.hostname : '';
      return hostPart + parsed.pathname + parsed.search + parsed.hash;
    }
    return parsed.pathname + parsed.search + parsed.hash;
  } catch {
    return null;
  }
}
