import type { BackgroundGeolocationPlugin, Location, CallbackError } from '@capacitor-community/background-geolocation';
import { registerPlugin } from '@capacitor/core';
import { Network, type ConnectionType } from '@capacitor/network';
import type { PluginListenerHandle } from '@capacitor/core';
import { v4 as uuidv4 } from 'uuid';
import type { MobileModule } from '~/types/mobile/module';
import type { MobileLocation } from '~/types/mobile/location';
import {
  updateCurrentLocation,
  clearCurrentLocation,
  restoreCurrentLocation,
} from '~/composables/mobile/useCurrentLocation';
import { AudioManager } from 'audio-manager-plugin';
import { addPayload } from '~/utils/useDb';
import { SENSOR_TYPES } from '~/types/mobile/trackingSensors';
import { getAppConfig } from '~/composables/mobile/config/useMobileConfig';
import { useRecorderStore } from '~/stores/mobile/vadRecorder';

const BackgroundGeolocation = registerPlugin<BackgroundGeolocationPlugin>('BackgroundGeolocation');

interface LocationReading {
  latitude: number;
  longitude: number;
  accuracy: number;
  timestamp: number;
  altitude: number | null;
  altitude_accuracy: number | null;
  speed: number | null;
  bearing: number | null;
  simulated: boolean;
  connection_type: ConnectionType;
}

export function createLocationTracker(shiftId: string, deviceId: string): MobileModule {
  const config = getAppConfig();
  const recorderStore = useRecorderStore();

  let watcherId: string | null = null;
  let networkListener: PluginListenerHandle | null = null;
  let _alive = false;
  let currentConnectionType: ConnectionType = 'none';

  let buffer: LocationReading[] = [];
  let batchId: string | undefined;
  let flushTimer: ReturnType<typeof setInterval> | null = null;
  const pendingFlushes = new Set<Promise<void>>();

  function toMobileLocation(location: Location): MobileLocation {
    return {
      latitude: location.latitude,
      longitude: location.longitude,
      accuracy: location.accuracy,
      altitude: location.altitude ?? undefined,
      altitude_accuracy: location.altitudeAccuracy ?? undefined,
      timestamp: location.time || Date.now(),
    };
  }

  function enqueueLocation(location: Location, loc: MobileLocation) {
    if (!batchId) {
      batchId = uuidv4();
    }
    buffer.push({
      latitude: loc.latitude,
      longitude: loc.longitude,
      accuracy: loc.accuracy,
      timestamp: loc.timestamp,
      altitude: loc.altitude ?? null,
      altitude_accuracy: loc.altitude_accuracy ?? null,
      speed: location.speed ?? null,
      bearing: location.bearing ?? null,
      simulated: location.simulated,
      connection_type: currentConnectionType,
    });
    if (buffer.length >= config.LocationBufferSize) {
      const p = flushBuffer();
      pendingFlushes.add(p);
      void p.finally(() => pendingFlushes.delete(p));
    }
  }

  async function flushBuffer() {
    if (!buffer.length) return;

    const readings = buffer;
    const id = batchId;
    buffer = [];
    batchId = undefined;

    const payload = {
      record_id: id,
      work_shift_id: shiftId,
      device_id: deviceId,
      sensor_type: SENSOR_TYPES.gps,
      started_at: readings[0].timestamp ?? Date.now(),
      ended_at: readings[readings.length - 1].timestamp ?? Date.now(),
      sensor_readings: readings,
    };

    try {
      await addPayload(SENSOR_TYPES.gps, payload);
      console.log(`[gps] Flushed batch ${id} with ${readings.length} readings.`);
    } catch (e) {
      console.error(`[gps] Failed to flush batch ${id}:`, e);
    }
  }

  async function startWatcher() {
    if (watcherId) {
      await BackgroundGeolocation.removeWatcher({ id: watcherId });
      watcherId = null;
    }

    watcherId = await BackgroundGeolocation.addWatcher(
      {
        backgroundMessage: 'Activity is being recorded',
        backgroundTitle: 'Workshift in progress',
        requestPermissions: false,
        stale: false,
        distanceFilter: config.LocationDistanceFilter,
        androidPriority: config.LocationAndroidPriority,
        desiredAccuracy: config.LocationDesiredAccuracy,
        pausesLocationUpdatesAutomatically: config.LocationPausesAutomatically,
        activityType: config.LocationActivityType,
      },
      onLocationUpdate
    );
    console.log('[Watcher] started with filter=' + config.LocationDistanceFilter);
  }

  function onLocationUpdate(location: Location | undefined, error: CallbackError | undefined) {
    if (error || !location) {
      if (error) console.error('Geolocation error:', error);
      return;
    }
    const loc = toMobileLocation(location);
    console.log('[LocationTracker] onLocationUpdate fired', JSON.stringify(loc));

    updateCurrentLocation(loc);
    enqueueLocation(location, loc);

    if (recorderStore.isAlive()) {
      AudioManager.updateLocation(loc).catch((e: unknown) =>
        console.warn('[LocationTracker] Failed to forward location to AudioManager:', e)
      );
    }
  }

  async function stopWatcher() {
    if (!watcherId) return;
    // No catch: a failed native removeWatcher must propagate so the module manager
    // counts this module as still running and keeps the handle for retry (SGVS-2678).
    await BackgroundGeolocation.removeWatcher({ id: watcherId });
    console.log('Watcher stopped:', watcherId);
    watcherId = null;
    clearCurrentLocation();
  }

  const start = async () => {
    await restoreCurrentLocation();
    const status = await Network.getStatus();
    currentConnectionType = status.connectionType;
    networkListener = await Network.addListener('networkStatusChange', (status) => {
      currentConnectionType = status.connectionType;
    });
    await startWatcher();
    flushTimer = setInterval(() => {
      void flushBuffer();
    }, config.LocationFlushIntervalMs);
    _alive = true;
  };

  const stop = async () => {
    if (flushTimer) {
      clearInterval(flushTimer);
      flushTimer = null;
    }
    await stopWatcher();
    await networkListener?.remove();
    networkListener = null;
    await Promise.all(pendingFlushes);
    await flushBuffer();
    _alive = false;
  };

  const isAlive = () => _alive || watcherId !== null;
  return { name: SENSOR_TYPES.gps, isAlive, start, stop };
}
