import type { HttpOptions } from '@capacitor/core';
import type {
  MobileWorkShiftFinalizeResponseV2,
  FinalizeWorkShiftV2Data,
  MobileWorkShiftFinalizeRequest,
} from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function uploadShiftEnd(
  payload: MobileWorkShiftFinalizeRequest[]
): Promise<MobileWorkShiftFinalizeResponseV2> {
  const url: FinalizeWorkShiftV2Data['url'] = '/api/mobile/work_shift/finalize_v2';
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<MobileWorkShiftFinalizeResponseV2>(options, 'ShiftEnd');
}
