import type { MobileLocation } from '~/types/mobile/location';
import { clearRecentLocations, getLatestRecentLocation, saveRecentLocation } from '~/utils/useDb';

const currentLocation = ref<MobileLocation | null>(null);
const lastUpdateTime = ref<number | null>(null);

export function updateCurrentLocation(location: MobileLocation) {
  currentLocation.value = location;
  lastUpdateTime.value = Date.now();
  void saveRecentLocation(location);
}

export function clearCurrentLocation() {
  currentLocation.value = null;
  lastUpdateTime.value = null;
  void clearRecentLocations();
}

export async function restoreCurrentLocation(): Promise<MobileLocation | null> {
  if (currentLocation.value) return currentLocation.value;
  const latest = await getLatestRecentLocation();
  if (latest && !currentLocation.value) {
    currentLocation.value = latest;
    lastUpdateTime.value = Date.now();
  }
  return currentLocation.value;
}

export function useCurrentLocation() {
  return {
    location: readonly(currentLocation),
    lastUpdateTime: readonly(lastUpdateTime),
    hasLocation: computed(() => currentLocation.value !== null),
  };
}
