import { FetchError } from 'ofetch';

export function getErrorMessage(error: FetchError | string | null | undefined): string | null {
  if (!error) return null;
  if (typeof error === 'string') return error;

  if (error.name === 'TimeoutError' || (error.cause as any)?.name === 'TimeoutError') {
    return 'Request timed out. Please try again.';
  }

  if (error.statusCode && error.statusCode >= 500) {
    return error.data?.detail || 'Server error. Please try again later.';
  }

  return error.data?.detail || error.message || null;
}
