import { Capacitor } from '@capacitor/core';

let state: 'idle' | 'initializing' | 'initialized' = 'idle';
// `state` resets to 'idle' on each return to the login layout, so a logout→login cycle re-runs
// initialization within the same process. The previous-exit report must fire only once per
// process, otherwise a re-login re-sends a duplicate app_termination event (and on iOS the
// graceful marker — cleared on the first read — is gone for the second report).
let exitReasonReported = false;

export default defineNuxtRouteMiddleware(async (to) => {
  if (to.meta.layout === 'login' && state === 'initialized') {
    state = 'idle';
    return;
  }
  if (state !== 'idle') return;
  if (!Capacitor.isNativePlatform()) return;

  const { isAuthenticated } = useUserRole();
  if (!isAuthenticated.value) return;

  state = 'initializing';

  const { initialize, reportLastExitReason, restoreAfterTermination } = useNuxtApp().$mobile;
  try {
    await initialize();
    // Must run before restoreAfterTermination — resuming tracking re-arms the clean-shutdown flag.
    // Once per process only (see `exitReasonReported` above).
    if (!exitReasonReported) {
      exitReasonReported = true;
      await reportLastExitReason();
    }
    await restoreAfterTermination();
    state = 'initialized';
  } catch (err) {
    state = 'idle';
    console.error('[Mobile] Initialization error:', err);
  }
});
