import type { CookieRef } from '#app';
import { config } from '~/config/auth';
import { isTokenExpired } from '~/utils/authTokenExpiry';
import { Capacitor } from '@capacitor/core';
import { KeychainAccess, SecureStorage } from '@aparajita/capacitor-secure-storage';

const keychainAccess = KeychainAccess.afterFirstUnlock;

export interface UseAuthStateReturn extends CommonUseAuthStateReturn<SessionData> {
  token: ComputedRef<string | null>;
  rawToken: ComputedRef<string | null>;
  refreshToken: ComputedRef<string | null>;
  rawRefreshToken: ComputedRef<string | null>;
  setToken: (newToken: string | null) => void;
  clearToken: () => void;
  setRefreshToken: (newToken: string | null) => void;
  clearRefreshToken: () => void;
  hydrateFromSecureStorage: () => Promise<void>;
  _internal: {
    rawTokenCookie: CookieRef<string | null>;
    rawRefreshTokenCookie: CookieRef<string | null>;
  };
}

export function useAuthState(): UseAuthStateReturn {
  const isNative = Capacitor.isNativePlatform();
  const hostname = useRequestURL().hostname;

  // Web storage: cookies
  const rawTokenCookie = useCookie<string | null>(config.token.name, {
    domain: hostname,
    maxAge: config.token.maxAgeInSeconds,
    sameSite: config.token.sameSiteAttribute,
    secure: config.token.secureCookieAttribute,
    httpOnly: config.token.httpOnlyCookieAttribute,
    watch: 'shallow',
  });

  const rawRefreshTokenCookie = useCookie<string | null>(config.refreshToken.name, {
    domain: hostname,
    maxAge: config.refreshToken.maxAgeInSeconds,
    sameSite: config.refreshToken.sameSiteAttribute,
    secure: config.refreshToken.secureCookieAttribute,
    httpOnly: config.refreshToken.httpOnlyCookieAttribute,
    watch: 'shallow',
  });

  // Native storage: in-memory refs mirroring SecureStorage
  const nativeToken = useState<string | null>('auth:nativeToken', () => null);
  const nativeRefreshToken = useState<string | null>('auth:nativeRefreshToken', () => null);

  // Unified raw token access (platform-aware)
  const rawToken = computed(() => (isNative ? nativeToken.value : rawTokenCookie.value));
  const rawRefreshToken = computed(() => (isNative ? nativeRefreshToken.value : rawRefreshTokenCookie.value));

  function setToken(token: string | null) {
    if (isNative) {
      nativeToken.value = token;
      if (token) {
        SecureStorage.set(config.token.name, token, false, false, keychainAccess);
      } else {
        SecureStorage.remove(config.token.name, false);
      }
    } else {
      rawTokenCookie.value = token;
    }
  }

  function clearToken() {
    setToken(null);
  }

  function setRefreshToken(token: string | null) {
    if (isNative) {
      nativeRefreshToken.value = token;
      if (token) {
        SecureStorage.set(config.refreshToken.name, token, false, false, keychainAccess);
      } else {
        SecureStorage.remove(config.refreshToken.name, false);
      }
    } else {
      rawRefreshTokenCookie.value = token;
    }
  }

  function clearRefreshToken() {
    setRefreshToken(null);
  }

  async function hydrateFromSecureStorage() {
    if (!isNative) return;
    try {
      const [accessResult, refreshResult] = await Promise.all([
        SecureStorage.get(config.token.name, false, false),
        SecureStorage.get(config.refreshToken.name, false, false),
      ]);
      nativeToken.value = (accessResult as string) ?? null;
      nativeRefreshToken.value = (refreshResult as string) ?? null;
    } catch (e) {
      console.error('[AUTH] Failed to hydrate tokens from SecureStorage:', e);
      nativeToken.value = null;
      nativeRefreshToken.value = null;
    }
  }

  const token = computed(() => {
    if (!rawToken.value) return null;
    return `Bearer ${rawToken.value}`;
  });

  const refreshToken = computed(() => {
    return rawRefreshToken.value;
  });

  const data = useState<SessionData | undefined | null>('auth:data', () => undefined);

  const hasInitialSession = computed(() => {
    if (!rawToken.value) return false;
    return !isTokenExpired(rawToken.value);
  });

  // If session exists, initialize as already synced
  const lastRefreshedAt = useState<SessionLastRefreshedAt>('auth:lastRefreshedAt', () => {
    if (hasInitialSession.value) {
      return new Date();
    }

    return undefined;
  });

  // If session exists, initialize as not loading
  const loading = useState<boolean>('auth:loading', () => false);
  const status = computed<SessionStatus>(() => {
    if (hasInitialSession.value) {
      return 'authenticated';
    }
    if (loading.value) {
      return 'loading';
    }
    return 'unauthenticated';
  });

  return {
    data,
    loading,
    lastRefreshedAt,
    status,
    token,
    rawToken,
    refreshToken,
    rawRefreshToken,
    setToken,
    clearToken,
    setRefreshToken,
    clearRefreshToken,
    hydrateFromSecureStorage,
    _internal: {
      rawTokenCookie: rawTokenCookie,
      rawRefreshTokenCookie: rawRefreshTokenCookie,
    },
  };
}
