import { Capacitor } from '@capacitor/core';
import { SwipeBack } from 'swipe-back-plugin';

export default defineNuxtPlugin(() => {
  // Provided on all platforms so callers don't need platform guards
  const disableSwipeGestures = () => {};

  if (!Capacitor.isNativePlatform() || Capacitor.getPlatform() !== 'ios') {
    return { provide: { disableSwipeGestures } };
  }

  const router = useRouter();
  SwipeBack.enable();

  const updateGestures = () => {
    const back = !!window.history.state?.back;
    const forward = !!window.history.state?.forward;
    SwipeBack.setCanNavigate({ back, forward });
  };

  // history.state is already updated when afterEach fires — no nextTick needed
  router.afterEach(updateGestures);
  updateGestures();

  let didNavigate = false;

  const startedHandlePromise = SwipeBack.addListener('swipeStarted', ({ direction }) => {
    didNavigate = false;
    if (direction === 'back' && window.history.state?.back) {
      didNavigate = true;
      router.back();
    } else if (direction === 'forward' && window.history.state?.forward) {
      didNavigate = true;
      router.forward();
    }
  });

  const cancelledHandlePromise = SwipeBack.addListener('swipeCancelled', ({ direction }) => {
    if (!didNavigate) return;
    didNavigate = false;
    if (direction === 'back') {
      router.forward();
    } else {
      router.back();
    }
  });

  return {
    provide: {
      // Call this after any programmatic redirect that leaves authenticated pages
      // behind in the history stack (e.g. sign-out). replace:true only swaps the
      // current entry; earlier entries remain and would otherwise enable back swipe.
      disableSwipeGestures: () => SwipeBack.setCanNavigate({ back: false, forward: false }),
    },
    teardown() {
      return Promise.all([
        startedHandlePromise.then((h) => h.remove()),
        cancelledHandlePromise.then((h) => h.remove()),
      ]);
    },
  };
});
