import type { MobileModule } from '~/types/mobile/module';
import type { startStatus } from '~/types/mobile/trackingStartStatus';

export type UploadProgress = { isUploading: boolean; total: number; uploaded: number };

const _modules = ref<MobileModule[]>([]);
const _startStatus = ref<startStatus>('idle');
const _hasNetworkError = ref(false);
const _permissionsMissing = ref(false);
const _isTracking = ref(false);
const _isPaused = ref(false);
const _usingMicrophone = ref(false);
const _unsyncedShiftIds = ref<string[]>([]);
const _isAppForeground = ref(true);
const _uploadProgress = ref<UploadProgress>({ isUploading: false, total: 0, uploaded: 0 });
const _lastUploadHadErrors = ref(false);

export function setIsTracking(val: boolean): void {
  _isTracking.value = val;
}

export function setIsPaused(val: boolean): void {
  _isPaused.value = val;
}

export function setUsingMicrophone(val: boolean): void {
  _usingMicrophone.value = val;
}

export function setUnsyncedShiftIds(val: string[]): void {
  _unsyncedShiftIds.value = val;
}

export function setPermissionsMissing(val: boolean): void {
  _permissionsMissing.value = val;
}

export function setIsAppForeground(val: boolean): void {
  _isAppForeground.value = val;
}

export function setUploadProgress(val: UploadProgress): void {
  _uploadProgress.value = val;
}

export function setLastUploadHadErrors(val: boolean): void {
  _lastUploadHadErrors.value = val;
}

export function incrementUploadProgress(amount: number): void {
  if (amount <= 0) return;
  const next = _uploadProgress.value.uploaded + amount;
  _uploadProgress.value = {
    ..._uploadProgress.value,
    uploaded: _uploadProgress.value.total > 0 ? Math.min(next, _uploadProgress.value.total) : next,
  };
}

export type RuntimeState = {
  modules: Ref<MobileModule[]>;
  startStatus: Ref<startStatus>;
  hasNetworkError: Ref<boolean>;
  permissionsMissing: Ref<boolean>;
  isTracking: Ref<boolean>;
  isPaused: Ref<boolean>;
  usingMicrophone: Ref<boolean>;
  unsyncedShiftIds: Ref<string[]>;
  isAppForeground: Ref<boolean>;
  uploadProgress: Ref<UploadProgress>;
  lastUploadHadErrors: Ref<boolean>;
};

export function useMobileRuntimeState(): RuntimeState {
  return {
    modules: _modules,
    startStatus: _startStatus,
    hasNetworkError: _hasNetworkError,
    permissionsMissing: _permissionsMissing,
    isTracking: _isTracking,
    isPaused: _isPaused,
    usingMicrophone: _usingMicrophone,
    unsyncedShiftIds: _unsyncedShiftIds,
    isAppForeground: _isAppForeground,
    uploadProgress: _uploadProgress,
    lastUploadHadErrors: _lastUploadHadErrors,
  };
}
