import type { AudioRecordingPermission } from '~/client';
import type { Feature, Polygon, MultiPolygon } from 'geojson';
import type { MobileLocation } from '~/types/mobile/location';

export type RestrictedZone = Feature<Polygon | MultiPolygon, { zipCode: string }>;

export const AUDIO_RECORDING_PERMISSION: Record<string, AudioRecordingPermission> = {
  FULL_RECORDING: 'full_recording',
  NO_RECORDING: 'no_recording',
  FULL_RECORDING_WITH_RESTRICTED_AREA: 'full_recording_with_restricted_area',
} as const;

export interface RestrictionCheckResult {
  isRestricted: boolean;
  distanceToNearestZoneKm: number | null;
  nearestZoneId: string | null;
}

export interface RestrictionStatus {
  isRestricted: boolean;
  isApproaching: boolean;
  distanceKm: number | null;
}

export interface RestrictionStatusEntry {
  isRestricted: boolean;
  hasCoverage: boolean;
  timestamp: number;
  point: MobileLocation;
}

export interface ProjectState {
  zones: RestrictedZone[];
  centerPoint: MobileLocation | null;
  fetchRadiusKm: number;
  lastFetchedAt: number | null;
  nextRetryAfter: number | null;
  permission: AudioRecordingPermission | null;
  isLoading: boolean;
  error: Error | null;
  status: RestrictionStatus;
  recentRestrictionStatuses: RestrictionStatusEntry[];
}
