import { v4 as uuidv4 } from 'uuid';
import type { WakeWordDetectionEvent } from 'audio-manager-plugin';
import type { WakeWordEventRequest } from '~/client';
import { addPayloadReturningId, deletePayloadsByIds } from '~/utils/useDb';
import { sendWakeWordEvent } from '~/mutations/mobile/sendWakeWordEvent';
import { MESSAGE_TYPES } from '~/types/mobile/trackingSensors';
import { uploadWakeWordClipNative } from '~/utils/mobile/uploadWakeWordClipNative';

export function createWakeWordHandler(shiftId: string, deviceId: string) {
  async function handle(evt: WakeWordDetectionEvent): Promise<void> {
    const gpsRaw = evt.gps_point;
    const gps_point = gpsRaw ? { ...gpsRaw, timestamp: new Date(gpsRaw.timestamp).toISOString() } : null;

    const eventId = uuidv4();
    const payload: WakeWordEventRequest = {
      id: eventId,
      work_shift_id: shiftId,
      device_id: deviceId,
      timestamp_ms: evt.timestampMs,
      gps_point,
    };

    // If DB write throws, the event is lost (no retry, no network call) — inherited behavior
    const rowId = await addPayloadReturningId(MESSAGE_TYPES.wake_word_event, payload);

    try {
      await sendWakeWordEvent(payload);
      if (rowId > 0) await deletePayloadsByIds([rowId]);
    } catch {
      // Left in payloads table for uploader retry
    }

    // Upload the raw clip on the binary path, joined to the event by id. If the event row has
    // not landed yet the endpoint 404s and native caches the clip for retry; offline likewise.
    if (evt.clipId && evt.clipStartMs != null && evt.clipEndMs != null) {
      try {
        await uploadWakeWordClipNative({
          clipId: evt.clipId,
          eventId,
          workShiftId: shiftId,
          deviceId,
          clipStartMs: evt.clipStartMs,
          clipEndMs: evt.clipEndMs,
        });
      } catch (err) {
        console.warn('[wakeWord] clip upload failed; will retry from cache', err);
      }
    }
  }

  return { handle };
}
