import { AudioManager } from 'audio-manager-plugin';
import type { ReceiveWakeWordAudioClipData, ReceiveCachedWakeWordAudioClipsData } from '~/client';
import {
  saveWakeWordClip,
  fetchCachedWakeWordClips,
  deleteCachedWakeWordClipsByIds,
  cachedWakeWordClips,
} from '~/utils/useDb';
import { makeCacheTtlCleanup, uploadCachedGroups, type CachedUploadGroup } from '~/utils/mobile/offlineAudioCache';
import { isDbInitialized } from '~/utils/dbManager';

const clipUrl: ReceiveWakeWordAudioClipData['url'] = '/api/canvasser_voice/wake_word_audio';
const clipCachedUrl: ReceiveCachedWakeWordAudioClipsData['url'] = '/api/canvasser_voice/wake_word_audio_cached';

// Expire cached wake-word clips the same way `checkAudioCacheTTL` expires cached VAD audio
// (both are built by `makeCacheTtlCleanup`), so clips that can never upload (e.g. a
// permanently-mismatched device_id) don't accumulate on disk forever — the dedicated
// `cached_wake_word_clips` table has no other cleanup path.
export const checkWakeWordClipCacheTTL = makeCacheTtlCleanup({
  label: 'checkWakeWordClipCacheTTL',
  cols: () => cachedWakeWordClips.cols,
  fetchItems: fetchCachedWakeWordClips,
  deleteByIds: deleteCachedWakeWordClipsByIds,
  precondition: isDbInitialized,
});

export async function uploadWakeWordClipNative(opts: {
  clipId: string;
  eventId: string;
  workShiftId: string;
  deviceId: string;
  clipStartMs: number;
  clipEndMs: number;
}): Promise<void> {
  const { token } = useAuth();
  const url = useRuntimeConfig().public.apiBaseURL + clipUrl;
  const resp = await AudioManager.uploadWakeWordClip({
    url,
    token: token.value as string,
    clipId: opts.clipId,
    eventId: opts.eventId,
    workShiftId: opts.workShiftId,
    deviceId: opts.deviceId,
    clipStartMs: opts.clipStartMs,
    clipEndMs: opts.clipEndMs,
  });

  if (resp?.cachedPath) {
    const filename = resp.cachedPath.split('/').pop()!;
    await saveWakeWordClip(
      {
        eventId: resp.eventId ?? opts.eventId,
        workShiftId: opts.workShiftId,
        deviceId: opts.deviceId,
        clipStartMs: resp.clipStartMs ?? opts.clipStartMs,
        clipEndMs: resp.clipEndMs ?? opts.clipEndMs,
      },
      filename
    );
  }
}

export async function uploadCachedWakeWordClipsIfExists(): Promise<void> {
  await checkWakeWordClipCacheTTL();

  const { token } = useAuth();
  const url = useRuntimeConfig().public.apiBaseURL + clipCachedUrl;

  const items = await fetchCachedWakeWordClips([
    cachedWakeWordClips.cols.id,
    cachedWakeWordClips.cols.audioPath,
    cachedWakeWordClips.cols.metadata,
  ]);
  if (!items?.length) return;

  type DeviceGroup = {
    ids: number[];
    audioPath: string[];
    clips: Array<{ eventId: string; workShiftId: string; clipStartMs: number; clipEndMs: number }>;
  };
  const byDevice = new Map<string, DeviceGroup>();

  for (const item of items) {
    const deviceId = item.deviceId;
    let group = byDevice.get(deviceId);
    if (!group) {
      group = { ids: [], audioPath: [], clips: [] };
      byDevice.set(deviceId, group);
    }
    group.ids.push(item[cachedWakeWordClips.cols.id]);
    group.audioPath.push(item[cachedWakeWordClips.cols.audioPath]);
    group.clips.push({
      eventId: item.eventId,
      workShiftId: item.workShiftId,
      clipStartMs: item.clipStartMs,
      clipEndMs: item.clipEndMs,
    });
  }

  // Upload each device group sequentially; a failed group is left cached for the next
  // retry while the remaining device groups still get their chance.
  const groups: CachedUploadGroup[] = Array.from(byDevice, ([deviceId, group]) => ({
    ids: group.ids,
    upload: () =>
      AudioManager.uploadCachedWakeWordClips({
        url,
        token: token.value as string,
        deviceId,
        audioPath: group.audioPath,
        clips: group.clips,
      }),
  }));

  await uploadCachedGroups('uploadCachedWakeWordClipsIfExists', groups, deleteCachedWakeWordClipsByIds);
}
