import { createAudioRecorder } from '~/composables/mobile/audio/useMobileAudioManager';

type Recorder = ReturnType<typeof createAudioRecorder>;

export const useRecorderStore = defineStore('vadRecorder', () => {
  const recorder = shallowRef<Recorder | null>(null);
  let currentShiftId: string | null = null;

  function init(shiftId: string, deviceId: string) {
    if (recorder.value && currentShiftId === shiftId) return;
    currentShiftId = shiftId;
    recorder.value = createAudioRecorder(shiftId, deviceId);
  }

  async function start() {
    await recorder.value?.start();
  }
  async function stop() {
    await recorder.value?.stop();
  }
  async function clear() {
    await recorder.value?.clear();
  }
  async function sendFullBuffer() {
    if (!recorder.value) return { ok: false, uploadedBytes: 0 };
    return recorder.value.sendFullBuffer();
  }
  const name = 'audio' as const;
  const isAlive = () => recorder.value?.isAlive() ?? false;

  return { name, recorder, init, start, stop, isAlive, clear, sendFullBuffer };
});
