import { Preferences } from '@capacitor/preferences';
import type { SelectorProjectItem } from '~/client';

const STORAGE_KEY = 'selectedWorkShiftProject';

const _project = ref<SelectorProjectItem | null>(null);
const _loaded = ref(false);

// Only validates id + name. Fields added after initial release (e.g. audio_recording_config)
// may be missing from projects stored before an app update. Callers that depend on optional
// fields must handle undefined gracefully.
function parseProject(raw: string | null): SelectorProjectItem | null {
  if (!raw) return null;
  try {
    const p = JSON.parse(raw);
    if (typeof p?.id === 'string' && p.id && typeof p?.name === 'string' && p.name) {
      return p as SelectorProjectItem;
    }
    return null;
  } catch {
    return null;
  }
}

export function useWorkShiftProject() {
  const project = computed(() => _project.value);

  async function load(): Promise<SelectorProjectItem | null> {
    if (_loaded.value) return _project.value;
    const { value } = await Preferences.get({ key: STORAGE_KEY });
    _project.value = parseProject(value);
    _loaded.value = true;
    return _project.value;
  }

  async function save(project: SelectorProjectItem | null): Promise<void> {
    _project.value = project;
    if (project) {
      await Preferences.set({ key: STORAGE_KEY, value: JSON.stringify(project) });
    } else {
      await Preferences.remove({ key: STORAGE_KEY });
    }
  }

  return { project, load, save };
}
