import type { HttpOptions } from '@capacitor/core';
import type { MobileDeviceUpdateInfoRequest, MobileDeviceUpdateInfoResponse, DeviceInfoUpdateData } from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function uploadDeviceInfo(
  payload: MobileDeviceUpdateInfoRequest
): Promise<MobileDeviceUpdateInfoResponse> {
  const url: DeviceInfoUpdateData['url'] = '/api/mobile/device/update_info';
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<MobileDeviceUpdateInfoResponse>(options, 'UploadDeviceInfo');
}
