import { App } from '@capacitor/app';
import { Capacitor } from '@capacitor/core';

import { getUpdateInfo } from '~/mutations/mobile/getUpdateInfo';

export async function checkVersion(currentBundle: any) {
  const currentPlatform = Capacitor.getPlatform();

  const appInfo = await App.getInfo();
  const fv = useRuntimeConfig().public.version;

  try {
    return await getUpdateInfo({
      // @ts-expect-error
      platform: currentPlatform,
      native_version: appInfo.version,
      native_build_number: appInfo.build,
      frontend_version: fv,
      current_bundle_id: currentBundle,
    });
  } catch (error) {
    console.error('[VersionCheck] Failed to get update info:', error);
    throw error;
  }
}
