import { useMobileRemoteConfig } from '~/composables/mobile/config/useMobileRemoteConfig';
import type { AppConfig } from '~/types/database/config';
import { AppConfigKeys, DefaultAppConfig } from '~/types/database/config';
import { getConfig, updateConfig } from '~/utils/useDb';

let _configRef: Ref<AppConfig> | null = null;

// Returns DefaultAppConfig if called before initConfig() — this is intentional as a safe fallback.
export function getAppConfig(): AppConfig {
  if (!_configRef) _configRef = ref<AppConfig>(DefaultAppConfig);
  return _configRef.value;
}

export const useMobileConfig = () => {
  const { loadRemoteConfig } = useMobileRemoteConfig();
  if (!_configRef) _configRef = ref<AppConfig>(DefaultAppConfig);

  async function initConfig() {
    const local = await getConfig().catch(() => null);
    if (local) _configRef!.value = local;
    const remote = await fetchAndSync();
    if (remote) _configRef!.value = remote;
  }

  async function fetchAndSync(): Promise<AppConfig | null> {
    const remote = await loadRemoteConfig().catch(() => null);
    if (!remote) return null;

    if (hasConfigChanged(remote)) {
      _configRef!.value = remote;
      await updateConfig(remote);
      console.debug('[MobileConfig] Config changed, emitted app-config-updated');
    }
    return remote;
  }

  function hasConfigChanged(remote: AppConfig): boolean {
    return AppConfigKeys.some((k) => remote[k] !== _configRef!.value[k]);
  }

  return { initConfig, fetchAndSync };
};
