import { AudioManager } from 'audio-manager-plugin';
import { getAppConfig } from '~/composables/mobile/config/useMobileConfig';

type TtlColumns = { id: string; createdAt: string; audioPath: string };

export type TtlSweepResult = {
  audioPaths: string[];
  indices: number[];
  scanned: number;
  error?: unknown;
};

// One TTL-expiry pass over a cached-audio table: deletes rows older than
// `AudioCacheTTLDays` from both the native chunk store and the SQLite index.
// Never throws — errors are caught and returned so callers can add telemetry.
async function expireCachedAudioByTtl(opts: {
  label: string;
  cols: () => TtlColumns;
  fetchItems: (columns: string[]) => Promise<any[] | null>;
  deleteByIds: (ids: number[]) => Promise<void>;
}): Promise<TtlSweepResult> {
  const { label, fetchItems, deleteByIds } = opts;
  const cols = opts.cols();
  const indices: number[] = [];
  const audioPaths: string[] = [];

  try {
    const items = await fetchItems([cols.id, cols.createdAt, cols.audioPath]);
    if (!items?.length) return { audioPaths, indices, scanned: 0 };

    const ttlDays = getAppConfig().AudioCacheTTLDays;
    const now = new Date();
    for (const item of items) {
      const expireAt = new Date(item[cols.createdAt]);
      expireAt.setDate(expireAt.getDate() + ttlDays);
      if (now >= expireAt) {
        indices.push(item[cols.id]);
        audioPaths.push(item[cols.audioPath]);
      }
    }

    if (audioPaths.length > 0) {
      await AudioManager.deleteCachedChunksByIds({ audioPaths });
      await deleteByIds(indices);
      console.info(`[${label}] Deleted ${audioPaths.length} expired cached audio.`);
    }
    return { audioPaths, indices, scanned: items.length };
  } catch (error) {
    console.error(`[${label}] Failed to cleanup audio cache:`, error);
    return { audioPaths, indices, scanned: 0, error };
  }
}

// Build the guarded TTL-cleanup function for one cache: skips while another sweep is
// already running and when `precondition` says the environment isn't ready (e.g. DB not
// initialized on the login page), and reports each finished sweep to `onResult`.
export function makeCacheTtlCleanup(opts: {
  label: string;
  cols: () => TtlColumns;
  fetchItems: (columns: string[]) => Promise<any[] | null>;
  deleteByIds: (ids: number[]) => Promise<void>;
  precondition?: () => boolean;
  onResult?: (result: TtlSweepResult) => void;
}): () => Promise<void> {
  let inProgress = false;
  return async (): Promise<void> => {
    if (opts.precondition && !opts.precondition()) return;
    if (inProgress) return;
    inProgress = true;
    try {
      const result = await expireCachedAudioByTtl(opts);
      opts.onResult?.(result);
    } finally {
      inProgress = false;
    }
  };
}

export type CachedUploadGroup = {
  ids: number[];
  upload: () => Promise<{ success?: boolean; succeededIndices?: number[] } | null | undefined>;
};

// Shared retry-upload loop: run each group's native upload and delete the index rows the
// backend acknowledged. succeededIndices are positions within the group's arrays (post
// native missing-file filter + remap), so they are mapped back to DB row ids here.
export async function uploadCachedGroups(
  label: string,
  groups: CachedUploadGroup[],
  deleteByIds: (ids: number[]) => Promise<void>,
  opts: { onFailure?: () => Promise<void>; stopOnFailure?: boolean } = {}
): Promise<void> {
  for (const [i, group] of groups.entries()) {
    const resp = await group.upload();
    console.debug(`[${label}] group ${i + 1}/${groups.length} response: ${JSON.stringify(resp)}`);
    if (resp?.success) {
      const succeeded = resp.succeededIndices ?? [];
      await deleteByIds(succeeded.map((idx) => group.ids[idx]).filter((id): id is number => id != null));
    } else {
      await opts.onFailure?.();
      if (opts.stopOnFailure) break;
    }
  }
}
