import { Preferences } from '@capacitor/preferences';
import { getWorkShiftStatus } from '~/mutations/mobile/getWorkShiftStatus';

import { ref, computed } from 'vue';
import { useIntervalFn } from '@vueuse/core';

// --- Storage keys ---

const CURRENT_WORK_SHIFT_START_TIME = 'current_work_shift_start_time';
const BREAK_ACCUMULATED_MS = 'break_accumulated_ms';
const BREAK_SEGMENT_START = 'break_segment_start';
const SHIFT_LAST_BREAK_KEY = 'shift_last_break_time';

// --- Storage helpers ---

async function getCurrentWorkShiftStartTime(): Promise<Date | null> {
  const preference = await Preferences.get({ key: CURRENT_WORK_SHIFT_START_TIME });
  console.debug('Getting work shift start time from preferences storage. Time:', preference.value);
  if (!preference.value) return null;
  return new Date(Number(preference.value));
}

async function setCurrentWorkShiftStartTime(value: Date): Promise<void> {
  console.debug('Setting work shift time to preferences storage. Time:', value);
  await Preferences.set({ key: CURRENT_WORK_SHIFT_START_TIME, value: value.valueOf().toString() });
}

async function removeCurrentWorkShiftStartTime(): Promise<void> {
  console.debug('Removing work shift start time from preferences storage');
  await Preferences.remove({ key: CURRENT_WORK_SHIFT_START_TIME });
}

async function getStoredAccumulatedMs(): Promise<number> {
  const preference = await Preferences.get({ key: BREAK_ACCUMULATED_MS });
  return preference.value ? Number(preference.value) : 0;
}

async function setStoredAccumulatedMs(value: number): Promise<void> {
  await Preferences.set({ key: BREAK_ACCUMULATED_MS, value: value.toString() });
}

async function removeStoredAccumulatedMs(): Promise<void> {
  await Preferences.remove({ key: BREAK_ACCUMULATED_MS });
}

async function getStoredSegmentStart(): Promise<number | null> {
  const preference = await Preferences.get({ key: BREAK_SEGMENT_START });
  return preference.value ? Number(preference.value) : null;
}

async function setStoredSegmentStart(value: number): Promise<void> {
  await Preferences.set({ key: BREAK_SEGMENT_START, value: value.toString() });
}

async function removeStoredSegmentStart(): Promise<void> {
  await Preferences.remove({ key: BREAK_SEGMENT_START });
}

async function getStoredLastBreakTime(): Promise<string | null> {
  const preference = await Preferences.get({ key: SHIFT_LAST_BREAK_KEY });
  return preference.value ?? null;
}

async function setStoredLastBreakTime(value: string): Promise<void> {
  await Preferences.set({ key: SHIFT_LAST_BREAK_KEY, value });
}

async function removeStoredLastBreakTime(): Promise<void> {
  await Preferences.remove({ key: SHIFT_LAST_BREAK_KEY });
}

// --- Formatting ---

function formatDuration(ms: number): string {
  if (ms >= 0) {
    const totalSeconds = Math.max(0, Math.floor(ms / 1000));
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;

    const pad = (n: number) => n.toString().padStart(2, '0');
    return `${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
  } else {
    return '00:00:00';
  }
}

// --- Composable ---

export function useWorkShiftTimer() {
  const shiftStartTime = ref<string | null>(null);
  const lastBreakTime = ref<string | null>(null);
  const accumulatedBreakMs = ref(0);
  const breakSegmentStart = ref<number | null>(null);
  const now = ref(Date.now());

  // Single interval — always runs while shift is active (tracking or paused).
  // During a break: netElapsed = (now - shiftStart) - breakElapsed is constant because
  // now and breakSegmentStart grow at the same rate, so the main display auto-freezes.
  const { pause: pauseInterval, resume: resumeInterval } = useIntervalFn(
    () => {
      now.value = Date.now();
    },
    1000,
    { immediate: false }
  );

  // Break elapsed: grows while on break, frozen otherwise
  const breakElapsedMs = computed(() => {
    if (breakSegmentStart.value === null) return accumulatedBreakMs.value;
    return accumulatedBreakMs.value + Math.max(0, now.value - breakSegmentStart.value);
  });

  // Net shift time: auto-freezes during break, ticks when actively tracking
  const elapsedMs = computed(() => {
    if (!shiftStartTime.value) return 0;
    const start = new Date(shiftStartTime.value).getTime();
    return Math.max(0, now.value - start - breakElapsedMs.value);
  });

  const formattedDuration = computed(() => formatDuration(elapsedMs.value));
  const breakFormattedDuration = computed(() => formatDuration(breakElapsedMs.value));

  async function init(startTime: Date) {
    if (shiftStartTime.value !== null) {
      console.debug('[MobileShiftTimer] Timer already initialized');
      return;
    }
    shiftStartTime.value = startTime.toISOString();
    now.value = Date.now();
    resumeInterval();
    await setCurrentWorkShiftStartTime(startTime);
  }

  async function ensureInitialised() {
    if (shiftStartTime.value) return;

    const startTime = await getCurrentWorkShiftStartTime();
    if (startTime) {
      shiftStartTime.value = startTime.toISOString();
    } else {
      try {
        const response = await getWorkShiftStatus();
        shiftStartTime.value = response?.start_time ?? null;
      } catch (error: unknown) {
        console.error('[MobileShiftTimer] Failed to get start time of the work shift:', error);
      }
    }

    accumulatedBreakMs.value = await getStoredAccumulatedMs();
    const storedSegmentStart = await getStoredSegmentStart();
    if (storedSegmentStart !== null) {
      breakSegmentStart.value = storedSegmentStart;
    }
    lastBreakTime.value = await getStoredLastBreakTime();

    if (shiftStartTime.value !== null) {
      now.value = Date.now();
      resumeInterval();
    }
  }

  // Called when shift is paused — update now immediately to avoid stale reads
  async function startBreak() {
    if (breakSegmentStart.value !== null) return;
    now.value = Date.now();
    const start = now.value;
    breakSegmentStart.value = start;
    await setStoredSegmentStart(start);
    const breakTime = new Date().toISOString();
    lastBreakTime.value = breakTime;
    await setStoredLastBreakTime(breakTime);
  }

  // Called when shift is resumed — update now immediately to eliminate lag
  async function endBreak() {
    now.value = Date.now();
    if (breakSegmentStart.value !== null) {
      const raw = now.value - breakSegmentStart.value;
      if (raw < 0) {
        console.warn('[MobileShiftTimer] Negative break segment detected — possible clock adjustment. raw=', raw);
      }
      accumulatedBreakMs.value += Math.max(0, raw);
      breakSegmentStart.value = null;
      await removeStoredSegmentStart();
      await setStoredAccumulatedMs(accumulatedBreakMs.value);
    }
  }

  // Called when shift ends — clears all break data
  async function resetBreak() {
    accumulatedBreakMs.value = 0;
    breakSegmentStart.value = null;
    await removeStoredAccumulatedMs();
    await removeStoredSegmentStart();
  }

  async function destroy() {
    pauseInterval();
    shiftStartTime.value = null;
    lastBreakTime.value = null;
    await resetBreak();
    await removeCurrentWorkShiftStartTime();
    await removeStoredLastBreakTime();
  }

  return {
    init,
    ensureInitialised,
    destroy,
    startBreak,
    endBreak,
    resetBreak,
    elapsedMs,
    formattedDuration,
    breakFormattedDuration,
    shiftStartTime,
    lastBreakTime,
  };
}
