function camelToSnake(key: string): string {
  return key
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2')
    .toLowerCase();
}

export function deepKeysToSnakeCase(value: any): any {
  if (Array.isArray(value)) return value.map(deepKeysToSnakeCase);

  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [camelToSnake(k), deepKeysToSnakeCase(v)]));
  }

  return value;
}
