import { useAuthState } from './useAuthState';
import {
  drainPendingRefresh,
  pendingRefresh as _pendingRefresh,
  setSigningOut,
  singleFlightRefresh,
} from './refreshSingleFlight';
import { config } from '~/config/auth';
import { Capacitor, type HttpHeaders } from '@capacitor/core';
import { doMobileRequest, doWebRequest } from '#imports';
import { servingOffline } from '~/utils/offlineCache';
import { unlinkIfNative } from '~/utils/mobile/unlinkDeviceFromUser';
import type {
  CreateAuthTokenResponse,
  AuthLogoutResponse,
  GetProfileResponse,
  RefreshAuthTokenResponse,
} from '~/client';

interface Credentials extends Record<string, any> {
  username?: string;
  email?: string;
  password?: string;
}

export interface SignInFunc<T = Record<string, any>> {
  (
    credentials: Credentials,
    signInOptions?: SecondarySignInOptions,
    paramsOptions?: Record<string, string>,
    headersOptions?: Record<string, string>
  ): Promise<T | undefined>;
}

export interface SignOutFunc<T = unknown> {
  (options?: SignOutOptions): Promise<T | undefined>;
}

interface UseAuthReturn extends CommonUseAuthReturn<SignInFunc, SignOutFunc, SessionData> {
  token: Readonly<Ref<string | null>>;
  refreshToken: Readonly<Ref<string | null>>;
  refreshing: Readonly<Ref<boolean>>;
  pendingRefresh: () => Promise<SessionData | null | void> | null;
}

export function useAuth(): UseAuthReturn {
  const isNative = Capacitor.isNativePlatform();
  const {
    setToken,
    clearToken,
    setRefreshToken,
    clearRefreshToken,
    data,
    loading,
    status,
    lastRefreshedAt,
    token,
    refreshToken,
  } = useAuthState();

  const refreshing = useState<boolean>('auth:refreshing', () => false);

  interface ExtendedSecondarySignInOptions extends SecondarySignInOptions {
    callbackBeforNavigation?: () => Promise<void>;
  }

  async function signIn<T>(
    credentials: Credentials,
    signInOptions?: ExtendedSecondarySignInOptions,
    signInParams?: Record<string, string>,
    signInHeaders?: Record<string, string>
  ): Promise<T | undefined> {
    const { path, method } = config.endpoints.signIn;

    //in case we have FormData hear, using web request that works in foreground
    const response = await doWebRequest<CreateAuthTokenResponse>(path, {
      method,
      body: credentials,
      headers: signInHeaders ?? {},
      // params: signInParams ?? {},
    });

    if (typeof response !== 'object' || response === null) {
      console.error(`[AUTH] signIn returned non-object value`);
      showToastError('Failed to sign in.');
      return;
    }

    setToken(response.access_token);
    setRefreshToken(response.refresh_token);

    const { callbackUrl, callGetSession = true, callbackBeforNavigation } = signInOptions ?? {};

    if (callGetSession) {
      await getSession();
    }

    if (callbackBeforNavigation) {
      try {
        await callbackBeforNavigation();
      } catch (e) {
        console.error('Error in callbackBeforNavigation:', e);
      }
    }

    if (callbackUrl) {
      await navigateTo(callbackUrl, { replace: true });
    } else {
      await navigateTo(getSafeRedirectUrl(useRoute()), { replace: true });
    }
    useNuxtApp().$disableSwipeGestures();

    return response as unknown as T;
  }

  async function signOut<T = AuthLogoutResponse>(signOutOptions?: SignOutOptions): Promise<T | undefined> {
    if (servingOffline.value) {
      showOfflineToastError();
      return;
    }

    setSigningOut(true);
    // setSigningOut(true) blocks NEW refreshes; drainPendingRefresh() lets any
    // in-flight one settle so its setToken() lands before clearToken() below.
    await drainPendingRefresh();

    const signOutConfig = config.endpoints.signOut;

    try {
      await unlinkIfNative();
    } catch (e) {
      console.error('Error in unlinkIfNative function:', e);
    }

    await useMobile()?.stop();

    const { path, method } = signOutConfig;

    const nativeHeader = { Authorization: token.value } as HttpHeaders;
    const webHeaders = new Headers(nativeHeader as HeadersInit);

    const body = { refresh_token: refreshToken.value };

    // Clear tokens before the API call to prevent any refresh triggers
    // (middleware, Supabase interceptor, visibility handler) from racing
    clearToken();
    clearRefreshToken();
    data.value = null;

    try {
      const response = isNative
        ? await doMobileRequest<AuthLogoutResponse>({
            url: path,
            method,
            data: body,
            headers: nativeHeader,
          })
        : await doWebRequest<AuthLogoutResponse>(path, {
            method,
            body: body,
            headers: webHeaders,
          });

      return response as T | undefined;
    } catch (error) {
      console.error('Error during sign out:', error);
    } finally {
      setSigningOut(false);
      const { redirect = true, callbackUrl } = signOutOptions ?? {};
      if (redirect) {
        await navigateTo(callbackUrl ?? '/login', { replace: true });
        useNuxtApp().$disableSwipeGestures();
      }
      await cacheClear().catch(() => {});
    }
  }

  async function getSession(getSessionOptions?: GetSessionOptions): Promise<SessionData | null | void> {
    const { path, method } = config.endpoints.getSession;

    if (!token.value && !getSessionOptions?.force) {
      loading.value = false;
      return;
    }

    const nativeHeader = { Authorization: token.value } as HttpHeaders;
    const webHeaders = new Headers(nativeHeader as HeadersInit);

    loading.value = true;
    try {
      const response = isNative
        ? await doMobileRequest<GetProfileResponse>({
            url: path,
            method,
            headers: nativeHeader,
          })
        : await doWebRequest<GetProfileResponse>(path, {
            method,
            headers: webHeaders,
          });
      if (response) {
        data.value = response;
      }
    } catch (err: any) {
      const statusCode = err?.statusCode ?? err?.status;

      if (statusCode === 401) {
        // Token is invalid — clear it
        data.value = null;
        clearToken();
      } else {
        // Error (network, 500, etc.) — preserve existing session and token
        console.error(`[AUTH] Session fetch failed (${statusCode}): ${err?.message}`);
      }
    }
    loading.value = false;

    const { required = false, callbackUrl, onUnauthenticated } = getSessionOptions ?? {};
    if (required && !data.value) {
      if (onUnauthenticated) {
        onUnauthenticated();
      }
      if (callbackUrl) await navigateTo(callbackUrl, { replace: true });
    }
    return data.value;
  }

  async function _doRefresh(getSessionOptions?: GetSessionOptions) {
    const { path, method } = config.endpoints.refresh;

    const response = isNative
      ? await doMobileRequest<RefreshAuthTokenResponse>({
          url: path,
          method,
          data: { refresh_token: refreshToken.value },
        })
      : await doWebRequest<RefreshAuthTokenResponse>(path, {
          method,
          body: { refresh_token: refreshToken.value },
        });
    if (response === undefined) {
      console.error(`[AUTH] refresh returned undefined value`);
      return;
    }
    setToken(response.access_token);
    lastRefreshedAt.value = new Date();

    await nextTick();

    // getSession failure after a successful refresh should not bubble up —
    // the token is already updated, session data will load on next opportunity
    try {
      return await getSession(getSessionOptions);
    } catch (err) {
      console.error('[AUTH] getSession failed after refresh, token preserved:', err);
    }
  }

  // Single-flight refresh (skipped during sign-out to prevent race conditions).
  // State lives in `./refreshSingleFlight` so it's unit-testable without a Nuxt runtime.
  async function refresh(getSessionOptions?: GetSessionOptions) {
    return singleFlightRefresh(() => {
      refreshing.value = true;
      return _doRefresh(getSessionOptions).finally(() => {
        refreshing.value = false;
      });
    });
  }

  // Expose the in-flight refresh promise so request interceptors can gate concurrent
  // requests on a pending refresh instead of each firing and racing the same stale token.
  function pendingRefresh() {
    return _pendingRefresh<SessionData | null | void>();
  }

  return {
    status,
    data: readonly(data),
    lastRefreshedAt: readonly(lastRefreshedAt),
    token: readonly(token),
    refreshToken: readonly(refreshToken),
    refreshing: readonly(refreshing),
    signIn,
    signOut,
    getSession,
    refresh,
    pendingRefresh,
  };
}
