import type { HttpOptions } from '@capacitor/core';
import type { GetVersionsInfoResponse, VersionDetailsRequest, GetVersionsInfoData } from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function getUpdateInfo(payload: VersionDetailsRequest): Promise<GetVersionsInfoResponse> {
  const url: GetVersionsInfoData['url'] = '/api/settings/versions';
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<GetVersionsInfoResponse>(options, 'UpdateInfo', false);
}
