import { uploadCachedAudioIfExists } from '~/utils/mobile/uploadAudioNative';
import { uploadCachedWakeWordClipsIfExists } from '~/utils/mobile/uploadWakeWordClipNative';

export async function uploadAllCachedAudioIfExists(): Promise<void> {
  const results = await Promise.allSettled([uploadCachedAudioIfExists(), uploadCachedWakeWordClipsIfExists()]);
  const failed = results.find((r): r is PromiseRejectedResult => r.status === 'rejected');
  if (failed) throw failed.reason;
}
