import { Capacitor } from '@capacitor/core';
import { useDeviceInfoStore } from '~/stores/mobile/deviceInfo';
import { unlinkDeviceFromUser } from '~/mutations/mobile/unlinkUserFromDevice';
import { deleteTokenIfExists } from '~/plugins/notifications';
import { resetDeviceLink } from '~/utils/mobile/ensureDeviceLinked';

export async function unlinkIfNative(deleteToken: boolean = true) {
  if (!Capacitor.isNativePlatform()) return;
  try {
    if (deleteToken) {
      await deleteTokenIfExists();
    }

    const deviceInfoStore = useDeviceInfoStore();
    const id = deviceInfoStore.info.id;

    if (id) {
      await unlinkDeviceFromUser({ device_id: id });
    } else {
      console.warn('[UnlinkDevice] Failed to unlink device from user. No device id found');
    }
  } catch (error) {
    console.error('[UnlinkDevice] Failed to unlink device:', error);
  } finally {
    // The device→user link has been deactivated — clear the cached registration
    // so the next signed-in user re-links before their events are sent.
    resetDeviceLink();
  }
}
