import { cacheStore, cacheGet, servingOffline } from '~/utils/offlineCache';

type MaybePromise<T> = T | PromiseLike<T>;

export function useCheckSupabaseClient() {
  const { $supabase } = useNuxtApp();
  if (!$supabase) throw new Error('Connect to server failed');
  return $supabase;
}

type SupabaseQuery<T> = (supabase: ReturnType<typeof useCheckSupabaseClient>) => MaybePromise<T>;

export async function withSupabase<T>(cb: SupabaseQuery<T>): Promise<Awaited<T>> {
  const supabase = useCheckSupabaseClient();
  return await cb(supabase);
}

/**
 * Caching wrapper for Supabase queries that bypass the plugin's global fetch
 * (e.g. storage operations). For REST/RPC queries, use `withSupabase` instead —
 * the supabase plugin's fetch wrapper handles caching automatically.
 */
export async function withCachedSupabase<T extends { data: any; error: any }>(
  cacheKey: string,
  cb: SupabaseQuery<T>
): Promise<Awaited<T>> {
  const { isOffline } = useNetworkStatus();
  const fullKey = `sb:${cacheKey}`;
  const supabase = useCheckSupabaseClient();

  let result: Awaited<T>;
  try {
    result = (await cb(supabase)) as Awaited<T>;
  } catch (err) {
    console.warn(`[withCachedSupabase] cb threw for key="${fullKey}"`, err);
    const cached = await cacheGet<Awaited<T>>(fullKey);
    if (cached !== undefined) {
      console.log(`[withCachedSupabase] CACHE HIT (from throw) key="${fullKey}"`);
      servingOffline.value = true;
      return cached;
    }
    throw err;
  }

  if (result.error === null && result.data !== null) {
    cacheStore(fullKey, result).catch((e) =>
      console.warn(`[withCachedSupabase] cacheStore failed key="${fullKey}"`, e)
    );
    servingOffline.value = false;
    return result;
  }

  if (isOffline.value) {
    const cached = await cacheGet<Awaited<T>>(fullKey);
    if (cached !== undefined) {
      servingOffline.value = true;
      return cached;
    }
  }

  return result;
}
