import { useToast } from '~/components/ui/toast';
import { FetchError } from 'ofetch';

export function showToastError(error?: FetchError | Error | string, title?: string, md = false): void {
  const { toast } = useToast();
  if (error instanceof FetchError && error.statusCode === 401) return;
  // Backend `detail` is always markdown-formatted (e.g. bulleted validation lists), so render it
  // as markdown. Otherwise render plain text unless the caller opts in via `md` — this keeps
  // arbitrary Error/string messages from being mangled by the markdown parser by default.
  const isDetail = (error instanceof FetchError && !!error?.data?.detail) || md;
  toast({
    title: title ?? 'Error',
    description:
      error instanceof FetchError && error?.data?.detail
        ? error.data.detail
        : error instanceof Error
          ? error.message
          : error,
    markdown: isDetail,
    variant: 'destructive',
  });
}

export function showToastInfo(title: string, description?: string): void {
  const { toast } = useToast();

  toast({
    title: title,
    description: description,
    variant: 'default',
  });
}

export function showOfflineToastError(): void {
  const { toast } = useToast();
  toast({
    title: 'You are offline',
    description: 'This action requires a network connection. Please try again when you are back online.',
    variant: 'destructive',
  });
}

export function showToastSuccess(title?: string, description?: string): void {
  const { toast } = useToast();

  toast({
    title: title ?? 'Success',
    description: description,
    variant: 'success',
  });
}
