import { LiveUpdate } from '@capawesome/capacitor-live-update';
import { Dialog } from '@capacitor/dialog';
import { Capacitor } from '@capacitor/core';
import { Browser } from '@capacitor/browser';
import { checkVersion } from '~/composables/mobile/updates/useVersionCheck';
import { Preferences } from '@capacitor/preferences';
import type { RoutesNamesList } from '@typed-router';
import { SplashScreen } from '@capacitor/splash-screen';

import { sendMobileEvent } from '~/utils/mobile/mobileEvents';
import { sendUpdateDeviceInfo } from '~/utils/mobile/updateDeviceInfo';

const PROMPT_INTERVAL_MS = 3 * 60 * 60 * 1000;
const PROMPT_KEY = 'liveupdate_last_prompt_time';
const PAGE_BEFORE_RELOAD_KEY = 'page_before_reload';
const LIVE_UPDATE_SPLASH_KEY = 'live_update_splash_shown';

type Mode = 'silent' | 'prompt';

type SavedRoute = { name: RoutesNamesList; params: Record<string, any>; query: Record<string, any> };

const setPageBeforeReload = async () => {
  const route = useRoute();
  const saved: SavedRoute = {
    name: route.name as RoutesNamesList,
    params: { ...route.params },
    query: { ...route.query },
  };
  await Preferences.set({ key: PAGE_BEFORE_RELOAD_KEY, value: JSON.stringify(saved) });
};

export const getPageBeforeReload = async (): Promise<SavedRoute | null> => {
  const { value } = await Preferences.get({ key: PAGE_BEFORE_RELOAD_KEY });
  await Preferences.remove({ key: PAGE_BEFORE_RELOAD_KEY });
  return value ? (JSON.parse(value) as SavedRoute) : null;
};

export const consumeLiveUpdateSplashFlag = async (): Promise<boolean> => {
  const { value } = await Preferences.get({ key: LIVE_UPDATE_SPLASH_KEY });
  await Preferences.remove({ key: LIVE_UPDATE_SPLASH_KEY });
  return value === '1';
};

const setLastPromptTime = async (time: number) => {
  await Preferences.set({ key: PROMPT_KEY, value: String(time) });
};

const getLastPromptTime = async (): Promise<number> => {
  const { value } = await Preferences.get({ key: PROMPT_KEY });
  return value ? Number(value) : 0;
};

const g = globalThis as any;
if (g.__liveUpdateInFlight === undefined) g.__liveUpdateInFlight = false;

export async function checkLiveUpdates(mode: Mode = 'prompt') {
  if (!Capacitor.isNativePlatform() || g.__liveUpdateInFlight) return;

  try {
    g.__liveUpdateInFlight = true;

    await LiveUpdate.ready();
    await setChannel();

    const currentBundle = await getCurrentBundle();
    const response = await checkVersion(currentBundle);

    if (response.force_native_update) {
      await enforceNativeUpdate();
      return;
    }

    if (response.force_live_update === true && response.live_update_bundle_id && response.bundle_url) {
      const changed = await prepareNextBundleIfNeeded(
        response.live_update_bundle_id,
        response.bundle_url,
        response.checksum ?? undefined
      );
      if (changed) {
        await applyNewBundle();
      }
      return;
    }

    const optionalNative = response.has_native_update === true;

    let preparedChanged = false;
    if (response.live_update_bundle_id && response.bundle_url) {
      preparedChanged = await prepareNextBundleIfNeeded(
        response.live_update_bundle_id,
        response.bundle_url,
        response.checksum ?? undefined
      );
    }

    if (mode === 'silent') {
      if (preparedChanged) {
        await applyNewBundle();
      }
      return;
    } else {
      if (await shouldPromptNow()) {
        if (optionalNative && (!response.live_update_bundle_id || !response.bundle_url)) {
          const confirmed = await confirmDialog({
            title: 'Update available',
            message: 'A new app version is available in the store. Update now?',
            ok: 'Update',
            cancel: 'Later',
          });
          await setLastPromptTime(Date.now());
          if (confirmed) {
            await Browser.open({ url: getStoreUrl() });
          }
          return;
        } else if (response.live_update_bundle_id && response.bundle_url) {
          const confirmed = await confirmDialog({
            title: 'In-App update available',
            message: 'A new in-app update is ready. Do you want to install it now?',
            ok: 'Update now',
            cancel: 'Later',
          });
          await setLastPromptTime(Date.now());
          if (confirmed && preparedChanged) {
            await applyNewBundle();
          }
          return;
        }
      }
    }
  } catch (err) {
    try {
      console.error('[LiveUpdate] check failed:', JSON.stringify(err));
    } catch {
      console.error('[LiveUpdate] check failed:', err);
    }
  } finally {
    g.__liveUpdateInFlight = false;
  }
}

const getCurrentBundle = async (): Promise<string | null> => {
  const result = await LiveUpdate.getCurrentBundle();
  return result.bundleId ?? null;
};

export const setChannel = async () => {
  const env = useRuntimeConfig().public.environment;
  await LiveUpdate.setChannel({ channel: String(env) });
};

const getStoreUrl = () => {
  const platform = Capacitor.getPlatform();
  const cfg = useRuntimeConfig().public.mobile;
  return platform === 'ios' ? cfg.ios_store_url : cfg.android_store_url;
};

const confirmDialog = async (opts: { title: string; message: string; ok: string; cancel: string }) => {
  const { value } = await Dialog.confirm({
    title: opts.title,
    message: opts.message,
    okButtonTitle: opts.ok,
    cancelButtonTitle: opts.cancel,
  });
  return Boolean(value);
};

const enforceNativeUpdate = async () => {
  await Dialog.alert({
    title: 'Update required',
    message: 'A new version is required to continue.',
    buttonTitle: 'Update now',
  });
  await Browser.open({ url: getStoreUrl() });
};

const hasBundleDownloaded = async (bundleId: string): Promise<boolean> => {
  const bundles = await LiveUpdate.getBundles();
  return (bundles.bundleIds ?? []).includes(bundleId);
};

const isBundleCurrent = async (bundleId: string): Promise<boolean> => {
  const current = await getCurrentBundle();
  return current === bundleId;
};

export const prepareNextBundleIfNeeded = async (bundleId: string, url: string, checksum?: string): Promise<boolean> => {
  if (await isBundleCurrent(bundleId)) return false;
  if (!(await hasBundleDownloaded(bundleId))) {
    await LiveUpdate.downloadBundle({ bundleId, url, ...(checksum ? { checksum } : {}) });
    showToastInfo('App update has been downloaded.');
    try {
      await sendMobileEvent('live_update_downloaded', { bundle_id: bundleId });
    } catch (err) {
      console.error('[LiveUpdate] Failed to send event about live update downloading:', err);
    }
  }
  await LiveUpdate.setNextBundle({ bundleId });
  return true;
};

const shouldPromptNow = async (): Promise<boolean> => {
  const now = Date.now();
  const last = await getLastPromptTime();
  return now - last >= PROMPT_INTERVAL_MS;
};

export const applyNewBundle = async () => {
  try {
    const { bundleId } = await LiveUpdate.getNextBundle();
    if (!bundleId) {
      console.warn('[LiveUpdate] applyNewBundle: no next bundle set, aborting reload');
      return;
    }

    await sendUpdateDeviceInfo().catch((err) => {
      console.error(`[LiveUpdate] Failed to upload device info on bundle apply. (${err})`);
    });

    try {
      await sendMobileEvent('live_update_applied', { bundle_id: bundleId });
    } catch (err) {
      console.error('[LiveUpdate] Failed to send event about live update application.', err);
    }

    await SplashScreen.show({ autoHide: false });
    await Preferences.set({ key: LIVE_UPDATE_SPLASH_KEY, value: '1' });
    try {
      await setPageBeforeReload();
    } catch (err) {
      console.error('[LiveUpdate] Failed to save page before reload, will not restore page. Error:', err);
    }
    setTimeout(() => {
      LiveUpdate.reload();
    }, 2000);
  } catch (err) {
    console.error('[LiveUpdate] Failed to apply new bundle:', err);
  }
};

export async function restorePageAfterLiveUpdate() {
  const savedPage = await getPageBeforeReload();
  if (savedPage) {
    console.info(`[LiveUpdate] Restoring page after bundle apply.`);
    const router = useRouter();
    const splashTimeout = setTimeout(() => {
      stop();
      SplashScreen.hide().catch(() => {});
      console.warn('[LiveUpdate] splash screen safety timeout fired — page restore aborted');
    }, 20000);
    const stop = router.afterEach((_to, _from, failure) => {
      if (failure) {
        stop();
        clearTimeout(splashTimeout);
        SplashScreen.hide().catch(() => {});
        return;
      }
      clearTimeout(splashTimeout);
      stop();
      router
        .replace({ name: savedPage.name as any, params: savedPage.params, query: savedPage.query })
        .then(() => {
          console.info(`[LiveUpdate] page restored successfully: ${savedPage.name}`);
          showToastSuccess('App has been updated successfully.');
        })
        .catch((err) => console.error('[LiveUpdate] page restore failed:', err))
        .finally(() => SplashScreen.hide());
    });
  } else {
    console.debug('[LiveUpdate] no saved page found, starting normally');
    const splashWasShown = await consumeLiveUpdateSplashFlag();
    if (splashWasShown) {
      SplashScreen.hide().catch(() => {});
    }
  }
}
