import { recordNavigation, NAV_JOURNEY_STORAGE_KEY, type BackGroup, type JourneyEntry } from '~/utils/navJourney';
import { useNavJourney } from '~/composables/useNavJourney';

declare module '#app' {
  interface PageMeta {
    backGroup?: BackGroup;
    /** Label shown by GoBackButton when this page is the back target: "Back to <backLabel>" */
    backLabel?: string;
    /** Exclude this page from the back journey. Set on transient pages that redirect on
     *  submit (create/wizard forms) so they never become a back target. */
    skipNavJourney?: boolean;
  }
}

declare module 'vue-router' {
  interface RouteMeta {
    backGroup?: BackGroup;
    backLabel?: string;
    skipNavJourney?: boolean;
  }
}

export default defineNuxtPlugin(() => {
  const router = useRouter();
  const { journey } = useNavJourney();

  // recordNavigation returns null when the route should be ignored; only then do we
  // leave state and sessionStorage untouched.
  const persist = (next: JourneyEntry[] | null) => {
    if (next === null) return;
    journey.value = next;
    sessionStorage.setItem(NAV_JOURNEY_STORAGE_KEY, JSON.stringify(journey.value));
  };

  router.afterEach((to, _from, failure) => persist(recordNavigation(journey.value, to, failure)));

  // Seed the current route once at init: afterEach may not fire for the initial
  // hydration navigation, so on a cold session the landing page would never be
  // recorded and Back from the first onward navigation would use the fallback
  // instead of the real origin. This is idempotent — if afterEach DID fire for the
  // initial route, applyNavigation replaces the same-group top, so re-recording is
  // a no-op.
  if (router.currentRoute.value.name) {
    persist(recordNavigation(journey.value, router.currentRoute.value));
  }
});
