import { Capacitor } from '@capacitor/core';

export const PTR_CONTENT_ID = 'ptr-content' as const;

export default defineNuxtPlugin(() => {
  if (!Capacitor.isNativePlatform()) return;

  const router = useRouter();
  let teardown: (() => void) | null = null;

  function findScrollParent(el: Element | null): Element | null {
    while (el && el !== document.documentElement) {
      const { overflowY } = getComputedStyle(el);
      if ((overflowY === 'auto' || overflowY === 'scroll') && el.scrollHeight > el.clientHeight) {
        return el;
      }
      el = el.parentElement;
    }
    return null;
  }

  function setup() {
    teardown?.();

    const DEAD_ZONE = 0; // Must remain 0 — onMove relies on immediate direction-lock to suppress iOS bounce.
    const RELEASE_DIST = 170; // pull distance (px) that triggers refresh
    const EDGE_GUARD = 30; // px from left edge reserved for iOS swipe-back
    const MAX_HEIGHT = 170; // max indicator height (px)
    const BOX_TOP = Math.round(MAX_HEIGHT / 6); // icon appears after pulling 1/6 of MAX_HEIGHT
    const REFRESH_HEIGHT = BOX_TOP + 80; // chip(36) + gap(4) + label(~16) + bottom-padding(10)

    let startY: number | null = null;
    let startX = 0;
    let pullDist = 0;
    let directionLocked = false;
    let state: 'idle' | 'pulling' | 'refreshing' = 'idle';
    let scrollParent: Element | null = null;
    let isPtrAvailable = false;

    const svgNS = 'http://www.w3.org/2000/svg';

    // Container — position:fixed at top, clips content via overflow:hidden as it grows
    const ptr = document.createElement('div');
    ptr.style.cssText = `
      pointer-events: none;
      position: fixed; top: 0; left: 0; right: 0;
      height: 0; overflow: hidden; width: 100%;
      background: hsl(var(--accent));
      z-index: 1;
    `;

    // Box — absolutely positioned at BOX_TOP so icon/text are hidden until ptr is tall enough
    const box = document.createElement('div');
    box.style.cssText = `
      position: absolute; top: ${BOX_TOP}px; left: 0; right: 0;
      display: flex; flex-direction: column; align-items: center; gap: 4px;
    `;

    const svg = document.createElementNS(svgNS, 'svg') as SVGSVGElement;
    svg.setAttribute('width', '24');
    svg.setAttribute('height', '24');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('fill', 'none');

    const arcPath = document.createElementNS(svgNS, 'path');
    arcPath.setAttribute('d', 'M21 12a9 9 0 1 1-9-9c2.52 0 4.93 1 6.74 2.74L21 8');
    arcPath.setAttribute('stroke', 'hsl(var(--primary))');
    arcPath.setAttribute('stroke-width', '2');
    arcPath.setAttribute('stroke-linecap', 'round');
    arcPath.setAttribute('stroke-linejoin', 'round');

    const arrowPath = document.createElementNS(svgNS, 'path');
    arrowPath.setAttribute('d', 'M21 3v5h-5');
    arrowPath.setAttribute('stroke', 'hsl(var(--primary))');
    arrowPath.setAttribute('stroke-width', '2');
    arrowPath.setAttribute('stroke-linecap', 'round');
    arrowPath.setAttribute('stroke-linejoin', 'round');

    svg.appendChild(arcPath);
    svg.appendChild(arrowPath);

    const chip = document.createElement('div');
    chip.style.cssText = `
        width: 36px; height: 36px; border-radius: 50%;
        
        display: flex; align-items: center; justify-content: center;
      `;
    // background: white;
    //   box-shadow: 0 2px 8px rgba(0,0,0,0.22);
    chip.appendChild(svg);
    box.appendChild(chip);

    const onArcProgress = (p: number) => {
      svg.style.transform = `rotate(${p * 360}deg)`;
      svg.style.transformOrigin = 'center';
    };
    const onArcReset = () => {
      svg.style.transform = '';
      svg.style.transformOrigin = '';
    };
    const onArcRefresh = () => {
      // Clear inline transform so the ptr-spinning-svg CSS animation takes over cleanly
      svg.style.transform = '';
      svg.style.transformOrigin = '';
    };

    // Text label
    const label = document.createElement('div');
    label.style.cssText = 'font-size: .85em; font-weight: bold; color: hsl(var(--primary));';
    label.textContent = 'Pull to refresh';
    box.appendChild(label);

    ptr.appendChild(box);
    document.body.prepend(ptr);

    const isAtTop = () => (scrollParent ? scrollParent.scrollTop <= 1 : window.scrollY <= 1);

    const setHeight = (h: number, animated: boolean) => {
      ptr.style.transition = animated ? 'height .3s' : 'none';
      ptr.style.height = `${h}px`;
      const contentEl = document.getElementById(PTR_CONTENT_ID);
      if (contentEl) {
        contentEl.style.transition = animated ? 'transform .3s' : 'none';
        contentEl.style.transform = h > 0 ? `translateY(${h}px)` : '';
      }
    };

    const clearVisuals = (animated: boolean) => {
      pullDist = 0;
      onArcReset();
      label.textContent = 'Pull to refresh';
      setHeight(0, animated);
    };

    const reset = () => {
      state = 'idle';
      startY = null;
      startX = 0;
      directionLocked = false;
      isPtrAvailable = false;
      svg.classList.remove('ptr-spinning-svg');
      clearVisuals(true);
    };

    const onStart = (e: TouchEvent) => {
      isPtrAvailable = false;
      if (state !== 'idle') return; // refreshing or pulling — ignore extra touches mid-gesture
      const touch = e.touches[0];
      if (touch.clientX < EDGE_GUARD) return; // leave left edge for iOS swipe-back
      scrollParent = findScrollParent(e.target as Element);
      // Native PTR semantics: only arm if the scroll container is already at the top.
      // If the user starts scrolled, the entire gesture is handed to the browser —
      // they must release and re-touch at the top to trigger PTR.
      if (!isAtTop()) return;
      startX = touch.clientX;
      startY = touch.clientY;
      pullDist = 0;
      directionLocked = false;
      isPtrAvailable = true;
    };

    const onMove = (e: TouchEvent) => {
      if (!isPtrAvailable || startY === null) return;

      const touch = e.touches[0];
      let dy = touch.clientY - startY;
      const dx = Math.abs(touch.clientX - startX);

      // Lock direction once we've moved past the dead zone. Direction-lock runs
      // before any preventDefault — a horizontal-leaning gesture (e.g. native
      // overflow-x inside FilterTabs/ResponsiveTable) must reach the dx > |dy|
      // bail without us first canceling the touch. iOS elastic bounce on the
      // first downward-vertical move is suppressed by the preventDefault at the
      // bottom of this handler, which runs in the same event tick.
      if (!directionLocked && (Math.abs(dy) > DEAD_ZONE || dx > DEAD_ZONE)) {
        directionLocked = true;
        if (dx > Math.abs(dy)) {
          reset(); // horizontal — hand off to iOS swipe-back
          return;
        }
      }
      if (!directionLocked) return;

      // The touchstart top-of-scroll gate only checks scrollTop at the start of
      // the gesture. If the user then drags up while still 'idle', we let the
      // browser scroll the page natively (no preventDefault on the dy <= 0
      // idle path). On a subsequent downward move, scrollTop is no longer 0 —
      // activating PTR here would render the indicator over a scrolled page
      // and could trigger refresh from a non-top position. Disarm instead and
      // let the browser own the rest of the touch.
      if (state === 'idle' && !isAtTop()) {
        isPtrAvailable = false;
        return;
      }

      if (dy <= 0) {
        if (state === 'pulling') {
          // Once pulling, the gesture is ours until touchend. Clamp to 0 but stay
          // armed — calling reset() here would hand control back to the browser
          // mid-gesture and cause page-scroll to run alongside the PTR retract.
          clearVisuals(false);
          if (e.cancelable) e.preventDefault();
        }
        return;
      }

      state = 'pulling';
      pullDist = dy;

      // Rubber-band: full speed to RELEASE_DIST, then 30% past it
      const rubber = pullDist > RELEASE_DIST ? RELEASE_DIST + (pullDist - RELEASE_DIST) * 0.3 : pullDist;
      const h = Math.min(MAX_HEIGHT, rubber * (MAX_HEIGHT / RELEASE_DIST));
      onArcProgress(Math.min(1, pullDist / RELEASE_DIST));
      label.textContent = pullDist >= RELEASE_DIST ? 'Release to refresh' : 'Pull to refresh';

      setHeight(h, false);
      if (e.cancelable) e.preventDefault();
    };

    const onEnd = () => {
      if (state !== 'pulling') return;
      if (pullDist >= RELEASE_DIST) {
        state = 'refreshing';
        label.textContent = 'Refreshing\u2026';
        onArcRefresh();
        svg.classList.add('ptr-spinning-svg');
        setHeight(REFRESH_HEIGHT, true);
        setTimeout(() => window.location.replace(window.location.href), 350);
      } else {
        reset();
      }
    };

    window.addEventListener('touchstart', onStart, { passive: true });
    window.addEventListener('touchmove', onMove, { passive: false });
    window.addEventListener('touchend', onEnd, { passive: true });
    window.addEventListener('touchcancel', reset, { passive: true });

    teardown = () => {
      window.removeEventListener('touchstart', onStart);
      window.removeEventListener('touchmove', onMove);
      window.removeEventListener('touchend', onEnd);
      window.removeEventListener('touchcancel', reset);
      ptr.remove();
      const contentEl = document.getElementById(PTR_CONTENT_ID);
      if (contentEl) {
        contentEl.style.transform = '';
        contentEl.style.transition = '';
      }
    };
  }

  router.afterEach(() => nextTick(setup));
});
