import * as Sentry from '@sentry/capacitor';
import { createBleScanner } from '~/composables/mobile/trackers/useMobileBleScan';
import { createLocationTracker } from '~/composables/mobile/trackers/useMobileLocationTracking';
import { createSensorTracker } from '~/composables/mobile/trackers/useMobileMotionTracking';
import { createWifiScanner } from '~/composables/mobile/trackers/useMobileWifiScan';
import { useMobileRuntimeState } from '~/composables/mobile/useMobileRuntimeState';
import { useRecorderStore } from '~/stores/mobile/vadRecorder';
import { AudioSessionBusyError } from '~/composables/mobile/audio/useAudioSessionAvailability';
import { setUsingMicrophone } from '~/composables/mobile/useMobileRuntimeState';
import type { MobileModule } from '~/types/mobile/module';
import type { ModuleName } from 'permissions-manager-plugin';

export function createModuleManager() {
  const { modules } = useMobileRuntimeState();

  function buildModules(shiftId: string, deviceId: string, modulesToStart: ModuleName[]): MobileModule[] {
    const mods: MobileModule[] = [];
    console.log('[Mobile] Building following tracking modules:', JSON.stringify(modulesToStart));
    if (modulesToStart.includes('motion')) mods.push(createSensorTracker(shiftId, deviceId));
    if (modulesToStart.includes('location')) mods.push(createLocationTracker(shiftId, deviceId));
    if (modulesToStart.includes('wifi')) mods.push(createWifiScanner(shiftId, deviceId));
    if (modulesToStart.includes('ble')) mods.push(createBleScanner(shiftId, deviceId));
    if (modulesToStart.includes('microphone')) {
      const recorderStore = useRecorderStore();
      recorderStore.init(shiftId, deviceId);
      mods.push(recorderStore);
      setUsingMicrophone(true);
    } else {
      setUsingMicrophone(false);
    }

    return mods;
  }

  async function stopOne(m: MobileModule): Promise<boolean> {
    try {
      await m.stop();
    } catch (e: unknown) {
      console.warn(`[Mobile] Module ${m.name} failed to stop, retrying:`, e);
      await new Promise((resolve) => setTimeout(resolve, 300));
      try {
        await m.stop();
      } catch (retryErr: unknown) {
        console.error(`[Mobile] Module ${m.name} failed to stop after retry:`, retryErr);
        Sentry.captureException(retryErr);
        return false;
      }
    }
    if (m.isAlive()) {
      console.error(`[Mobile] Module ${m.name} still alive after stop.`);
      return false;
    }
    return true;
  }

  async function stop(): Promise<{ stopped: string[]; failed: string[] }> {
    const outcomes = await Promise.all(modules.value.map(async (m) => ({ m, ok: await stopOne(m) })));
    const stopped = outcomes.filter((o) => o.ok).map((o) => o.m.name);
    const failed = outcomes.filter((o) => !o.ok).map((o) => o.m.name);
    // Keep failed handles so a watchdog / later pause can retry the stop.
    modules.value = outcomes.filter((o) => !o.ok).map((o) => o.m);
    return { stopped, failed };
  }

  async function start(workShiftId: string, deviceId: string, modulesToStart: ModuleName[]): Promise<string[]> {
    // Stop any existing modules before starting new ones
    if (modules.value.length > 0) {
      const { failed } = await stop();
      if (failed.length > 0) {
        // stop() already dropped the retry-kept handles from modules.value, and buildModules
        // below is about to overwrite modules.value with the fresh set — without this, a
        // module that never actually stopped (e.g. a still-running native watcher) would
        // vanish silently. The Task-4 watchdog is the real backstop for a surviving watcher;
        // this just makes the discard loud.
        console.error(`[Mobile] Stale module(s) failed to stop before restart, discarding handle(s):`, failed);
        Sentry.captureException(
          new Error(`[Mobile] Stale module(s) failed to stop before restart: ${failed.join(', ')}`)
        );
      }
    }
    modules.value = buildModules(workShiftId, deviceId, modulesToStart);
    const results = await Promise.allSettled(modules.value.map((m) => m.start()));
    let succeededModules = [];
    let audioBusyError: AudioSessionBusyError | null = null;
    for (let i = 0; i < results.length; i++) {
      if (results[i].status === 'rejected') {
        const reason = (results[i] as PromiseRejectedResult).reason;
        // Another app grabbed audio between the pre-start gate and module start (call, Siri,
        // media). Transient and not Sentry-worthy — remember it so we can abort the start
        // cleanly and let the user retry, rather than letting an audio-required shift run
        // silently without recording.
        if (reason instanceof AudioSessionBusyError) {
          console.warn(`[Mobile] Module ${modules.value[i].name} not started (audio session busy):`, reason.reason);
          audioBusyError = reason;
        } else {
          console.error(`[Mobile] Module ${modules.value[i].name} failed to start:`, reason);
          Sentry.captureException(reason);
        }
      } else {
        succeededModules.push(modules.value[i].name);
      }
    }

    if (audioBusyError) {
      // Tear down any modules that did start; the tracking controller's AudioSessionBusyError
      // branch surfaces the busy toast and cancels the half-started shift.
      await stop();
      throw audioBusyError;
    }

    return succeededModules;
  }
  return { start, stop };
}
