import { Device } from '@capacitor/device';
import { DeviceSecurityDetect } from '@capacitor-community/device-security-detect';
import { Capacitor } from '@capacitor/core';
import { registerPlugin } from '@capacitor/core';
import type { MotionActivityPlugin } from 'motion-activity-plugin';
import { App } from '@capacitor/app';
import { Udid } from 'capacitor-udid';

export type DeviceInfo = {
  id: string;
  is_root: boolean;
  platform: string;
  software_version: string;
  os_version: string;
  model: string;
  name: string;
  is_complete_sensors: boolean;
  timezone: string;
};

export const useDeviceInfoStore = defineStore('deviceInfo', () => {
  const info = ref<DeviceInfo>({
    id: '',
    is_root: false,
    platform: '',
    software_version: '',
    os_version: '',
    model: '',
    name: '',
    is_complete_sensors: false,
    timezone: '',
  });

  const isInitialised = computed(() => Boolean(info.value.id));

  let initInFlight: Promise<void> | null = null;
  let lastLazyInitAt = 0;
  const LAZY_INIT_COOLDOWN_MS = 30_000;

  async function fetchInfo() {
    if (isInitialised.value) {
      console.warn('DeviceInfo already initialised.');
      return;
    }
    if (initInFlight) return initInFlight;

    initInFlight = (async () => {
      const appInfo = await App.getInfo();
      const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const isRoot = Capacitor.isNativePlatform() ? (await DeviceSecurityDetect.isJailBreakOrRooted()).value : false;
      const deviceInfo = await Device.getInfo();
      const MotionActivity = registerPlugin<MotionActivityPlugin>('MotionActivity');
      const { sensors } = await MotionActivity.getMotionSensors();
      const allAvailable = sensors.accelerometer && sensors.gyroscope && sensors.magnetometer && sensors.rotationVector;
      const deviceId = (await Udid.getUdid()).value;
      const publicAppConfig = useRuntimeConfig().public;
      const web_version = publicAppConfig.version;

      Object.assign(info.value, {
        id: deviceId,
        is_root: isRoot,
        platform: deviceInfo.platform,
        os_version: deviceInfo.osVersion,
        model: deviceInfo.model,
        name: deviceInfo.name,
        is_complete_sensors: allAvailable,
        software_version: `v${web_version} (${appInfo.build})`,
        timezone: timeZone,
      });
    })();

    try {
      await initInFlight;
    } finally {
      initInFlight = null;
    }
  }

  async function ensureDeviceId(): Promise<string | null> {
    if (isInitialised.value) return info.value.id;

    try {
      if (initInFlight) {
        await initInFlight;
      } else if (Date.now() - lastLazyInitAt >= LAZY_INIT_COOLDOWN_MS) {
        lastLazyInitAt = Date.now();
        await fetchInfo();
      }
    } catch (error) {
      console.warn('[DeviceInfo] Lazy init failed:', error);
    }

    return info.value.id || null;
  }

  return {
    info,
    isInitialised,
    init: fetchInfo,
    ensureDeviceId,
  };
});
