import type { HttpOptions } from '@capacitor/core';
import type { MobileWorkShiftGenerateRequest, GenerateWorkShiftIdResponse, GenerateWorkShiftIdData } from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function generateWorkShiftId(
  payload: MobileWorkShiftGenerateRequest
): Promise<GenerateWorkShiftIdResponse> {
  const url: GenerateWorkShiftIdData['url'] = '/api/mobile/work_shift/generate';
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<GenerateWorkShiftIdResponse>(options, 'GenerateWorkShiftId');
}
