import { Preferences } from '@capacitor/preferences';

const PUSH_DISABLED_KEY = 'push_notifications_user_disabled';

/**
 * Whether the user has deliberately turned push notifications off via the
 * Notifications page toggle. Used to stop the implicit auto-registration paths
 * (login + the 5-minute loop in app.vue) from silently re-enabling them.
 */
export async function getPushDisabledByUser(): Promise<boolean> {
  const { value } = await Preferences.get({ key: PUSH_DISABLED_KEY });
  return value === 'true';
}

export async function setPushDisabledByUser(disabled: boolean): Promise<void> {
  await Preferences.set({ key: PUSH_DISABLED_KEY, value: String(disabled) });
}
