import * as Sentry from '@sentry/capacitor';
import { syncNotificationToken } from '~/mutations/mobile/uploadPushNotificationsToken';
import { Capacitor } from '@capacitor/core';
import { Dialog } from '@capacitor/dialog';
import { AppLauncher } from '@capacitor/app-launcher';
import { Preferences } from '@capacitor/preferences';
import { openAppSettings } from '~/composables/mobile/useMobilePermissions';
import { FirebaseMessaging, type Notification } from '@capacitor-firebase/messaging';
import { useDeviceInfoStore } from '~/stores/mobile/deviceInfo';
import { prepareNextBundleIfNeeded, applyNewBundle } from '~/composables/mobile/updates/useMobileLiveUpdates';
import { useUploader } from '~/composables/mobile/useUploader';
import { PUSH_NOTIFICATION_ACTIONS } from '~/types/mobile/pushNotificationActions';
import { getPushDisabledByUser, setPushDisabledByUser } from '~/utils/mobile/pushNotificationPrefs';

export const isRegistered = ref<boolean>(false);
export const isNotificationsPermitted = ref<boolean>(false);

const PROMPT_INTERVAL_MS = 12 * 60 * 60 * 1000; // 12 hours
const PROMPT_KEY = 'notifications_last_prompt_time';

const setLastPromptTime = async () => {
  await Preferences.set({ key: PROMPT_KEY, value: String(Date.now()) });
};

const getLastPromptTime = async (): Promise<number> => {
  const { value } = await Preferences.get({ key: PROMPT_KEY });
  return value ? Number(value) : 0;
};

const shouldPromptNow = async (): Promise<boolean> => {
  const now = Date.now();
  const last = await getLastPromptTime();
  return now - last >= PROMPT_INTERVAL_MS;
};

export async function resolveNotificationPermissions() {
  const response = await FirebaseMessaging.checkPermissions();
  if (!isNotificationsPermitted.value) {
    const answer = await FirebaseMessaging.requestPermissions();
    if (answer.receive == 'granted') {
      isNotificationsPermitted.value = true;
    }
    return answer.receive;
  }
  return response.receive;
}

export async function requestAndRegisterPushNotifications() {
  await resolveNotificationPermissions();

  if (await getPushDisabledByUser()) {
    console.debug('[PushNotifications] User disabled push notifications. Skipping registration.');
    return;
  }

  const perm = await FirebaseMessaging.checkPermissions();

  if (perm.receive === 'granted') {
    const deviceInfoStore = useDeviceInfoStore();
    const deviceId = deviceInfoStore.info.id;

    const ntoken = await FirebaseMessaging.getToken();
    if (deviceId) {
      try {
        await syncNotificationToken({
          device_id: deviceId,
          token: ntoken.token,
        });
        isRegistered.value = true;
      } catch (e) {
        console.warn('[PushNotifications] Failed to sync notification token:', e);
      }
    }
  } else if (perm.receive === 'denied') {
    const timeToPrompt = await shouldPromptNow();
    if (timeToPrompt) {
      const { value } = await Dialog.confirm({
        title: 'Push Notifications',
        message:
          'You have denied push notification permissions. In order to receive status updates for your work shifts and projects, you need to allow permissions in your settings.',
        okButtonTitle: 'Settings',
        cancelButtonTitle: 'Cancel',
      });

      await setLastPromptTime();

      if (value) {
        await openAppSettings();
      }
    }
  } else {
    const result = await FirebaseMessaging.requestPermissions();
    console.debug('[PushNotifications] Push notification permission request response:', result.receive);
  }
}

export async function deleteTokenIfExists() {
  const { token } = await FirebaseMessaging.getToken();
  if (token) {
    await FirebaseMessaging.deleteToken();
  } else {
    console.warn('[PushNotifications] Token deletion requested but no token available');
  }
}

const toInternalPath = (url: string): string | null => {
  try {
    const u = new URL(url);
    if (u.protocol === 'validnation:') {
      return u.pathname + u.search + u.hash;
    }
  } catch {}
  return null;
};

export default defineNuxtPlugin(async () => {
  if (!Capacitor.isNativePlatform()) return;

  const router = useRouter();

  await setPushDisabledByUser(false);

  FirebaseMessaging.addListener('tokenReceived', async (event) => {
    console.log('tokenReceived', { event });
    if (await getPushDisabledByUser()) {
      console.debug('[PushNotifications] User disabled push notifications. Skipping token registration.');
      return;
    }
    const result = await FirebaseMessaging.getToken();
    try {
      const deviceInfoStore = useDeviceInfoStore();
      const deviceId = deviceInfoStore.info.id;

      if (isNotificationsPermitted.value) {
        if (deviceId) {
          await syncNotificationToken({
            device_id: deviceId,
            token: result.token,
          });
          isRegistered.value = true;
        } else {
          console.warn(`[PushNotifications] Device ID not initialized yet.`);
        }
      } else {
        console.warn(
          '[PushNotifications] Push notifications are not permitted by the user. Skipping registration of notification token.'
        );
      }
    } catch (e: any) {
      console.warn('[PushNotifications] Push notifications token registration failed.');
    }
  });

  async function executeAction(action: string, payload: any) {
    if (action == PUSH_NOTIFICATION_ACTIONS.download_and_apply_live_update) {
      const url = payload.bundle_url;
      const bundleId = payload.bundle_id;
      await prepareNextBundleIfNeeded(bundleId, url);
      await applyNewBundle();
      return;
    } else if (action == PUSH_NOTIFICATION_ACTIONS.work_shift_upload_data) {
      // upload-only — falls through to uploader.tick() below
    } else if (action == PUSH_NOTIFICATION_ACTIONS.work_shift_end) {
      const mobile = useMobile();
      await mobile?.stop();
    }
    const uploader = useUploader();
    await uploader.tick();
  }

  async function parseSilentNotification(notification: Notification) {
    if (notification.data) {
      let action: string = PUSH_NOTIFICATION_ACTIONS.none;
      let payload: any;

      const currentPlatform = Capacitor.getPlatform();
      if (currentPlatform == 'ios') {
        // @ts-expect-error
        payload = notification.data.aps?.custom_data || notification.data.aps;
        // @ts-expect-error
        action = payload?.action || notification.data?.action;
      } else if (currentPlatform == 'android') {
        payload = notification.data;
        action = payload.action;
      } else {
        console.error('[PushNotifications] Trying to parse silent notification, but platform is unknown. Skipping.');
        return;
      }

      console.debug(`[PushNotifications] action: ${action}; payload: ${JSON.stringify(payload)}`);
      if (action) {
        await executeAction(action, payload);
      }
    }
  }

  FirebaseMessaging.addListener('notificationReceived', async (event) => {
    console.debug(`[PushNotifications] Notification event: ${JSON.stringify(event)}`);
    await parseSilentNotification(event.notification);
    const message = event.notification.body;

    if (message) {
      showToastInfo(message);
    }
  });

  FirebaseMessaging.addListener('notificationActionPerformed', async (notification: any) => {
    const redirectUrl = notification.notification.data.redirectUrl;
    if (redirectUrl) {
      try {
        const internalPath = toInternalPath(redirectUrl);
        if (internalPath) {
          console.log(`[PushNotifications] Navigating to internal path: ${internalPath}`);
          await router.push(internalPath);
          return;
        }

        const { value: canOpen } = await AppLauncher.canOpenUrl({ url: redirectUrl });
        console.debug('[PushNotifications] canOpenUrl:', canOpen);

        if (!canOpen) {
          console.warn(`[PushNotifications] AppLauncher.canOpenUrl returned false: ${redirectUrl}`);
        } else {
          console.info(`[PushNotifications] Opening push URL: ${redirectUrl}`);
          await AppLauncher.openUrl({ url: redirectUrl });
        }
      } catch (e: any) {
        console.error(`[PushNotifications] Failed to open push notification redirect.`);
        Sentry.captureException(e);
      }
    } else {
      console.debug('[PushNotifications] No redirect url was provided in this push notification.');
    }
  });
});
