import * as Sentry from '@sentry/capacitor';
import { AudioManager } from 'audio-manager-plugin';
import type { UploadVadResponse, SegmentMetadata } from 'audio-manager-plugin/src/definitions';
import type { ReceiveCanvasserVoiceData, ReceiveCachedCanvasserVoicesData } from '~/client';
import type { UploadResult } from '~/composables/mobile/audio/useAudioSegmentPool';
import type { SegmentMetadataSnapshot } from '~/types/mobile/audio';
import { refreshAccessToken } from '~/utils/mobile/doNativeRequest';
import { saveAudio, fetchCachedAudioItems, deleteCachedAudioByIds, cachedAudio } from '~/utils/useDb';
import { makeCacheTtlCleanup, uploadCachedGroups, type CachedUploadGroup } from '~/utils/mobile/offlineAudioCache';
import { isDbInitialized } from '~/utils/dbManager';
import { getAppConfig } from '~/composables/mobile/config/useMobileConfig';
import { sendMobileEvent } from '~/utils/mobile/mobileEvents';
import { MESSAGE_TYPES } from '~/types/mobile/trackingSensors';

const receiveUrl: ReceiveCanvasserVoiceData['url'] = '/api/canvasser_voice/receive';
const receiveCachedUrl: ReceiveCachedCanvasserVoicesData['url'] = '/api/canvasser_voice/cached_receive';

// Fired from app-resume lifecycle listeners regardless of auth (SGVS-2602): on the login
// page the DB is never initialized, so the precondition bails out before reading the cache.
export const checkAudioCacheTTL = makeCacheTtlCleanup({
  label: 'checkAudioCacheTTL',
  cols: () => cachedAudio.cols,
  fetchItems: fetchCachedAudioItems,
  deleteByIds: deleteCachedAudioByIds,
  precondition: isDbInitialized,
  onResult: ({ audioPaths, indices, scanned, error }) => {
    // Preserve prior telemetry: emit only when there was something cached to consider.
    if (scanned === 0 && !error) return;
    const eventPayload = error
      ? { error: error instanceof Error ? error.message : String(error), audioPaths, indices }
      : { audioPaths };
    sendMobileEvent(MESSAGE_TYPES.audio_cache_cleanup, eventPayload);
  },
});

async function doRequest(segmentIds: string[], workShiftId: string, deviceId: string) {
  const { token } = useAuth();
  const fullUrl = useRuntimeConfig().public.apiBaseURL + receiveUrl;
  const response = await AudioManager.uploadVadChunk({
    url: fullUrl,
    segmentIds,
    workShiftId,
    deviceId,
    token: token.value as string,
  });
  return response;
}

const DB_TO_PLUGIN_KEY: Record<string, string> = {
  audio_path: 'audioPath',
};

function transformCachedAudioItems(items: any[] | null): any {
  if (!items?.length) return null;

  return items.reduce(
    (acc, item) => {
      Object.entries(item).forEach(([key, value]) => {
        if (key === 'id' || key === 'created_at') return;

        const mappedKey = DB_TO_PLUGIN_KEY[key] ?? key;
        if (!acc[mappedKey]) acc[mappedKey] = [];
        acc[mappedKey].push(value);
      });

      if (!acc._ids) acc._ids = [];
      acc._ids.push(item.id);

      return acc;
    },
    {} as Record<string, any[]>
  );
}

export const uploadCachedAudioIfExists = async () => {
  const { token } = useAuth();
  const fullUrl = useRuntimeConfig().public.apiBaseURL + receiveCachedUrl;
  const batchSize = getAppConfig().AudioUploadBatchSize;

  const items = await fetchCachedAudioItems([
    cachedAudio.cols.id,
    cachedAudio.cols.audioPath,
    cachedAudio.cols.metadata,
  ]);

  if (!items?.length) {
    console.debug(`[uploadCachedAudioIfExists] No cached audio in database`);
    return;
  }

  const groups: CachedUploadGroup[] = [];
  for (let i = 0; i < items.length; i += batchSize) {
    const cached = transformCachedAudioItems(items.slice(i, i + batchSize));
    if (!cached) continue;

    const { _ids, ...chunksPayload } = cached;
    groups.push({
      ids: _ids,
      upload: () => AudioManager.uploadCachedChunks({ token: token.value, url: fullUrl, ...chunksPayload }),
    });
  }

  await uploadCachedGroups('uploadCachedAudioIfExists', groups, deleteCachedAudioByIds, {
    onFailure: checkAudioCacheTTL,
    stopOnFailure: true,
  });
};

const SAVE_AUDIO_RETRY_ATTEMPTS = 3;

// Writes the cached-chunk index row to SQLite. The WAV file already exists on disk at
// response.cachedPath (written natively during the upload-failure branch), and the
// native segment store has already dropped the source segments — so this DB row is the
// only thing that keeps the file reachable for later retry and TTL cleanup. If the
// write is unrecoverable, delete the orphan file and report loudly; losing one chunk is
// strictly better than leaking a WAV file forever on the user's device.
async function cacheAudio(response: UploadVadResponse, workShiftId: string, deviceId: string): Promise<boolean> {
  const metadata = {
    segments: response.segments ?? [],
    workShiftId,
    deviceId,
    wallclockStart: response.wallclockStart ?? '',
    wallclockEnd: response.wallclockEnd ?? '',
    ...(response.spanUploadId ? { spanUploadId: response.spanUploadId } : {}),
  };
  const cachedPath = response.cachedPath!;
  const filename = cachedPath.split('/').pop()!;

  let lastErr: unknown;
  for (let attempt = 1; attempt <= SAVE_AUDIO_RETRY_ATTEMPTS; attempt++) {
    try {
      await saveAudio(metadata, filename);
      return true;
    } catch (error) {
      lastErr = error;
      console.warn(`[uploadSnapshotNative] saveAudio attempt ${attempt}/${SAVE_AUDIO_RETRY_ATTEMPTS} failed:`, error);
    }
  }

  console.error('[uploadSnapshotNative] saveAudio unrecoverable — deleting orphan cached file', lastErr);
  try {
    await AudioManager.deleteCachedChunksByIds({ audioPaths: [cachedPath] });
  } catch (delErr) {
    console.error('[uploadSnapshotNative] Failed to delete orphan cached file (will leak):', delErr);
  }
  Sentry.captureMessage('audio cache-index write failed; cached chunk lost to avoid storage leak', {
    level: 'error',
    extra: {
      cachedPath,
      workShiftId,
      deviceId,
      segmentsCount: metadata.segments.length,
      wallclockStart: metadata.wallclockStart,
      wallclockEnd: metadata.wallclockEnd,
      error: lastErr instanceof Error ? lastErr.message : String(lastErr),
    },
  });
  return false;
}

// Reports segments the native store dropped before upload. The audio bytes are gone,
// but the metadata (GPS, byteLength, timing) captured when the segment first arrived is
// still here — preserve it as much as possible so loss events are debuggable.
function reportEviction(
  requestedCount: number,
  missing: string[] | undefined,
  workShiftId: string,
  metadata: Record<string, SegmentMetadataSnapshot>
): void {
  if (!missing?.length) return;
  const preserved = missing.map((id) => ({ segmentId: id, ...metadata[id] }));
  console.error(
    `[uploadSnapshotNative] ${missing.length} of ${requestedCount} segment(s) evicted from native store — audio lost`,
    preserved
  );
  Sentry.captureMessage('audio segments evicted from native store', {
    level: 'warning',
    extra: {
      workShiftId,
      requestedCount,
      missingCount: missing.length,
      missingSegments: preserved,
    },
  });
}

export const uploadSnapshotNative = async (
  segmentIds: string[],
  workShiftId: string,
  deviceId: string,
  metadata: Record<string, SegmentMetadataSnapshot> = {}
): Promise<UploadResult> => {
  const response = await doRequest(segmentIds, workShiftId, deviceId);

  if (response?.error === 'SEGMENTS_EVICTED') {
    reportEviction(segmentIds.length, response.missingSegmentIds, workShiftId, metadata);
    return { uploadedBytes: 0, retryable: false };
  }

  if (response?.cachedPath) {
    await cacheAudio(response, workShiftId, deviceId);
    reportEviction(segmentIds.length, response.missingSegmentIds, workShiftId, metadata);
    return { uploadedBytes: 0, retryable: false };
  }
  if (response?.error) {
    console.error('[uploadSnapshotNative] Upload failed:', response.error);
    return { uploadedBytes: 0, retryable: false };
  }

  if (response.status === 401) {
    console.warn('[uploadSnapshotNative] Access token expired, refreshing...');
    try {
      await refreshAccessToken();
      const retryResponse = await doRequest(segmentIds, workShiftId, deviceId);
      if (retryResponse?.error === 'SEGMENTS_EVICTED') {
        reportEviction(segmentIds.length, retryResponse.missingSegmentIds, workShiftId, metadata);
        return { uploadedBytes: 0, retryable: false };
      }
      if (retryResponse?.cachedPath) {
        await cacheAudio(retryResponse, workShiftId, deviceId);
        reportEviction(segmentIds.length, retryResponse.missingSegmentIds, workShiftId, metadata);
        return { uploadedBytes: 0, retryable: false };
      }
      if (retryResponse?.error || !retryResponse?.success) {
        console.error('[uploadSnapshotNative] Retry failed after token refresh:', retryResponse?.error);
        const retryable = !retryResponse?.error && retryResponse?.status !== 401;
        return { uploadedBytes: 0, retryable };
      }
      reportEviction(segmentIds.length, retryResponse.missingSegmentIds, workShiftId, metadata);
      console.info('[uploadSnapshotNative] Voice upload success after token refresh');
      const uploaded = segmentIds.length - (retryResponse.missingSegmentIds?.length ?? 0);
      return { uploadedBytes: uploaded, retryable: false };
    } catch (err) {
      console.error(
        '[uploadSnapshotNative] Failed to refresh access token — leaving audio in native store for retry',
        err
      );
      return { uploadedBytes: 0, retryable: true };
    }
  }

  if (!response.success) {
    console.error('[uploadSnapshotNative] Server rejected upload, status:', response.status);
    // Native leaves segments in store on non-2xx — JS can retry.
    return { uploadedBytes: 0, retryable: true };
  }

  reportEviction(segmentIds.length, response.missingSegmentIds, workShiftId, metadata);
  console.info('[uploadSnapshotNative] Voice upload success');
  const uploaded = segmentIds.length - (response.missingSegmentIds?.length ?? 0);
  return { uploadedBytes: uploaded, retryable: false };
};

// Asks native to write whatever segments are still in the store to disk (as if the
// network had failed), then records the chunk in the SQLite index so the regular
// cached-upload path picks it up later. Used by the stop() flow when an online flush
// came back retryable — without this, AudioManager.stop() would wipe the native store
// and the buffered audio would be lost.
export const cacheRemainingBuffer = async (
  segmentIds: string[],
  workShiftId: string,
  deviceId: string,
  metadata: Record<string, SegmentMetadataSnapshot> = {}
): Promise<boolean> => {
  if (segmentIds.length === 0) return true;

  let response: UploadVadResponse;
  try {
    response = (await AudioManager.forceCacheRemaining({
      segmentIds,
      workShiftId,
      deviceId,
    })) as UploadVadResponse;
  } catch (err) {
    console.error('[cacheRemainingBuffer] Force caching failed. Audio data lost: ', err);
    Sentry.captureException(err, { extra: { workShiftId, segmentCount: segmentIds.length } });
    return false;
  }

  reportEviction(segmentIds.length, response.missingSegmentIds, workShiftId, metadata);

  if (!response.cachedPath) {
    if (response.error) {
      console.error('[cacheRemainingBuffer] Failed to cache remaining audio on the native layer: ', response.error);
    }
    return false;
  }

  return cacheAudio(response, workShiftId, deviceId);
};
