import type { LocationQuery } from 'vue-router';

export type JourneyEntry = {
  group: string;
  // vue-router route params/query are not plain string maps: params may repeat
  // (`string[]`) and query values may be null/absent — keep the honest shapes so
  // no lossy cast is needed and navigateTo receives them back unchanged.
  name: string;
  params: Record<string, string | string[]>;
  query: LocationQuery;
};

// Intentionally two independent constants that happen to share the literal 'navJourney':
// STATE_KEY namespaces the Nuxt `useState` entry, STORAGE_KEY the `sessionStorage` entry.
// They are unrelated namespaces — changing one does not (and should not) change the other.
export const NAV_JOURNEY_STORAGE_KEY = 'navJourney';
export const NAV_JOURNEY_STATE_KEY = 'navJourney';

// Pages sharing a backGroup (plus route params) share one journey entry, so tab
// switches inside a section replace the stack top instead of pushing. Extend this
// union when introducing a new tabbed section.
export type BackGroup =
  | 'project-details'
  | 'project-edit'
  | 'project-dashboard'
  | 'share-project-dashboard'
  | 'user-details'
  | 'assignment-details'
  | 'account'
  | 'subcontractor-company'
  | 'system-dashboard'
  | 'campaign-details'
  | 'campaign-dashboard';
export const MAX_JOURNEY_LENGTH = 50;

export function journeyGroupKey(name: string, params: Record<string, unknown>, backGroup?: string): string {
  // URLSearchParams escapes '=' and '&' inside values, so two different param sets can
  // never collide into the same key (e.g. { a: '1&b=2' } vs { a: '1', b: '2' }).
  const search = new URLSearchParams();
  for (const key of Object.keys(params).sort()) {
    search.append(key, String(params[key]));
  }
  return `${backGroup ?? name}:${search.toString()}`;
}

export function applyNavigation(stack: JourneyEntry[], entry: JourneyEntry): JourneyEntry[] {
  const top = stack[stack.length - 1];
  if (top && top.group === entry.group) {
    return [...stack.slice(0, -1), entry];
  }
  const revisitedIndex = stack.findIndex((existing) => existing.group === entry.group);
  if (revisitedIndex !== -1) {
    return [...stack.slice(0, revisitedIndex), entry];
  }
  const next = [...stack, entry];
  return next.length > MAX_JOURNEY_LENGTH ? next.slice(next.length - MAX_JOURNEY_LENGTH) : next;
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function parseStoredJourney(raw: string | null): JourneyEntry[] {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    // Require params/query too: an entry missing them (older schema, tampering, truncation)
    // would reach navigateTo as `params: undefined` and crash on parametrized routes.
    return parsed.filter(
      (entry): entry is JourneyEntry =>
        typeof entry?.group === 'string' &&
        typeof entry?.name === 'string' &&
        isPlainRecord(entry?.params) &&
        isPlainRecord(entry?.query)
    );
  } catch {
    return [];
  }
}

// The route fields recordNavigation reads. Params values are widened to `string |
// number` because Nuxt's typed router surfaces numeric params; they always serialize
// as strings in the URL, so recordNavigation coerces them (see below). Structurally
// satisfied by vue-router's afterEach `to` and by `router.currentRoute.value`, so both
// can be passed directly.
export type RecordableRoute = {
  name: string | symbol | null | undefined;
  params: Record<string, string | number | (string | number)[]>;
  query: LocationQuery;
  meta: { backGroup?: string; skipNavJourney?: boolean };
};

function coerceParams(params: RecordableRoute['params']): Record<string, string | string[]> {
  const result: Record<string, string | string[]> = {};
  for (const [key, value] of Object.entries(params)) {
    result[key] = Array.isArray(value) ? value.map(String) : String(value);
  }
  return result;
}

// Pure recording rule shared by the plugin's initial seed and every afterEach.
// Returns null to mean "skip — leave the stack (and sessionStorage) untouched".
export function recordNavigation(
  stack: JourneyEntry[],
  route: RecordableRoute,
  failure?: unknown
): JourneyEntry[] | null {
  if (failure || !route.name || route.meta.skipNavJourney) return null;
  if (route.name === 'login') return [];
  return applyNavigation(stack, {
    group: journeyGroupKey(String(route.name), route.params, route.meta.backGroup),
    name: String(route.name),
    params: coerceParams(route.params),
    query: { ...route.query },
  });
}
