import type { HttpOptions } from '@capacitor/core';
import type { MobileWorkShiftPauseRequest, MobileWorkShiftPauseResponse, PauseWorkShiftData } from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function pauseWorkShift(payload: MobileWorkShiftPauseRequest): Promise<MobileWorkShiftPauseResponse> {
  const url: PauseWorkShiftData['url'] = '/api/mobile/work_shift/pause';
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<MobileWorkShiftPauseResponse>(options, 'WorkShift|Pause');
}
