import * as Sentry from '@sentry/capacitor';
import type { SegmentEntry, SegmentMetadataSnapshot } from '~/types/mobile/audio';

export type UploadResult = { uploadedBytes: number; retryable: boolean };

export type PoolUpload = (ids: string[], metadata: Record<string, SegmentMetadataSnapshot>) => Promise<UploadResult>;

export function createAudioSegmentPool(maxBytesLimit: number, upload: PoolUpload) {
  let entries: SegmentEntry[] = [];
  let poolBytes = 0;

  function clear(): void {
    entries = [];
    poolBytes = 0;
  }

  function add(entry: SegmentEntry): void {
    entries.push(entry);
    poolBytes += entry.byteLength;
  }

  function hasPending(): boolean {
    return entries.length > 0;
  }

  function snapshotIds(): string[] {
    return entries.map((e) => e.id);
  }

  function buildMetadataMap(source: SegmentEntry[]): Record<string, SegmentMetadataSnapshot> {
    const out: Record<string, SegmentMetadataSnapshot> = {};
    for (const e of source) out[e.id] = e.metadata;
    return out;
  }

  async function flush(): Promise<{ ok: boolean; uploadedBytes: number }> {
    if (entries.length === 0) return { ok: true, uploadedBytes: 0 };

    const snapshot = entries.slice();
    const bytes = poolBytes;
    const ids = snapshot.map((e) => e.id);
    const metadata = buildMetadataMap(snapshot);
    clear();

    try {
      const { uploadedBytes, retryable } = await upload(ids, metadata);
      if (uploadedBytes === 0 && retryable) {
        // Re-queue the original entries (with metadata intact) so a future flush or
        // the stop-time durable-cache path still has full context for loss reporting.
        entries = [...snapshot, ...entries];
        poolBytes += bytes;
        return { ok: false, uploadedBytes: 0 };
      }
      return { ok: uploadedBytes > 0, uploadedBytes };
    } catch (err) {
      entries = [...snapshot, ...entries];
      poolBytes += bytes;
      throw err;
    }
  }

  function autoFlush(): void {
    if (!isFinite(maxBytesLimit) || poolBytes < maxBytesLimit) return;

    (async () => {
      try {
        await flush();
      } catch (err) {
        Sentry.captureException(err);
        console.error('[AudioManager] auto-flush error:', err);
      }
    })();
  }

  return { add, clear, flush, autoFlush, hasPending, snapshotIds, buildMetadataMap, getEntries: () => entries };
}
