import type { HttpOptions } from '@capacitor/core';
import type { GetSelectorProjectListData, SelectorProjectItem, SelectorProjectResponse } from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function findSelectorProjectByIdViaList(
  projectId: string,
  currentUserId: string
): Promise<SelectorProjectItem | null> {
  const url: GetSelectorProjectListData['url'] = '/api/selector/project';
  const options: HttpOptions = {
    url,
    params: { assigned_user_ids: [currentUserId] },
  };
  try {
    const response = await doNativeRequest<SelectorProjectResponse>(options, 'Selector|Project_List');
    return response.items.find((p) => p.id === projectId) ?? null;
  } catch (err: unknown) {
    console.error('Failed to fetch selector project list:', err);
    return null;
  }
}
