import type { HttpOptions } from '@capacitor/core';
import type { DeviceSensorSaveRequest, BatchUploadSensorDataResponse } from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function uploadSensor(request: Array<DeviceSensorSaveRequest>): Promise<BatchUploadSensorDataResponse> {
  const options: HttpOptions = {
    url: '/api/mobile/sensor/batch_upload',
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    data: JSON.stringify({ records: request }),
  };
  return doNativeRequest<BatchUploadSensorDataResponse>(options, 'UploadSensor');
}
