interface MiddlewareOptionsNormalized {
  unauthenticatedOnly: boolean;
  navigateAuthenticatedTo: string;
  navigateUnauthenticatedTo?: string;
}

const defaultNavigateAuthenticatedTo = '/projects';
const loginPage = '/login';

/**
 * Returns `redirect_url` from the route query if it's safe to follow (not the login page).
 * Falls back to the provided `fallback` or `/projects`.
 */
export function getSafeRedirectUrl(
  route: { query: Record<string, any> },
  fallback = defaultNavigateAuthenticatedTo
): string {
  const redirect = route.query?.redirect_url as string | undefined;
  if (redirect && !redirect.startsWith(loginPage)) {
    return redirect;
  }
  return fallback;
}

/**
 * Build a `/login?redirect_url=<currentPath>` URL for the 401 / sign-out flows.
 * `currentPath` is URL-encoded so paths containing `&`, `=`, `#`, or other
 * URL-special characters round-trip cleanly through `useRoute().query`.
 *
 * Mirrors how `middleware/01.auth.global.ts` lets Nuxt's `query: {...}` form
 * encode the value — keeps the supabase, mobile-native, and hey-api 401 paths
 * symmetric with the middleware-driven redirect.
 */
export function buildLoginCallbackUrl(currentPath: string): string {
  return `${loginPage}?redirect_url=${encodeURIComponent(currentPath)}`;
}

/**
 * @returns `undefined` is returned when passed options are `false`
 */
export function normalizeUserOptions(userOptions: MiddlewareMeta | undefined): MiddlewareOptionsNormalized | undefined {
  // false - do not use middleware
  // true - use defaults
  if (typeof userOptions === 'boolean' || userOptions === undefined) {
    return userOptions !== false
      ? {
          // Guest Mode off if `auth: true`
          unauthenticatedOnly: false,
          navigateAuthenticatedTo: defaultNavigateAuthenticatedTo,
          navigateUnauthenticatedTo: undefined,
        }
      : undefined;
  }

  // We check in runtime in case usage error was not caught by TS
  if (typeof userOptions === 'object') {
    // Guest Mode on to preserve compatibility. A warning is also issued to prevent unwanted behaviour
    if (userOptions.unauthenticatedOnly === undefined) {
      userOptions.unauthenticatedOnly = true;
    }

    return {
      unauthenticatedOnly: userOptions.unauthenticatedOnly,
      navigateAuthenticatedTo: userOptions.navigateAuthenticatedTo ?? defaultNavigateAuthenticatedTo,
      navigateUnauthenticatedTo: userOptions.navigateUnauthenticatedTo,
    };
  }
}
