/**
 * Auth hooks for the OpenAPI client (`app.vue` wires them into `client.setConfig`).
 *
 * Extracted from `app.vue` so the refresh/retry logic can be unit-tested
 * without the Nuxt app shell. The hooks are pure: every Nuxt-side dependency
 * (`refresh`, `signOut`, `token`, toast, query-cache, offline flag, retry)
 * is injected by the caller.
 */

import { isSigningOut } from './refreshSingleFlight';
import { isTokenExpired } from '~/utils/authTokenExpiry';

/**
 * Authorization header as the auth store represents it: either `null` when
 * logged out or `Bearer <jwt>` when logged in.
 */
export interface TokenRef {
  readonly value: string | null;
}

export interface AuthPreRequestDeps {
  pendingRefresh: () => Promise<unknown> | null | undefined;
  refresh: () => Promise<unknown>;
  token: TokenRef;
}

/**
 * 30s clock-skew / network-latency buffer for the pre-request expiry check.
 * A token whose `exp` is within this window is treated as already expired so
 * we refresh proactively instead of letting it land on the backend just after
 * it goes invalid (clock drift between client and server, or in-flight latency
 * pushing a borderline token past expiry).
 */
const PRE_REQUEST_EXPIRY_BUFFER_MS = 30_000;

/**
 * Returns the raw JWT to attach to the outgoing request, or `undefined` if
 * no token is stored.
 *
 * - If a refresh is already in flight, await it so the request sees the new
 *   token instead of racing with a stale one.
 * - Otherwise, if the local token is already expired or will expire within
 *   the clock-skew buffer (e.g. a backgrounded tab where `setTimeout` was
 *   throttled past the proactive lead time), kick off a refresh now instead
 *   of paying a guaranteed 401 round-trip.
 *
 * Swallowed errors in both branches let the `onResponse` 401 path handle
 * the failure coherently (it already knows how to sign the user out).
 */
export async function authPreRequest(deps: AuthPreRequestDeps): Promise<string | undefined> {
  const pending = deps.pendingRefresh();
  if (pending) {
    try {
      await pending;
    } catch {
      // Let the onResponse 401 path handle a failed refresh.
    }
  } else {
    const rawJwt = deps.token.value?.split(' ')[1];
    if (rawJwt && isTokenExpired(rawJwt, Date.now() + PRE_REQUEST_EXPIRY_BUFFER_MS)) {
      try {
        await deps.refresh();
      } catch {
        // Same — let the 401 path handle it.
      }
    }
  }
  return deps.token.value ? deps.token.value.split(' ')[1] : undefined;
}

/**
 * Minimal surface of the fetch context we read from / write to. Matches
 * ofetch / $fetch interceptor shape without importing their types directly.
 */
export interface FetchCtx {
  request: unknown;
  options: {
    method?: string;
    body?: unknown;
    query?: Record<string, unknown>;
    params?: Record<string, unknown>;
  };
  response?: { status?: number } | undefined;
}

export interface AuthOnResponseDeps {
  refresh: () => Promise<unknown>;
  signOut: () => Promise<unknown>;
  token: TokenRef;
  retryRequest: (ctx: FetchCtx, authorization: string) => Promise<FetchCtx['response']>;
  cancelQueries: () => void;
  showToastError: (msg: string) => void;
  isOffline: () => boolean;
}

// Guard against a cascade of sign-outs when many requests race a dead refresh
// token: the first 401-after-refresh wins; everyone else is dropped on the floor.
let _signingOut = false;

/**
 * onResponse hook: on a 401, refresh the access token and replay the request
 * once. If the replay also hits 401 (online, and not already signing out),
 * show a toast, cancel in-flight queries, and sign out.
 *
 * No-op if a user-initiated `signOut()` is already in progress — the racing
 * 401 is from a request that fired before the click, and any retry/sign-out
 * here would only surface a spurious "Session expired" toast on top of the
 * deliberate logout.
 */
export async function authOnResponse(ctx: FetchCtx, deps: AuthOnResponseDeps): Promise<void> {
  if (ctx.response?.status !== 401) return;
  if (isSigningOut()) return;

  try {
    await deps.refresh();
    ctx.response = await deps.retryRequest(ctx, deps.token.value ?? '');
  } catch (error: unknown) {
    const e = error as { status?: number; statusCode?: number } | null | undefined;
    const is401 = e?.status === 401 || e?.statusCode === 401;
    // Re-check `isSigningOut()` because logout can begin during the awaits above.
    if (is401 && !_signingOut && !isSigningOut() && !deps.isOffline()) {
      _signingOut = true;
      try {
        deps.showToastError('Session expired. Please log in again.');
        deps.cancelQueries();
        await deps.signOut();
      } finally {
        _signingOut = false;
      }
    }
  }
}

/**
 * Test-only helper. Do not call from application code.
 */
export function __resetForTests(): void {
  _signingOut = false;
}
