import type { HttpOptions } from '@capacitor/core';
import type { NotificationTokenRequest, NotificationTokenResponse, SyncFcmTokenData } from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function syncNotificationToken(payload: NotificationTokenRequest): Promise<NotificationTokenResponse> {
  const url: SyncFcmTokenData['url'] = '/api/mobile/notifications/token';
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<NotificationTokenResponse>(options, 'NotificationToken');
}
