import type { UserRole, AuthTokenData } from '~/client';
import { jwtDecode } from 'jwt-decode';

export const useUserRole = () => {
  const { data, status, token } = useAuth();
  const { loading: userProfileLoading } = useAuthState();
  const decodedPayload: AuthTokenData | null = token.value ? jwtDecode(token.value) : null;
  const isAuthenticated = computed(() => status.value === 'authenticated');
  const userData = computed(() => (data.value ? data.value?.token.user : decodedPayload?.user));
  const userRole = computed(() => userData.value?.role as UserRole);

  const isCanvasser = computed<boolean>(() => userRole.value === 'canvasser');
  const isSubcontractorCanvasser = computed<boolean>(() => userRole.value === 'subcontractor_canvasser');
  const isManager = computed<boolean>(() => userRole.value === 'manager');
  const isAdmin = computed<boolean>(() => userRole.value === 'admin');
  const isAdminOrManager = computed<boolean>(() => isAdmin.value || isManager.value);
  const isManagerOrCanvasser = computed<boolean>(() => isManager.value || isCanvasser.value);
  const isCanvasserOrSubCanvasser = computed<boolean>(() => isCanvasser.value || isSubcontractorCanvasser.value);
  const isManagerOrAnyCanvasser = computed<boolean>(() => isManager.value || isCanvasserOrSubCanvasser.value);
  const accountProblems = computed(() => data.value?.alerts);
  const timezone = computed(() =>
    Intl.DateTimeFormat().resolvedOptions().timeZone
      ? Intl.DateTimeFormat().resolvedOptions().timeZone
      : data.value?.settings.time_zone
  );
  const userId = computed(() => userData.value?.id);
  const fullName = computed(() => `${userData.value?.first_name ?? ''} ${userData.value?.last_name ?? ''}`.trim());
  const email = computed(() => userData.value?.email ?? '');
  const initials = computed(() => getAvatarFallback(fullName.value));
  const avatarUrl = computed(() => data.value?.profile_picture_url ?? undefined);

  return {
    userId,
    fullName,
    email,
    initials,
    avatarUrl,
    userRole,
    isCanvasser,
    isSubcontractorCanvasser,
    isManager,
    isAdmin,
    userData,
    accountProblems,
    isAuthenticated,
    timezone,
    isAdminOrManager,
    isManagerOrCanvasser,
    isCanvasserOrSubCanvasser,
    isManagerOrAnyCanvasser,
    userProfileLoading,
  };
};
