import { AudioManager, type VadVoiceEvent } from 'audio-manager-plugin';
import type { createAudioSegmentPool } from '~/composables/mobile/audio/useAudioSegmentPool';
import type { useAudioRestrictionZones } from '~/composables/mobile/audio/useAudioRestrictionZones';

export function createVadVoiceHandler(
  pool: ReturnType<typeof createAudioSegmentPool>,
  restrictionZones: ReturnType<typeof useAudioRestrictionZones> | null
) {
  const seenChunkIds = new Set<string>();

  function clear(): void {
    seenChunkIds.clear();
  }

  async function handle(evt: VadVoiceEvent): Promise<void> {
    const { segments, chunkId } = evt;

    if (seenChunkIds.has(chunkId)) return;
    seenChunkIds.add(chunkId);

    if (restrictionZones) {
      const firstGps = segments.find((s) => s?.gps_point)?.gps_point;
      if (firstGps) await restrictionZones.ensureZonesLoaded(firstGps);
    }

    const observedAt = Date.now();
    for (const s of segments) {
      if (typeof s?.segmentId !== 'string') continue;

      const gpsPoint = s.gps_point ?? null;

      if (restrictionZones && gpsPoint) {
        restrictionZones.updateStatus(gpsPoint);
      }

      if (restrictionZones && !restrictionZones.isRecentlyAllowed()) {
        AudioManager.releaseSegments({ segmentIds: [s.segmentId] });
        continue;
      }

      // Pool owns the metadata alongside the ID so that retryable re-queues and the
      // stop-time durable-cache path keep full context for loss reporting.
      pool.add({
        id: s.segmentId,
        byteLength: s.byteLength,
        metadata: { gpsPoint, byteLength: s.byteLength, observedAt },
      });
    }

    pool.autoFlush();
  }

  return { handle, clear };
}
