import { sendEvent } from '~/mutations/mobile/sendDeviceEvent';
import { ensureDeviceLinked } from '~/utils/mobile/ensureDeviceLinked';
import { type MobileEventType } from '~/client';
import { useDeviceInfoStore } from '~/stores/mobile/deviceInfo';
import { addPayload } from '~/utils/useDb';
import { deepKeysToSnakeCase } from '~/utils/toSnakeCase';
import { MESSAGE_TYPES } from '~/types/mobile/trackingSensors';

async function composePayload(eventType: MobileEventType, payload?: Record<string, any>) {
  try {
    const deviceId = await useDeviceInfoStore().ensureDeviceId();

    if (!deviceId) {
      console.warn('[MobileEvent] Device id unavailable after init. Skipping event.');
      return;
    }

    const request = {
      device_id: deviceId,
      created_at: new Date().toISOString(),
      event_type: eventType,
      payload: payload ? deepKeysToSnakeCase(payload) : null,
    };
    return request;
  } catch (error: any) {
    console.debug('[MobileEvent] Failed to create request payload: ', error);
  }
}

export const enqueueMobileEvent = async (eventType: MobileEventType, payload?: Record<string, any>) => {
  try {
    const request = await composePayload(eventType, payload);
    if (!request) {
      console.debug('[MobileEvent] Failed to compose event payload. Skipping enqueue.');
      return;
    }
    addPayload(MESSAGE_TYPES.mobile_event, request);
  } catch (error: any) {
    console.error(`[MobileEvent] Failed to add event payload to DB: ${JSON.stringify(error)}`);
  }
};

export const sendMobileEvent = async (eventType: MobileEventType, payload?: Record<string, any>) => {
  try {
    const request = await composePayload(eventType, payload);
    if (!request) {
      console.warn('[MobileEvent] Failed to compose event payload. Skipping.');
      return;
    }

    if (isSessionUnrecoverable() || servingOffline.value) {
      console.debug('[MobileEvent] User is not authenticated or offline. Enqueuing event locally.');
      addPayload(MESSAGE_TYPES.mobile_event, request);
      return;
    }

    // Guarantee the device→user link exists before sending any event — otherwise
    // the backend rejects events from an unlinked device with a 403. Single-flight,
    // so this only triggers one /update_info call regardless of event volume.
    await ensureDeviceLinked().catch(() => {
      // Registration failed (e.g. transient). Fall through: the send below will
      // fail and re-enqueue the event for later retry.
    });

    await sendEvent(request).catch((error: unknown) => {
      if (!isNetworkConnectivityError(error)) console.error('[MobileEvent] Direct send failed:', error);
      addPayload(MESSAGE_TYPES.mobile_event, request);
    });
  } catch {
    console.error('[MobileEvent] Failed to send an event to the server and to save to DB.');
  }
};
