type MiddlewareMeta =
  | boolean
  | {
      /**
       * Whether to allow only unauthenticated users to access this page.
       *
       * Authenticated users will be redirected to `/` or the route defined in `navigateAuthenticatedTo`
       */
      unauthenticatedOnly: boolean;
      /**
       * Where to redirect authenticated users if `unauthenticatedOnly` is set to true
       *
       * @default undefined
       */
      navigateAuthenticatedTo?: string;
      /**
       * Where to redirect unauthenticated users if this page is protected
       *
       * @default undefined
       */
      navigateUnauthenticatedTo?: string;
    };

declare module '#app' {
  interface PageMeta {
    auth?: MiddlewareMeta;
  }
}

declare module 'vue-router' {
  interface RouteMeta {
    auth?: MiddlewareMeta;
  }
}
import { servingOffline } from '~/utils/offlineCache';

export default defineNuxtRouteMiddleware(async (to) => {
  const options = normalizeUserOptions(to.meta.auth);
  if (!options) {
    return;
  }

  const { status, refresh, refreshToken } = useAuth();

  const isGuestMode = options.unauthenticatedOnly;
  let isAuthenticated = status.value === 'authenticated';

  // Access token expired but refresh token may still be valid.
  if (!isAuthenticated && refreshToken.value) {
    try {
      await refresh();
      isAuthenticated = true;
    } catch {
      if (servingOffline.value) {
        console.error('[AUTH] (offline): Failed to refresh token during route change');
        return;
      }
      const { clearToken, clearRefreshToken, data } = useAuthState();
      clearToken();
      clearRefreshToken();
      data.value = null;
    }
  }

  if (isGuestMode && !isAuthenticated) {
    // Guest Mode - unauthenticated users can stay on the page
    return;
  } else if (isGuestMode && isAuthenticated) {
    // Guest Mode - authenticated users should be redirected to another page
    return navigateTo(getSafeRedirectUrl(to, options.navigateAuthenticatedTo), { replace: true });
  } else if (isAuthenticated) {
    // Authenticated users don't need any further redirects
    return;
  }

  const loginPage = '/login';

  // Don't redirect if we're already heading to the login page (prevents infinite loop)
  if (to.path === loginPage) {
    return;
  }

  const matchedRoute = to.matched.length > 0;
  if (!matchedRoute) {
    // Hands control back to `vue-router`, which will direct to the `404` page
    return;
  }

  if (options.navigateUnauthenticatedTo) {
    return navigateTo(options.navigateUnauthenticatedTo, { replace: true });
  }

  // Session is truly gone — notify and redirect to login
  showToastError('Session expired. Please log in again.');

  return navigateTo(
    {
      path: loginPage,
      query: {
        redirect_url: to.fullPath,
      },
    },
    { replace: true }
  );
});
