import type { WifiEntry } from '@codext/capacitor-wifi';
import { Wifi } from '@codext/capacitor-wifi';
import { v4 as uuidv4 } from 'uuid';
import type { MobileModule } from '~/types/mobile/module';
import { SENSOR_TYPES } from '~/types/mobile/trackingSensors';
import { addPayload } from '~/utils/useDb';
import { getAppConfig } from '~/composables/mobile/config/useMobileConfig';
import { useMobileRuntimeState } from '~/composables/mobile/useMobileRuntimeState';

export function createWifiScanner(shiftId: string, deviceId: string): MobileModule {
  const config = getAppConfig();
  const { isAppForeground } = useMobileRuntimeState();

  let networks: WifiEntry[] = [];

  let handle: number | null = null;
  let activeBurst: Promise<void> | null = null;
  let _alive = false;

  async function burstScan() {
    networks = [];

    const startedAt = new Date().toISOString();
    try {
      const result = await Wifi.scanWifi();
      networks = result.wifis;
      const endedAt = new Date().toISOString();

      if (!networks.length) {
        console.log('[Wi‑Fi burst] No networks found');
        return;
      }

      const scanRecord = {
        record_id: uuidv4(),
        work_shift_id: shiftId,
        device_id: deviceId,
        sensor_type: SENSOR_TYPES.wifi,
        started_at: startedAt,
        ended_at: endedAt,
        sensor_readings: networks,
      };

      try {
        await addPayload(SENSOR_TYPES.wifi, scanRecord);
        console.log(`[Wi‑Fi burst] saved 1 record with ${networks.length} networks`);
      } catch (dbErr) {
        console.warn('[Wi‑Fi burst] failed to write scan to DB', dbErr);
      }
    } catch (err) {
      console.error('[Wi‑Fi burst error]', err);
    }
  }

  const start = async () => {
    if (handle !== null) return;
    await burstScan();
    handle = window.setInterval(() => {
      if (!isAppForeground.value) {
        console.log('[Wi‑Fi] skipping scan — app in background');
        return;
      }
      if (activeBurst) return;
      activeBurst = burstScan().finally(() => {
        activeBurst = null;
      });
    }, config.WifiScanIntervalMs);
    _alive = true;
    console.log('[Wi‑Fi] scanner started (interval =', config.WifiScanIntervalMs, 'ms)');
  };

  const stop = async () => {
    if (handle === null) return;
    clearInterval(handle);
    handle = null;
    if (activeBurst) await activeBurst;
    _alive = false;
    console.log('[Wi‑Fi] scanner stopped');
  };
  const isAlive = () => _alive;

  return { name: SENSOR_TYPES.wifi, isAlive, start, stop };
}
