import type { HttpOptions } from '@capacitor/core';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';
import type {
  RestrictedAreasResponse,
  GetRestrictedAreasForAudioRecordingData,
  RestrictedAreasRequest,
} from '~/client';

export async function fetchRestrictedAreas(data: {
  payload: RestrictedAreasRequest;
  projectId: string;
}): Promise<RestrictedAreasResponse> {
  const { payload, projectId } = data;
  const urlTemplate: GetRestrictedAreasForAudioRecordingData['url'] = '/api/projects/{project_id}/restricted_areas';
  const url = urlTemplate.replace('{project_id}', encodeURIComponent(projectId));
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<RestrictedAreasResponse>(options, 'FetchRestrictedAreas');
}
