import {
  getAccountDetails,
  getProjectList,
  getSelectorProjectList,
  getEarningBalance,
  getProjectDetails,
  getPaymentAccountDetails,
  getProjectShortInfo,
} from '~/client';
import type { GetProjectListResponse } from '~/client';
import { useGetChatCursorList } from '~/composables/supabase/useChatList';
import { useGetUnreadChatCount } from '~/composables/supabase/useGetUnreadChatsCount';
import { pinned } from '~/utils/offlineCache';

export function prefetchOfflineData() {
  const { isCanvasser, isAuthenticated } = useUserRole();
  if (!isAuthenticated.value) return;
  console.debug('[offline-prefetch] Prefetching account details and project list for offline use...');
  const fetches: Promise<unknown>[] = [
    pinned(() => getAccountDetails({ composable: '$fetch' })),
    pinned(() => getSelectorProjectList({ composable: '$fetch', query: { statuses: ['active'] } })),
  ];

  if (isCanvasser.value) {
    fetches.push(pinned(() => getEarningBalance({ composable: '$fetch' })));
    fetches.push(pinned(() => getPaymentAccountDetails({ composable: '$fetch' })));
  }

  fetches.push(
    pinned(
      () =>
        getProjectList({
          composable: '$fetch',
          query: { page: 1, size: 10, sort_type: 'desc', sort_by: 'start_date', statuses: ['active', 'draft'] },
        }) as Promise<GetProjectListResponse>
    ).then((res) => {
      const ids = res?.items?.map((p: any) => p.id) ?? [];
      return Promise.all(
        ids.flatMap((id: string) => [
          pinned(() => getProjectShortInfo({ composable: '$fetch', path: { project_id: id } })),
          pinned(() => getProjectDetails({ composable: '$fetch', path: { project_id: id } })),
        ])
      );
    })
  );

  fetches.push(
    useGetChatCursorList({ archived: false, before_cursor: null, after_cursor: null, chat_limit: 20 }).catch(() => {})
  );
  fetches.push(useGetUnreadChatCount().catch(() => {}));

  return Promise.allSettled(fetches).then((results) => {
    console.debug(`[offline-prefetch] Completed prefetching offline data (${results.length} total)`);
    const failed = results.filter((r) => r.status === 'rejected').length;
    if (failed > 0) console.warn(`[offline-prefetch] ${failed}/${results.length} prefetch(es) failed`);
  });
}
