import { Capacitor, CapacitorHttp } from '@capacitor/core';

const PING_URL = 'https://google.com/generate_204';
const PING_TIMEOUT_MS = 2500;
const PING_CACHE_TTL_ONLINE = 5_000;
const PING_CACHE_TTL_OFFLINE_BASE = 5_000;
const PING_CACHE_TTL_OFFLINE_MAX = 60_000;

let _lastPingResult: boolean | null = null;
let _lastPingTime = 0;
let _currentOfflineTTL = PING_CACHE_TTL_OFFLINE_BASE;
let _inflight: Promise<boolean> | null = null;

function _currentTTL(): number {
  if (_lastPingResult === false) return _currentOfflineTTL;
  return PING_CACHE_TTL_ONLINE;
}

export function pingGoogle(): Promise<boolean> {
  const now = Date.now();
  if (_lastPingResult !== null && now - _lastPingTime < _currentTTL()) {
    return Promise.resolve(_lastPingResult);
  }
  if (_inflight) return _inflight;

  _inflight = doPing().finally(() => {
    _inflight = null;
  });
  return _inflight;
}

async function doPing(): Promise<boolean> {
  try {
    if (Capacitor.isNativePlatform()) {
      await CapacitorHttp.request({
        url: PING_URL,
        method: 'HEAD',
        connectTimeout: PING_TIMEOUT_MS,
        readTimeout: PING_TIMEOUT_MS,
      });
    } else {
      await fetch(PING_URL, {
        method: 'HEAD',
        mode: 'no-cors', //preventing HTTP status code verification. We only care about successful response or error (timeout or network error)
        signal: AbortSignal.timeout(PING_TIMEOUT_MS),
      });
    }
    _lastPingResult = true;
    _lastPingTime = Date.now();
    _currentOfflineTTL = PING_CACHE_TTL_OFFLINE_BASE;
    return true;
  } catch {
    _lastPingResult = false;
    _lastPingTime = Date.now();
    _currentOfflineTTL = Math.min(_currentOfflineTTL * 2, PING_CACHE_TTL_OFFLINE_MAX);
    return false;
  }
}
