import { Capacitor } from '@capacitor/core';
import { Dialog } from '@capacitor/dialog';
import {
  PermissionsManager,
  ALL_MODULES,
  type ModuleName,
  type ModuleResult,
  type PermissionsSummary,
} from 'permissions-manager-plugin';
import { NativeSettings, IOSSettings, AndroidSettings } from 'capacitor-native-settings';
import type { SelectorProjectItem } from '~/client';
import { setPermissionsMissing } from '~/composables/mobile/useMobileRuntimeState';

const statusToBool = (s?: ModuleResult['status']) => s === 'granted';

export function projectRequiresAudio(project: SelectorProjectItem | null | undefined): boolean {
  return (
    project?.audio_recording_config?.permission != null && project.audio_recording_config.permission !== 'no_recording'
  );
}

export function getRequiredPermissions(platform: string, project: SelectorProjectItem | null): ModuleName[] {
  const perms: ModuleName[] = ['location', 'motion', 'ble'];
  if (platform !== 'ios') perms.push('wifi');
  if (projectRequiresAudio(project)) perms.push('microphone');
  return perms;
}

export const PERMISSION_META: Record<ModuleName, { label: string; description: string }> = {
  location: {
    label: 'Location is not granted',
    description:
      'Access to Precise Background Location is needed. It is used to track your location during the work shift. We do not track your location during your breaks or outside your work shift.',
  },
  motion: {
    label: 'Motion is not granted',
    description:
      'Access to Motion data is required to start a work shift and is used for tracking movements and distance.',
  },
  ble: {
    label: 'Bluetooth is not granted',
    description: 'Access to Bluetooth is required to start a work shift and is used to look for nearby devices.',
  },
  wifi: {
    label: 'Wi-Fi is not granted',
    description: 'Access to Wi-Fi is required to start a work shift. It is used to look for nearby networks.',
  },
  microphone: {
    label: 'Microphone is not granted',
    description:
      'Access to Microphone is used to enable coaching features and emergency calls. This permission is required to start a work shift.',
  },
  camera: {
    label: 'Camera is not granted',
    description: 'Access to Camera is required to upload ballots and enable other camera-related features.',
  },
};

export function describePermissionIssue(
  platform: string,
  module: ModuleName,
  result?: ModuleResult
): { label: string; description: string } {
  if (module === 'location' && result?.status === 'denied') {
    const details = result.details ?? {};
    if (details.reason === 'needs_always' || details.reason === 'needs_background') {
      return {
        label: 'Background location needed',
        description:
          platform === 'ios'
            ? 'Location access must be set to "Always" so the app can track your work shift in the background.'
            : 'Location access must be set to "Allow all the time" so the app can track your work shift in the background.',
      };
    }
    if (details.accuracy === 'reduced' || details.scope === 'coarse') {
      return {
        label: 'Precise Location needed',
        description: 'Precise Location is off. Turn it on to start a work shift.',
      };
    }
  }
  return PERMISSION_META[module];
}

export async function openAppSettings() {
  const p = Capacitor.getPlatform();
  if (p === 'ios') return NativeSettings.openIOS({ option: IOSSettings.App });
  if (p === 'android') return NativeSettings.openAndroid({ option: AndroidSettings.ApplicationDetails });
}

export async function grantedAllOf(modules: ModuleName[]): Promise<boolean> {
  const perms = useMobilePermissions();
  await perms.refresh();
  return modules.every((m) => perms.statuses.value[m]?.status === 'granted');
}

const _statuses = ref<PermissionsSummary>({});
const _loading = ref(false);

export function useMobilePermissions() {
  const platform = Capacitor.getPlatform();
  const statuses = _statuses;
  const loading = _loading;
  const isNative = Capacitor.isNativePlatform();

  const ensureGrantedAllOf = async (modules: ModuleName[]): Promise<boolean> => {
    await refresh();
    let settingsShown = false;
    for (const module of modules) {
      const status = statuses.value[module]?.status;

      if (status === 'granted' || status === 'not_available') continue;
      if ((status === 'denied' || status === 'restricted') && settingsShown) continue;

      await requestOne(module);

      const after = statuses.value[module]?.status;
      if (after === 'denied' || after === 'restricted') {
        settingsShown = true;
      }
    }
    await refresh();

    return modules.every((m) => statuses.value[m]?.status === 'granted');
  };

  const refresh = async (project: SelectorProjectItem | null = null) => {
    if (!isNative) return;
    loading.value = true;
    try {
      const s = await PermissionsManager.getStatuses({ modules: ALL_MODULES });

      if (platform === 'ios') delete s.wifi;

      statuses.value = s;
      if (project) {
        const required = getRequiredPermissions(platform, project);
        const allPermissionsGranted = required.every((m) => granted.value[m]);
        setPermissionsMissing(!allPermissionsGranted);
      }
    } finally {
      loading.value = false;
    }
  };

  const isReducedAccuracyLocation = (module?: ModuleName, details?: ModuleResult['details']) =>
    module === 'location' && (details?.accuracy === 'reduced' || details?.scope === 'coarse');

  const isLocationBackgroundUpgrade = (module?: ModuleName, details?: ModuleResult['details']) =>
    module === 'location' && (details?.reason === 'needs_always' || details?.reason === 'needs_background');

  const maybePromptToOpenSettings = async (
    st?: ModuleResult['status'],
    module?: ModuleName,
    details?: ModuleResult['details']
  ) => {
    if (st !== 'denied' && st !== 'restricted') return;

    const reducedAccuracy = isReducedAccuracyLocation(module, details);
    const needsBackground = isLocationBackgroundUpgrade(module, details);

    let title: string;
    let message: string;
    if (reducedAccuracy) {
      title = 'Precise Location needed';
      message =
        'Precise Location is required. You currently have Approximate Location enabled. Open Settings to switch it to Precise.';
    } else if (needsBackground) {
      title = 'Background location needed';
      message =
        platform === 'ios'
          ? 'Location access must be set to "Always" so the app can track your work shift in the background. Open Settings to change it.'
          : 'Location access must be set to "Allow all the time" so the app can track your work shift in the background. Open Settings to change it.';
    } else {
      title = 'Permission needed';
      message = module
        ? `Permission for ${module} is denied. Do you want to open Settings to enable it?`
        : 'This permission is denied. Do you want to open Settings to enable it?';
    }

    const { value: go } = await Dialog.confirm({
      title,
      message,
      okButtonTitle: 'Open Settings',
      cancelButtonTitle: 'Not now',
    });

    if (go) await openAppSettings();
  };

  const requestOne = async (module: ModuleName) => {
    if (!isNative) return;
    if (platform === 'ios' && module === 'wifi') return;

    const r = await PermissionsManager.requestPermissions({ modules: [module] });
    statuses.value = { ...statuses.value, ...r };

    await maybePromptToOpenSettings(r[module]?.status, module, r[module]?.details);
    await refresh();
  };

  const granted = computed<Record<ModuleName, boolean>>(() => ({
    location: statusToBool(statuses.value.location?.status),
    ble: statusToBool(statuses.value.ble?.status),
    motion: statusToBool(statuses.value.motion?.status),
    wifi: statusToBool(statuses.value.wifi?.status),
    microphone: statusToBool(statuses.value.microphone?.status),
    camera: statusToBool(statuses.value.camera?.status),
  }));

  return {
    platform,
    statuses,
    granted,
    loading,
    refresh,
    requestOne,
    ensureGrantedAllOf,
  };
}
