import type { RefreshHandler } from '~/types/auth';
import { useAuth, useAuthState } from '#imports';
import { setSigningOut } from '~/composables/auth/refreshSingleFlight';
import { isTokenExpired } from '~/utils/authTokenExpiry';
import { servingOffline } from '~/utils/offlineCache';
import { computeProactiveRefreshDelayMs } from './authRefreshSchedule';

export { computeProactiveRefreshDelayMs };

type AuthComposable = ReturnType<typeof useAuth>;

interface CustomRefreshConfig {
  /**
   * Schedule an access-token refresh shortly before it expires so requests never race
   * a stale token. Removes the 401 → retry burst that otherwise fires on every page
   * load after the 15-minute access-token lifetime elapses.
   */
  enableProactiveRefresh: boolean;
  enableOnWindowFocus: boolean;
  /** How far before expiry (ms) to run the proactive refresh. */
  proactiveLeadTimeMs: number;
}

export class CustomRefreshHandler implements RefreshHandler {
  private config: CustomRefreshConfig;

  private auth: AuthComposable | undefined;
  private mobile: ReturnType<typeof useMobile> | undefined;

  private proactiveTimer: ReturnType<typeof setTimeout> | undefined;
  private scope: ReturnType<typeof effectScope> | undefined;

  private boundVisibilityHandler: () => void;
  private boundFocusHandler: () => void;

  constructor(config: CustomRefreshConfig) {
    this.config = config;
    this.boundVisibilityHandler = this.visibilityHandler.bind(this);
    this.boundFocusHandler = this.focusHandler.bind(this);
  }

  init() {
    this.auth = useAuth();
    this.mobile = useMobile();

    if (import.meta.client) {
      document.addEventListener('visibilitychange', this.boundVisibilityHandler);
      // window.addEventListener('focus', this.boundFocusHandler);
    }

    if (this.config.enableProactiveRefresh && import.meta.client) {
      const { rawToken } = useAuthState();
      this.scope = effectScope(true);
      this.scope.run(() => {
        // Re-arm whenever the access token changes (login, refresh, logout).
        watch(rawToken, () => this.scheduleProactiveRefresh(), { immediate: true });
      });
    }
  }

  destroy() {
    if (import.meta.client) {
      document.removeEventListener('visibilitychange', this.boundVisibilityHandler, false);
      // window.removeEventListener('focus', this.boundFocusHandler); //TODO: turn on when test everything else
    }

    this.clearProactiveTimer();
    this.scope?.stop();
    this.scope = undefined;

    this.auth = undefined;
    this.mobile = undefined;
  }

  private clearProactiveTimer() {
    if (this.proactiveTimer !== undefined) {
      clearTimeout(this.proactiveTimer);
      this.proactiveTimer = undefined;
    }
  }

  private scheduleProactiveRefresh() {
    this.clearProactiveTimer();
    if (!this.auth) return;

    const delay = computeProactiveRefreshDelayMs(
      this.auth.token.value,
      this.auth.refreshToken.value,
      this.config.proactiveLeadTimeMs
    );
    if (delay === null) return;

    this.proactiveTimer = setTimeout(() => {
      this.proactiveTimer = undefined;
      void this.auth?.refresh().catch((err) => {
        // Don't re-arm here — a successful refresh rotates the token and the watcher
        // triggers rescheduling. On failure, visibility/401 paths take over.
        if (!servingOffline.value) {
          console.error('[AUTH] Proactive refresh failed:', err);
        }
      });
    }, delay);
  }

  private focusHandler() {
    // Window focus fires reliably on desktop/app switches (e.g. macOS spaces)
    // where visibilitychange may not trigger. Delegate to the same logic,
    // but only when the document is actually visible (avoids double-firing
    // when both events occur together).
    if (typeof document !== 'undefined' && document.visibilityState === 'visible') {
      this.visibilityHandler();
    }
  }

  private async standDownTracking() {
    setSigningOut(true);
    try {
      await this.mobile?.stop();
    } finally {
      setSigningOut(false);
    }
  }

  private async visibilityHandler() {
    if (typeof document === 'undefined' || document.visibilityState !== 'visible') return;

    const route = useRoute();
    const authMeta = normalizeUserOptions(route.meta.auth);
    const isProtectedPage = !!authMeta && !authMeta.unauthenticatedOnly;

    // No refresh token or refresh token expired — session is gone
    if (!this.auth?.refreshToken.value || isTokenExpired(this.auth.refreshToken.value)) {
      if (this.auth) {
        await this.standDownTracking();
        const { clearToken, clearRefreshToken, data } = useAuthState();
        clearToken();
        clearRefreshToken();
        data.value = null;
      }
      if (isProtectedPage) {
        showToastError('Session expired. Please log in again.');
        await navigateTo(
          {
            path: '/login',
            query: { redirect_url: route.fullPath },
          },
          { replace: true }
        );
      }
      return;
    }

    try {
      await this.auth.refresh();

      // Refresh succeeded — redirect authenticated user away from guest-only pages
      if (authMeta?.unauthenticatedOnly) {
        await navigateTo(getSafeRedirectUrl(route, authMeta.navigateAuthenticatedTo), { replace: true });
      }
    } catch (err: any) {
      const statusCode = err?.statusCode ?? err?.status;

      if (servingOffline.value) {
        console.error('[AUTH] (offline):', err);
        return;
      }

      if (statusCode !== 401) {
        // Error (network, 500) — preserve current state
        console.error('[AUTH] Visibility refresh failed:', err);
        return;
      }

      // 401 — refresh token expired, clean up locally
      // No signOut API call needed — backend already rejected the token
      await this.standDownTracking();
      const { clearToken, clearRefreshToken, data } = useAuthState();
      clearToken();
      clearRefreshToken();
      data.value = null;

      if (isProtectedPage) {
        showToastError('Session expired. Please log in again.');
        await navigateTo(
          {
            path: '/login',
            query: { redirect_url: route.fullPath },
          },
          { replace: true }
        );
      }
      // Guest pages (login) & no-auth pages (share): user stays, session cleaned up silently
    }
  }
}

export default new CustomRefreshHandler({
  enableProactiveRefresh: true,
  enableOnWindowFocus: true,
  proactiveLeadTimeMs: 60_000,
});
