import { Capacitor } from '@capacitor/core';
import { AudioManager } from 'audio-manager-plugin';
import type { AudioSessionAvailability } from 'audio-manager-plugin';
import { useWorkShiftProject } from '~/composables/mobile/projects/useWorkShiftProject';
import { AudioSessionBusyError } from '~/composables/mobile/audio/useAudioSessionAvailability';
import type { MobileModule } from '~/types/mobile/module';
import { cacheRemainingBuffer, uploadSnapshotNative } from '~/utils/mobile/uploadAudioNative';
import { getAppConfig } from '~/composables/mobile/config/useMobileConfig';
import { AUDIO_RECORDING_PERMISSION } from '~/types/mobile/geofencing';
import { useAudioRestrictionZones } from '~/composables/mobile/audio/useAudioRestrictionZones';
import { createAudioSegmentPool } from '~/composables/mobile/audio/useAudioSegmentPool';
import { createVadVoiceHandler } from '~/composables/mobile/audio/useVadVoiceHandler';
import { createWakeWordHandler } from '~/composables/mobile/audio/useWakeWordHandler';
import { getRecentLocations } from '~/utils/useDb';

const SAMPLE_RATE = 16000;
const BYTES_PER_SECOND = SAMPLE_RATE * 2;

// Pre-flight: the OS denies a recording session while another app holds the mic (a phone
// call, Siri, media in another app). The shift-start gate (ensureAudioSessionAvailable)
// already checks once up front; this re-polls right before startVad to cover the race
// where another app grabbed audio between the gate and module start — otherwise startVad
// throws a CoreAudio '!rec' error and audio dies for the shift. On exhaustion it throws the
// same AudioSessionBusyError the gate uses, so the module manager and tracking controller
// surface the busy toast and let the user retry instead of running silently without audio.
const AUDIO_SESSION_RETRY_ATTEMPTS = 5;
const AUDIO_SESSION_RETRY_DELAY_MS = 1000;

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function waitForAudioSessionAvailable(): Promise<void> {
  let last: AudioSessionAvailability = { available: true };
  for (let attempt = 1; attempt <= AUDIO_SESSION_RETRY_ATTEMPTS; attempt++) {
    last = await AudioManager.checkAudioSessionAvailable();
    if (last.available) return;
    console.warn(
      `[AudioManager] Audio session unavailable (${last.reason}); attempt ${attempt}/${AUDIO_SESSION_RETRY_ATTEMPTS}.`
    );
    if (attempt < AUDIO_SESSION_RETRY_ATTEMPTS) await sleep(AUDIO_SESSION_RETRY_DELAY_MS);
  }
  throw new AudioSessionBusyError(last.reason ?? 'other_audio');
}

export function createAudioRecorder(
  shiftId: string,
  deviceId: string
): MobileModule & {
  clear: () => Promise<void>;
  sendFullBuffer: () => Promise<{ ok: boolean; uploadedBytes: number }>;
} {
  const config = getAppConfig();
  const isNative = Capacitor.isNativePlatform();
  const enabled = config.VadEnabled;

  const { project } = useWorkShiftProject();

  // vadHandler is wired at start() time so it captures a freshly-resolved restriction
  // policy. Constructing it at factory time would snapshot whatever permission happened
  // to be cached in `project` and — if that field was absent — silently skip geofencing.
  let vadHandler: ReturnType<typeof createVadVoiceHandler> | null = null;

  const pool = createAudioSegmentPool(BYTES_PER_SECOND * config.VadMaxBufferSize, (ids, metadata) =>
    uploadSnapshotNative(ids, shiftId, deviceId, metadata)
  );
  const wakeWordHandler = createWakeWordHandler(shiftId, deviceId);

  const running = ref(false);
  let removeVoiceListener: (() => void) | null = null;
  let removeWakeWordListener: (() => void) | null = null;

  async function registerListeners(handler: ReturnType<typeof createVadVoiceHandler>): Promise<void> {
    const voiceSub = await AudioManager.addListener('vadVoice', handler.handle);
    removeVoiceListener = () => voiceSub.remove();

    const wakeWordSub = await AudioManager.addListener('wakeWordDetection', wakeWordHandler.handle);
    removeWakeWordListener = () => wakeWordSub.remove();
  }

  function teardownListeners(): void {
    removeVoiceListener?.();
    removeVoiceListener = null;
    removeWakeWordListener?.();
    removeWakeWordListener = null;
  }

  async function start() {
    if (!enabled || !isNative || running.value) return;

    const permission = project.value?.audio_recording_config?.permission;

    if (permission == null) {
      console.warn('[AudioManager] Skipping VAD start: project recording permission unresolved.');
      return;
    }
    if (permission === AUDIO_RECORDING_PERMISSION.NO_RECORDING) {
      console.warn('[AudioManager] Skipping VAD start: recording on this project is not permitted.');
      return;
    }

    const projectId = project.value!.id;
    const needsRestrictionCheck = permission === AUDIO_RECORDING_PERMISSION.FULL_RECORDING_WITH_RESTRICTED_AREA;
    const restrictionZones = needsRestrictionCheck ? useAudioRestrictionZones(projectId) : null;
    const handler = createVadVoiceHandler(pool, restrictionZones);
    vadHandler = handler;

    pool.clear();
    handler.clear();

    try {
      await registerListeners(handler);
      await AudioManager.setPermissionMode({ mode: permission });
      await waitForAudioSessionAvailable();
      const vadResult = await AudioManager.startVad({
        bufferSeconds: config.VadMaxSegmentSeconds,
        threshold: config.VadModelThreshold,
        includeProbabilities: false,
        gateWakeWord: config.VadGateWakeWord,
        wakeWordHangoverMs: config.VadWakeWordHangoverMs,
      });

      if (vadResult.wakeWordAvailable === false) {
        console.warn('[AudioManager] WakeWord model unavailable on this device — wake word detection disabled.');
      }

      running.value = true;
      console.info('[AudioManager] VAD session started successfully.');
      await warmFromHistory();
    } catch (err) {
      teardownListeners();
      throw err;
    }
  }

  async function warmFromHistory() {
    const history = await getRecentLocations();
    if (history.length === 0) return;
    for (const loc of history.slice().reverse()) {
      try {
        await AudioManager.updateLocation(loc);
      } catch (e) {
        console.warn('[AudioManager] Failed to warm location history:', e);
      }
    }
  }

  async function stop() {
    if (!running.value) return;

    try {
      // Attempt the normal flush first — this is the happy path where pending audio
      // uploads before native resources are torn down.
      let flushResult: { ok: boolean; uploadedBytes: number };
      try {
        flushResult = await pool.flush();
      } catch (err) {
        console.warn('[AudioManager] Failed to flush data while stopping VAD session:', err);
        flushResult = { ok: false, uploadedBytes: 0 };
      }

      // If flush reported a retryable failure (5xx, token-refresh-throw, etc.) the pool
      // still holds IDs that native has in its store. AudioManager.stop() will wipe that
      // store shortly — force-cache to disk first so the buffer isn't silently lost.
      if (!flushResult.ok && pool.hasPending()) {
        const ids = pool.snapshotIds();
        const metadata = pool.buildMetadataMap(pool.getEntries());
        const cached = await cacheRemainingBuffer(ids, shiftId, deviceId, metadata);
        if (cached) {
          console.info(`[AudioManager] Force-cached ${ids.length} pending segment(s) on stop.`);
        } else {
          console.error(`[AudioManager] Failed to force-cache ${ids.length} pending segment(s) on stop.`);
        }
      }
      pool.clear();

      await AudioManager.stop();
    } catch (e: unknown) {
      console.warn('[AudioManager] Unexpected error happened during VAD session stopping:', e);
    } finally {
      teardownListeners();
      running.value = false;
      console.info('[AudioManager] VAD session finished successfully.');
    }
  }

  async function clear(): Promise<void> {
    pool.clear();
    vadHandler?.clear();
    await AudioManager.clearSegmentStore();
  }

  return {
    name: 'audio',
    isAlive: () => running.value,
    async start() {
      await start();
    },
    async stop() {
      await stop();
    },
    clear,
    sendFullBuffer: pool.flush,
  };
}
