<template>
  <Card v-if="card" :class="cn(largeAlertVariants({ variant }), props.class)">
    <CardContent>
      <State
        :description="description"
        :md-description="mdDescription"
        :icon="icon"
        :icon-class="iconClass"
        :title="title"
      >
        <slot />
      </State>
    </CardContent>
  </Card>
  <State
    v-else
    :class="props.class"
    :description="description"
    :md-description="mdDescription"
    :icon="icon"
    :icon-class="iconClass"
    :title="title"
    ><slot
  /></State>
</template>

<script setup lang="ts">
import type { HTMLAttributes, FunctionalComponent } from 'vue';
import { cn } from '@/lib/utils';
import { largeAlertVariants, type LargeAlertVariants } from './variants';

interface Props {
  variant?: LargeAlertVariants['variant'];
  class?: HTMLAttributes['class'];
  card?: boolean;
  title?: string;
  description?: string | null;
  mdDescription?: string | null;
  icon?: FunctionalComponent | string;
  iconClass?: string;
}
const props = withDefaults(defineProps<Props>(), {
  variant: 'default',
  class: '',
  card: false,
  icon: undefined,
  iconClass: '',
  title: '',
  description: null,
  mdDescription: null,
});
</script>

