import { BackgroundFetch, type BackgroundFetchConfig } from '@transistorsoft/capacitor-background-fetch';

export async function initBackgroundFetch(syncFn: () => Promise<void>) {
  const fetchConfig: BackgroundFetchConfig = {
    minimumFetchInterval: 15, // minutes
    stopOnTerminate: true, // stop background task when app is killed
    startOnBoot: false, // start on device boot
    enableHeadless: false, // don't allow running after app is terminated
    requiredNetworkType: BackgroundFetch.NETWORK_TYPE_ANY,
  };

  await BackgroundFetch.configure(
    fetchConfig,
    async (taskId: string) => {
      console.info('[BackgroundFetch] Starting background task:', taskId);
      try {
        await syncFn();
      } finally {
        await BackgroundFetch.finish(taskId);
      }
    },
    async (taskId) => {
      console.warn('[BackgroundFetch] Timeout: ', taskId);
      await BackgroundFetch.finish(taskId);
    }
  );
}

export async function destructBackgroundFetch() {
  await BackgroundFetch.stop();
}
