import { Capacitor } from '@capacitor/core';
import { Udid } from 'capacitor-udid';

export default defineNuxtPlugin(async (nuxtApp) => {
  if (!Capacitor.isNativePlatform()) {
    console.debug('[SentryNative] not native -> skip init');
    return;
  }
  const {
    build,
    environment,
    sentryRelease: release,
    version,
    sentry: { dsnAndroid, dsnIos },
  } = useRuntimeConfig().public;

  const platform = Capacitor.getPlatform() as 'ios' | 'android';
  const dsn = platform === 'ios' ? (dsnIos ?? null) : (dsnAndroid ?? null);

  if (!dsn) {
    console.warn(`[SentryNative] Missing DSN for platform "${platform}" — skipping Sentry init`);
    return;
  }

  const app = nuxtApp.vueApp;
  const SentryCap = await import('@sentry/capacitor');
  const SentryVue = await import('@sentry/vue');

  console.debug(`[SentryNative] Environment set: "${useRuntimeConfig().public.environment}"`);
  console.debug(
    `[SentryNative] Version set: "${useRuntimeConfig().public.version}" + build "${useRuntimeConfig().public.build}"`
  );

  const dist = String(build);

  let deviceId = '';
  try {
    deviceId = (await Udid.getUdid()).value;
  } catch (err) {
    console.warn('[SentryNative] Udid lookup failed:', err);
  }

  let sentryLogLevels = ['warn', 'error'];
  if (environment === 'production') {
    sentryLogLevels.push('info');
  }

  await Promise.race([
    new Promise<void>((resolve) => {
      SentryCap.init(
        {
          dsn,
          release,
          dist,
          environment,
          tracesSampleRate: 0.25,
          debug: true,
          initialScope: {
            tags: { device_id: deviceId },
          },
          _experiments: {
            enableLogs: true,
            beforeSendLog: (log: any) => ({
              ...log,
              attributes: { ...log.attributes, 'user.device_id': deviceId },
            }),
          },
          integrations: [
            SentryVue.consoleLoggingIntegration({ levels: sentryLogLevels as any }),
            SentryVue.feedbackIntegration({
              colorScheme: 'light',
              useSentryUser: {
                name: 'username',
                email: 'email',
              },
              autoInject: false,
            }),
            SentryVue.httpClientIntegration({
              failedRequestStatusCodes: [400, 403, 404, [500, 599]],
            }),
          ],
        },
        (opts: any) => {
          (SentryVue as any).init({ app, ...opts });
          resolve();
        }
      );
    }),
    new Promise<void>((resolve) => setTimeout(resolve, 5000)),
  ]);
  const client = (SentryCap as any).getClient?.();
  console.debug('[SentryNative] client =', client ? 'OK' : 'MISSING');

  const { data: userData } = useAuth();

  function setSentryUser() {
    const user = userData.value?.token
      ? {
          id: userData.value.token.user.id,
          email: userData.value.token.user.email,
          username: `${userData.value.token.user.first_name} ${userData.value.token.user.last_name}`,
        }
      : null;
    SentryCap.setUser(user);
    SentryVue.setUser(user);
  }

  setSentryUser();
  watch(userData, setSentryUser);
});
