import { App as CapacitorApp, type AppState } from '@capacitor/app';
import { LiveUpdate } from '@capawesome/capacitor-live-update';
import { SplashScreen } from '@capacitor/splash-screen';
import { checkLiveUpdates } from '~/composables/mobile/updates/useMobileLiveUpdates';
import { useMobilePermissions } from '~/composables/mobile/useMobilePermissions';
import { useMobileRuntimeState, setIsAppForeground } from '~/composables/mobile/useMobileRuntimeState';
import { useWorkShiftProject } from '~/composables/mobile/projects/useWorkShiftProject';
import { sendMobileEvent } from '~/utils/mobile/mobileEvents';
import { checkAudioCacheTTL } from '~/utils/mobile/uploadAudioNative';
import { restorePageAfterLiveUpdate } from '~/composables/mobile/updates/useMobileLiveUpdates';
import { useShiftSession } from '~/composables/mobile/shift/useMobileShift';

const SYNC_THROTTLE_MS = 15 * 60 * 1000;
let lastSyncAt = 0;

export default defineNuxtPlugin(async () => {
  const {
    public: { environment },
  } = useRuntimeConfig();
  const allowLiveUpdates = environment !== 'local';

  let coldStartChecked = false;

  const mobile = useMobile();
  if (!mobile) {
    console.debug('[MobileListeners] Not a mobile native platform. Skipping mobile listeners.');
    return;
  }

  const { refresh } = useMobilePermissions();
  const { isTracking } = useMobileRuntimeState();
  const { project } = useWorkShiftProject();

  if (allowLiveUpdates) {
    checkLiveUpdates('silent').finally(() => {
      coldStartChecked = true;
    });
  } else {
    LiveUpdate.ready().catch((err) => console.warn('[LiveUpdate] ready() failed:', err));
  }

  await restorePageAfterLiveUpdate();

  //Initialize app state
  const state = await CapacitorApp.getState();
  setIsAppForeground(state.isActive);

  const onResume = async () => {
    if (allowLiveUpdates) {
      if (coldStartChecked) checkLiveUpdates('prompt');
    } else {
      console.debug('[LiveUpdates] Live updates are not allowed by the app config.');
    }
    await checkAudioCacheTTL();
    await mobile.checkAndStopIfClosed();
  };

  const onStateChange = async (state: AppState) => {
    setIsAppForeground(state.isActive);
    await refresh();

    const app_state = state.isActive ? 'foreground' : 'background';
    await sendMobileEvent('app_state', { state: app_state });

    if (state.isActive) {
      // Watchdog (SGVS-2678): app returning to the foreground is a natural checkpoint to catch
      // a module handle or native watcher left running after the JS side believed pause/stop
      // had already torn tracking down.
      mobile.reconcileTrackerState().catch((err: unknown) => {
        console.error('[MobileListeners] Tracker-state reconcile on foreground failed:', err);
      });
      await refresh(project.value);
      if (isTracking.value) {
        const now = Date.now();
        if (now - lastSyncAt >= SYNC_THROTTLE_MS) {
          lastSyncAt = now;
          console.debug('[MobileListeners] Syncing data on app resume.');
          const { syncAndUploadWorkShiftData } = useShiftSession();
          syncAndUploadWorkShiftData().catch(console.error);
        }
      }
    }
  };

  // Listeners are never removed — this is intentional. Plugin scope = app lifetime,
  // so these persist for the entire session. Capacitor's onUnmounted is not applicable here.
  await CapacitorApp.addListener('resume', onResume);
  await CapacitorApp.addListener('appStateChange', onStateChange);
});
