import { API_CACHE_NAME, API_CACHE_TTL, IMAGE_CACHE_NAME, MAX_CACHE_BYTES } from '~/config/cache';
import { pingGoogle } from '~/utils/pingGoogle';
import { useMobileRuntimeState } from '~/composables/mobile/useMobileRuntimeState';

const H_SIZE = 'X-Cache-Size';
const H_STORED = 'X-Cache-Stored-At';
const H_PINNED = 'X-Cache-Pinned';

let _pinNext = false;
const env = import.meta.env.NUXT_PUBLIC_ENVIRONMENT || 'local';

export function pinned<T>(fetchFn: () => Promise<T>): Promise<T> {
  _pinNext = true;
  const p = fetchFn();
  _pinNext = false;
  return p;
}

export const servingOffline = ref(false);

export function clearOfflineFlag() {
  servingOffline.value = false;
  if (useMobileForWeb().isMobile) {
    const { hasNetworkError } = useMobileRuntimeState();
    hasNetworkError.value = false;
  }
}

export async function cacheClear(): Promise<void> {
  apiCachePromise = null;
  await Promise.all([caches.delete(API_CACHE_NAME), caches.delete(IMAGE_CACHE_NAME)]);
  navigator.serviceWorker?.controller?.postMessage('CACHE_CLEARED');
  clearOfflineFlag();
}

let apiCachePromise: Promise<Cache> | null = null;
function getApiCache(): Promise<Cache> {
  if (!apiCachePromise) {
    apiCachePromise = caches.open(API_CACHE_NAME);
  }
  return apiCachePromise;
}

function toUrl(key: string): string {
  if (key.startsWith('http://') || key.startsWith('https://')) return key;
  return `https://offline-cache.invalid/${encodeURIComponent(key)}`;
}

// --- Concurrency lock ---

let _storeLock: Promise<void> = Promise.resolve();

function withStoreLock<T>(fn: () => Promise<T>): Promise<T> {
  const prev = _storeLock;
  let resolve: () => void;
  _storeLock = new Promise<void>((r) => {
    resolve = r;
  });
  return prev.then(fn).finally(() => resolve!());
}

// --- Debug logging ---

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

// --- Cache introspection (reads metadata from response headers, no body parsing) ---

interface CacheEntry {
  url: string;
  size: number;
  storedAt: number;
  pinned: boolean;
}

async function listEntries(): Promise<{ entries: CacheEntry[]; total: number }> {
  const cache = await getApiCache();
  const requests = await cache.keys();
  const entries: CacheEntry[] = [];
  let total = 0;

  for (const req of requests) {
    const res = await cache.match(req);
    if (!res) continue;
    const size = parseInt(res.headers.get(H_SIZE) ?? '0', 10);
    if (!size || isNaN(size)) {
      await cache.delete(req); // don't skip request without size header, but remove them to avoid future confusion and free up space
      continue;
    }
    const storedAt = parseInt(res.headers.get(H_STORED) ?? '0', 10);
    const pinned = res.headers.get(H_PINNED) === '1';
    total += size;
    entries.push({ url: req.url, size, storedAt, pinned });
  }

  return { entries, total };
}

async function logCacheDebug(label: string): Promise<void> {
  const { entries, total } = await listEntries();
  const pinnedCount = entries.filter((e) => e.pinned).length;

  let storageInfo = '';
  if (navigator.storage?.estimate) {
    try {
      const { usage, quota } = await navigator.storage.estimate();
      storageInfo = ` | device storage: ${formatBytes(usage ?? 0)} / ${formatBytes(quota ?? 0)}`;
    } catch {}
  }

  console.debug(
    `[offline-cache] ${label} — cache: ${formatBytes(total)} / ${formatBytes(MAX_CACHE_BYTES)} (${entries.length} entries, ${pinnedCount} pinned)${storageInfo}`
  );
}

// --- Eviction ---

async function evictIfNeeded(incomingSize: number): Promise<boolean> {
  const { entries, total } = await listEntries();
  let needed = total + incomingSize - MAX_CACHE_BYTES;
  if (needed <= 0) return true;

  const cache = await getApiCache();
  const now = Date.now();

  // First evict expired entries (regardless of pinned status) to free space they no longer earn.
  const expired = entries.filter((e) => now - e.storedAt > API_CACHE_TTL);
  for (const entry of expired) {
    await cache.delete(new Request(entry.url));
    console.debug(`[offline-cache] evicted expired ${entry.url} (${formatBytes(entry.size)})`);
    needed -= entry.size;
  }

  if (needed <= 0) return true;

  // Then evict unpinned non-expired entries (oldest stored first).
  const evictable = entries
    .filter((e) => !e.pinned && now - e.storedAt <= API_CACHE_TTL)
    .sort((a, b) => a.storedAt - b.storedAt);

  for (const entry of evictable) {
    if (needed <= 0) break;
    await cache.delete(new Request(entry.url));
    console.debug(`[offline-cache] evicted ${entry.url} (${formatBytes(entry.size)})`);
    needed -= entry.size;
  }

  return needed <= 0;
}

// --- Public API ---

export async function cacheStore(key: string, data: unknown, pinned?: boolean): Promise<void> {
  try {
    await withStoreLock(async () => {
      const timestamp = Date.now();
      const body = JSON.stringify({ data, timestamp });
      const size = new Blob([body]).size;

      if (size > MAX_CACHE_BYTES) return;

      const cache = await getApiCache();
      const url = toUrl(key);

      // Check existing entry to preserve pinned status and factor its size into eviction
      let isPinned = pinned ?? false;
      let existingSize = 0;
      const existing = await cache.match(new Request(url));
      if (existing) {
        existingSize = parseInt(existing.headers.get(H_SIZE) ?? '0', 10);
        if (!isPinned && existing.headers.get(H_PINNED) === '1') isPinned = true;
      }

      // Eviction considers net new space needed (incoming minus existing entry being replaced)
      const hasRoom = await evictIfNeeded(size - existingSize);
      if (!hasRoom) {
        // Old entry stays intact — no data loss
        console.debug(`[offline-cache] skipped ${key} (${formatBytes(size)}) — no room after eviction`);
        await logCacheDebug('after skip');
        return;
      }

      // Safe to delete and replace now that we confirmed room
      await cache.delete(new Request(url));

      await cache.put(
        new Request(url),
        new Response(body, {
          headers: {
            'Content-Type': 'application/json',
            [H_SIZE]: String(size),
            [H_STORED]: String(timestamp),
            [H_PINNED]: isPinned ? '1' : '0',
          },
        })
      );

      await logCacheDebug(`stored ${key} (${formatBytes(size)}, ${isPinned ? 'pinned' : 'unpinned'})`);
    });
  } catch (err) {
    console.warn('[offline-cache] cacheStore failed:', err);
  }
}

export async function cacheGet<T = unknown>(key: string): Promise<T | undefined> {
  const cache = await getApiCache();
  const response = await cache.match(new Request(toUrl(key)));
  if (!response) return undefined;
  const { data, timestamp } = await response.json();
  if (Date.now() - timestamp > API_CACHE_TTL) {
    await cache.delete(new Request(toUrl(key)));
    return undefined;
  }
  return data as T;
}

export function isNetworkConnectivityError(error: any): boolean {
  // Browser/OS offline
  if (env === 'local' || env === 'development') {
    console.debug(
      '[offline-cache] checking connectivity error:',
      error,
      JSON.stringify(error),
      error.name,
      error.message
    );
    console.debug(typeof navigator !== 'undefined', !navigator.onLine);
  }
  if (typeof navigator !== 'undefined' && !navigator.onLine) return true;

  // Request timeout (AbortSignal.timeout / ofetch timeout) — treat as connectivity issue
  if (error?.name === 'TimeoutError' || error?.cause?.name === 'TimeoutError') return true;

  // Native layer errors (iOS / Android) — only codes that unambiguously mean
  // "no internet". Codes like NSURLErrorCannotConnectToHost or ConnectException
  // indicate the network works but the server is unreachable, so they are excluded.
  const code = String(error?.code ?? '');
  const msg = String(error?.message ?? '');
  const nativeText = `${code} ${msg}`;
  if (env === 'local' || env === 'development') {
    console.debug('[offline-cache] error detected:', nativeText);
  }
  if (
    nativeText.includes('NSURLErrorNotConnectedToInternet') ||
    nativeText.includes('NSURLErrorDataNotAllowed') ||
    nativeText.includes('NSURLErrorCannotFindHost') ||
    nativeText.includes('UnknownHostException') ||
    nativeText.includes('NoRouteToHostException')
  )
    return true;

  const nativeTextLower = nativeText.toLowerCase();
  if (
    nativeTextLower.includes('network connection was lost') ||
    nativeTextLower.includes('request timed out') ||
    nativeTextLower.includes('internet connection appears to be offline')
  )
    return true;

  // FetchError with no response and TypeError "Failed to fetch" are ambiguous —
  // CORS errors produce identical errors in the browser. Only treat as connectivity
  // when the browser reports offline. On mobile, native codes above already handle it.
  const { isMobile } = useMobileForWeb();
  if (typeof navigator !== 'undefined' && navigator.onLine && !isMobile) return false;

  // FetchError with no response (ofetch) — network didn't complete
  if (error?.name === 'FetchError' && !error?.response) return true;

  // Raw fetch TypeError — network-specific messages only
  if (error instanceof TypeError) {
    const msg = error.message.toLowerCase();
    if (
      msg.includes('failed to fetch') ||
      msg.includes('networkerror') ||
      msg.includes('internet connection appears to be offline') ||
      msg.includes('network request failed')
    )
      return true;
  }
  return false;
}

// Returns true = offline, false = online, undefined = skipped (app inactive in background).
// When undefined, no state is mutated — prevents background network failures from
// incorrectly triggering the offline screen on resume.
export async function setOfflineFlag(): Promise<boolean | undefined> {
  const { isMobile } = useMobileForWeb();
  const { hasNetworkError, isAppForeground } = useMobileRuntimeState();

  const isActive = isMobile ? isAppForeground.value : true;

  if (!isActive) return undefined;

  const reachable = await pingGoogle();
  if (!reachable) {
    servingOffline.value = true;
    if (isMobile) {
      hasNetworkError.value = true;
    }
  }
  return !reachable;
}

export function hashBody(body: unknown): string {
  if (body === undefined || body === null || body === '') return '';
  const str = typeof body === 'string' ? body : JSON.stringify(body);
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash + str.charCodeAt(i)) | 0;
  }
  return hash.toString(36);
}

type FetchFn = (request: any, opts?: any) => Promise<any>;

export function createCachingFetch(baseFetch: FetchFn): FetchFn {
  return (request: any, opts?: any) => {
    const method = (opts?.method ?? 'GET').toUpperCase();
    const url = typeof request === 'string' ? request : String(request);
    const cacheKey = `${url}:${method}:${hashBody(opts?.body)}`;
    const shouldPin = _pinNext;

    const finalOpts = {
      // TODO: make it 30 seconds, and a big number for VDB import process
      // timeout: 5 * 1000, // 5 second timeout to fail fast and serve from cache if needed
      ...opts,
    };

    return baseFetch(request, finalOpts)
      .then((data: any) => {
        clearOfflineFlag();
        cacheStore(cacheKey, data, shouldPin || undefined).catch(() => {});
        return data;
      })
      .catch(async (error: any) => {
        if (isNetworkConnectivityError(error)) {
          await setOfflineFlag();
          const cached = await cacheGet(cacheKey);
          if (cached !== undefined) {
            return cached;
          }
        }
        throw error;
      });
  };
}
