import type { HttpOptions } from '@capacitor/core';
import type { WakeWordDetectionEventData, WakeWordEventRequest, WakeWordEventResponse } from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function sendWakeWordEvent(payload: WakeWordEventRequest): Promise<WakeWordEventResponse> {
  const url: WakeWordDetectionEventData['url'] = '/api/canvasser_voice/wake_word_event';
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<WakeWordEventResponse>(options, 'WakeWordEvent');
}
