import type { RequestBleDeviceOptions, ScanResult } from '@capacitor-community/bluetooth-le';
import { BleClient } from '@capacitor-community/bluetooth-le';
import { v4 as uuidv4 } from 'uuid';
import type { MobileModule } from '~/types/mobile/module';
import { addPayload } from '~/utils/useDb';
import { SENSOR_TYPES } from '~/types/mobile/trackingSensors';
import { getAppConfig } from '~/composables/mobile/config/useMobileConfig';
import { useMobileRuntimeState } from '~/composables/mobile/useMobileRuntimeState';

export function createBleScanner(shiftId: string, deviceId: string): MobileModule {
  const config = getAppConfig();
  const { isAppForeground } = useMobileRuntimeState();

  let devices: ScanResult[] = [];

  let scanSub: any = null; // requestLEScan returns void but attaches a .remove() at runtime
  let intervalHandle: number | null = null;
  let activeBurst: Promise<void> | null = null;
  let _alive = false;
  let scanTimeoutId: ReturnType<typeof setTimeout> | null = null;
  let scanTimeoutResolve: (() => void) | null = null;

  const scanOpts: RequestBleDeviceOptions = {
    allowDuplicates: config.BleScanAllowDuplicates,
  };

  async function startScan() {
    scanSub = await BleClient.requestLEScan(scanOpts, (result) => {
      devices.push(result);
    });
  }

  async function stopScan() {
    if (scanSub) {
      scanSub.remove();
      scanSub = null;
    }
    return BleClient.stopLEScan().catch(() => {});
  }

  async function burstScan() {
    devices = [];
    try {
      const startedAt = new Date().toISOString();
      await startScan();
      await new Promise<void>((resolve) => {
        scanTimeoutResolve = resolve;
        scanTimeoutId = setTimeout(resolve, config.BleScanDurationMs);
      });
      scanTimeoutId = null;
      scanTimeoutResolve = null;
      await stopScan();
      const endedAt = new Date().toISOString();

      try {
        if (devices.length === 0) {
          console.log('[BLE burst] No devices found during scan');
          return;
        }
        const payload = {
          record_id: uuidv4(),
          work_shift_id: shiftId,
          device_id: deviceId,
          sensor_type: SENSOR_TYPES.ble,
          started_at: startedAt,
          ended_at: endedAt,
          sensor_readings: devices,
        };
        await addPayload(SENSOR_TYPES.ble, payload);
        console.log('[BLE burst] wrote scan to DB', devices.length, 'devices');
      } catch (dbErr) {
        console.warn('failed to write scan to DB', dbErr);
      }
    } catch (err) {
      console.error('[BLE burst error]', err);
    }
  }
  const start = async () => {
    await BleClient.initialize();

    const enabled = await BleClient.isEnabled();
    if (!enabled) {
      console.warn('[BLE] Bluetooth is not enabled');
      return;
    }
    console.log('[BLE] Bluetooth is enabled, starting scanner', intervalHandle);
    if (intervalHandle !== null) return;

    if (!activeBurst) {
      activeBurst = burstScan().finally(() => {
        activeBurst = null;
      });
    }

    intervalHandle = window.setInterval(async () => {
      if (!isAppForeground.value) {
        console.log('[BLE] skipping scan — app in background');
        return;
      }
      if (activeBurst) return;
      activeBurst = burstScan().finally(() => {
        activeBurst = null;
      });
    }, config.BleScanIntervalMs);

    _alive = true;
    console.log(
      '[BLE] scanner started (interval =',
      config.BleScanIntervalMs,
      'ms; duration =',
      config.BleScanDurationMs,
      'ms)'
    );
  };

  const stop = async () => {
    if (intervalHandle === null) return;
    clearInterval(intervalHandle);
    intervalHandle = null;

    await stopScan();
    if (scanTimeoutId) {
      clearTimeout(scanTimeoutId);
      scanTimeoutId = null;
    }
    if (scanTimeoutResolve) {
      scanTimeoutResolve();
      scanTimeoutResolve = null;
    }
    if (activeBurst) await activeBurst;
    _alive = false;
    console.log('[BLE] scanner stopped');
  };
  const isAlive = () => _alive;

  return { name: SENSOR_TYPES.ble, isAlive, start, stop };
}
