/**
 * SGVS-1921 proactive-refresh scheduling math.
 *
 * Extracted from `AuthRefreshHandler.ts` so the decisions are unit-testable
 * without pulling in the Nuxt runtime (`#imports`, `useRoute`, `useAuth`,
 * `effectScope`, …) that the handler class needs at `init()` time.
 */

import { getTokenExpiryMs, isTokenExpired } from '~/utils/authTokenExpiry';

/**
 * How long (ms, non-negative) until the proactive refresh should fire for
 * this access token. `null` means "don't schedule" — one of:
 *
 *   - access or refresh token is missing
 *   - access token is unparseable or has no numeric `exp` claim
 *   - refresh token is already expired (the 401 interceptor / route
 *     middleware handles sign-out from here; the scheduler's job is done)
 *
 * Inputs accept either a raw JWT or a `Bearer <jwt>` string because
 * `getTokenExpiryMs` / `isTokenExpired` both split on `.` and tolerate the
 * extra `Bearer ` prefix.
 */
export function computeProactiveRefreshDelayMs(
  accessToken: string | null | undefined,
  refreshToken: string | null | undefined,
  leadTimeMs: number,
  now: number = Date.now()
): number | null {
  if (!accessToken || !refreshToken) return null;
  if (isTokenExpired(refreshToken, now)) return null;
  const expiryMs = getTokenExpiryMs(accessToken);
  if (expiryMs === null) return null;
  return Math.max(0, expiryMs - now - leadTimeMs);
}
