import { CapacitorSQLite, SQLiteConnection, type capSQLiteVersionUpgrade } from '@capacitor-community/sqlite';

const sqlite = new SQLiteConnection(CapacitorSQLite);

let DB_VERSION: number = 5;
let DB_NAME: string;

export function setDbName(environment: string) {
  DB_NAME = `${environment}-internal-data`;
}

export const tables = {
  payloads: {
    name: 'payloads',
    cols: {
      id: 'id',
      userId: 'user_id',
      dataType: 'data_type',
      payload: 'payload',
    },
  },
  settings: {
    name: 'settings',
    cols: {
      id: 'id',
      config: 'config',
    },
  },
  cachedAudio: {
    name: 'cached_audio',
    cols: {
      id: 'id',
      metadata: 'metadata',
      createdAt: 'created_at',
      audioPath: 'audio_path',
    },
  },
  cachedWakeWordClips: {
    name: 'cached_wake_word_clips',
    cols: {
      id: 'id',
      metadata: 'metadata',
      createdAt: 'created_at',
      audioPath: 'audio_path',
    },
  },
  recentLocations: {
    name: 'recent_locations',
    cols: {
      id: 'id',
      timestamp: 'timestamp',
      location: 'location',
    },
  },
} as const;

async function registerMigrations() {
  const upgrades: capSQLiteVersionUpgrade[] = [
    {
      toVersion: 2,
      statements: [
        `DROP TABLE IF EXISTS ${tables.payloads.name};`,
        `CREATE TABLE IF NOT EXISTS ${tables.payloads.name} (
          ${tables.payloads.cols.id} INTEGER PRIMARY KEY AUTOINCREMENT,
          ${tables.payloads.cols.userId} TEXT NOT NULL,
          ${tables.payloads.cols.dataType} TEXT NOT NULL,
          ${tables.payloads.cols.payload} TEXT NOT NULL
        );`,
        `CREATE INDEX IF NOT EXISTS idx_payloads_type ON ${tables.payloads.name}(${tables.payloads.cols.dataType});`,

        `DROP TABLE IF EXISTS ${tables.settings.name};`,
        `CREATE TABLE IF NOT EXISTS ${tables.settings.name} (
          ${tables.settings.cols.id} INTEGER PRIMARY KEY CHECK (${tables.settings.cols.id} = 1),
          ${tables.settings.cols.config} TEXT NOT NULL
        );`,
      ],
    },
    {
      toVersion: 3,
      statements: [
        `CREATE TABLE IF NOT EXISTS ${tables.cachedAudio.name} (
          ${tables.cachedAudio.cols.id} INTEGER PRIMARY KEY AUTOINCREMENT,
          ${tables.cachedAudio.cols.createdAt} INTEGER NOT NULL,
          ${tables.cachedAudio.cols.metadata} TEXT NOT NULL,
          ${tables.cachedAudio.cols.audioPath} TEXT NOT NULL
        );`,
        `CREATE INDEX idx_cached_audio_created_at ON ${tables.cachedAudio.name}(${tables.cachedAudio.cols.createdAt});`,
      ],
    },
    {
      toVersion: 4,
      statements: [
        `CREATE TABLE IF NOT EXISTS ${tables.recentLocations.name} (
          ${tables.recentLocations.cols.id} INTEGER PRIMARY KEY AUTOINCREMENT,
          ${tables.recentLocations.cols.timestamp} INTEGER NOT NULL,
          ${tables.recentLocations.cols.location} TEXT NOT NULL
        );`,
        `CREATE INDEX IF NOT EXISTS idx_recent_locations_id ON ${tables.recentLocations.name}(${tables.recentLocations.cols.id});`,
      ],
    },
    {
      toVersion: 5,
      statements: [
        `CREATE TABLE IF NOT EXISTS ${tables.cachedWakeWordClips.name} (
          ${tables.cachedWakeWordClips.cols.id} INTEGER PRIMARY KEY AUTOINCREMENT,
          ${tables.cachedWakeWordClips.cols.createdAt} INTEGER NOT NULL,
          ${tables.cachedWakeWordClips.cols.metadata} TEXT NOT NULL,
          ${tables.cachedWakeWordClips.cols.audioPath} TEXT NOT NULL
        );`,
        `CREATE INDEX idx_cached_wake_word_clips_created_at ON ${tables.cachedWakeWordClips.name}(${tables.cachedWakeWordClips.cols.createdAt});`,
      ],
    },
  ];

  await sqlite.addUpgradeStatement(DB_NAME, upgrades);
}

let db: import('@capacitor-community/sqlite').SQLiteDBConnection | null = null;

// Reports whether initDb() has been invoked (i.e. the DB name was set via setDbName).
// Note: this flips true at the very start of initDb(), before migrations and the
// connection finish. It is a "was init ever started" gate for lifecycle listeners that
// fire pre-login, not a "connection is open and ready" check.
export function isDbInitialized(): boolean {
  return Boolean(DB_NAME);
}

export async function getDB() {
  if (db) return db;

  if (!DB_NAME) {
    throw new Error('Database is not initialized. Call initDb() before accessing the database.');
  }

  await sqlite.checkConnectionsConsistency();
  const has = (await sqlite.isConnection(DB_NAME, false)).result;
  db = has
    ? await sqlite.retrieveConnection(DB_NAME, false)
    : await sqlite.createConnection(DB_NAME, false, 'no-encryption', DB_VERSION, false);

  await db.open();

  return db;
}

export async function initDb(environment: string): Promise<void> {
  setDbName(environment);
  await registerMigrations();
  const db = await getDB();
  await db.execute('PRAGMA foreign_keys = ON;');
}

export async function closeDB(): Promise<void> {
  if (!db) return;
  await sqlite.closeConnection(DB_NAME, false);
  db = null;
}
