export default defineNuxtRouteMiddleware(async (to, from) => {
  const { isMobile } = useMobileForWeb();

  const requiredPlatform = to.meta?.platform;
  console.log('requiredPlatform:', requiredPlatform, 'isMobile:', isMobile, 'tometa:', to.meta);

  if (requiredPlatform === 'mobile' && !isMobile) {
    throw createError({ statusCode: 404, statusMessage: `Page not found: ${to.path}` });
  }
});
