import { marked, parser, parse, parseInline } from 'marked';
import DomPurify from 'isomorphic-dompurify';

export default defineNuxtPlugin(({ vueApp }) => {
  const renderer = new marked.Renderer();

  // Could use tailwindcss typography plugin instead
  // Override the heading method to add different classes for each level
  renderer.heading = (item) => {
    const classes: Record<number, string> = {
      1: 'text-4xl font-extrabold tracking-tight lg:text-5xl mt-12 first:mt-0 pb-4 last:pb-0',
      2: 'text-3xl font-semibold tracking-tight mt-10 first:mt-0 pb-4 last:pb-0',
      3: 'text-2xl font-semibold tracking-tight mt-8 first:mt-0 pb-4 last:pb-0',
      4: 'text-xl font-semibold tracking-tight mt-6 first:mt-0 pb-4 last:pb-0',
      5: 'text-lg font-semibold tracking-tight mt-4 first:mt-0 pb-4 last:pb-0',
      6: 'text-base font-semibold tracking-tight mt-2 first:mt-0 pb-4 last:pb-0',
    };
    const className = classes[item.depth] || 'heading';
    return `<h${item.depth} class="${className}">${item.text}</h${item.depth}>`;
  };

  renderer.listitem = (item) => {
    const text = parse(item.text);
    return `<li class="[&>ul]:ml-4 [&>ol]:ml-4">${text}</li>`;
  };

  renderer.list = (token) => {
    const items = token.items.map(renderer.listitem).join('\n');
    console.log(token);
    if (token.ordered) return `<ol class="list-decimal ml-4">${items}</ol>`;
    else return `<ul class="list-disc ml-4">${items}</ul>`;
  };

  renderer.paragraph = (item) => {
    const text = /^(<h[1-6]>|<ul>|<ol>|<li>)/.test(item.text) ? item.text : parseInline(item.raw);
    return `<p class="leading-7">${text}</p>`;
  };

  renderer.blockquote = (item) => {
    const text = parse(item.text);
    return `<blockquote class="mt-4 border-l-2 pl-4 italic">${text}</blockquote>`;
  };

  // Set the custom renderer in marked options
  marked.setOptions({
    renderer: renderer,
    breaks: true,
  });

  marked.use({ renderer });

  return {
    provide: {
      marked: (raw: string) => {
        const rawHtml = marked(raw || '') as string;
        return DomPurify.sanitize(rawHtml);
      },
    },
  };
});
