import { Device } from '@capacitor/device';
import { getAppConfig } from '~/composables/mobile/config/useMobileConfig';
import { useMobilePermissions } from '~/composables/mobile/useMobilePermissions';
import { deepKeysToSnakeCase } from '~/utils/toSnakeCase';

async function getBatteryState() {
  const info = await Device.getBatteryInfo();
  let sensor_readings = { batteryLevel: Math.round((info.batteryLevel ?? -0.01) * 100), isCharging: info.isCharging };
  return sensor_readings;
}

export async function getDeviceStatePayload() {
  const config = getAppConfig();
  const battery = await getBatteryState();

  const perms = useMobilePermissions();
  await perms.refresh();

  const permission_payload = {
    wifi: perms.granted.value.wifi,
    ble: perms.granted.value.ble,
    gps: perms.granted.value.location,
    motion: perms.granted.value.motion,
  };
  const payload = {
    permissions: permission_payload,
    battery: battery,
    config: { ...config },
  };

  const snakeCasePayload = deepKeysToSnakeCase(payload);

  return snakeCasePayload;
}
