import { LocalNotifications } from '@capacitor/local-notifications';
import type { LocalNotificationSchema, DeliveredNotificationSchema } from '@capacitor/local-notifications';
import { Capacitor } from '@capacitor/core';

// Deliberately outside the JS process's typical foreground/background reload lifecycle — these
// IDs are stable across app restarts so `clear()` (e.g. on resume/stop) can always find and
// cancel whatever `show()` may have scheduled in a previous JS context.
const BREAK_NOTIFICATION_ID = 26780;

// The plugin's `Schedule.every` field (see ScheduleEvery in
// @capacitor/local-notifications/dist/esm/definitions.d.ts) only accepts fixed units —
// 'minute' | 'hour' | 'day' | ... — with no custom interval multiplier, so "repeat every 15
// minutes" is not expressible as a single repeating schedule. `Schedule.on` is a cron-style
// wall-clock matcher (e.g. "at minute 15 of every hour"), not a relative interval either.
// Deviation from the task brief's sketch: instead of one repeating reminder, iOS gets one-shot
// `{ at }` notifications fired every 15 minutes through the 4-hour mark (the break that motivated
// this feature ran 4.2h). That's 16 reminders + 1 ongoing notification = 17 scheduled at once;
// iOS caps pending local notifications at 64, leaving 47 of headroom.
const BREAK_REMINDER_ID_BASE = 26781;
const BREAK_REMINDER_OFFSETS_MIN = Array.from({ length: 16 }, (_, i) => (i + 1) * 15); // 15, 30, ..., 240
const BREAK_REMINDER_IDS = BREAK_REMINDER_OFFSETS_MIN.map((_, i) => BREAK_REMINDER_ID_BASE + i);

const ALL_NOTIFICATION_IDS = [BREAK_NOTIFICATION_ID, ...BREAK_REMINDER_IDS];

export function useBreakNotification() {
  async function ensurePermission(): Promise<boolean> {
    const status = await LocalNotifications.checkPermissions();
    if (status.display === 'granted') return true;
    const requested = await LocalNotifications.requestPermissions();
    return requested.display === 'granted';
  }

  async function show(startedAt: Date): Promise<void> {
    // Notification permission is optional UX sugar on top of the break banner (Task 5 step 4) —
    // if the user has denied it, degrade silently to banner-only rather than surfacing a toast
    // or throwing on every pause.
    if (!(await ensurePermission())) return;

    const platform = Capacitor.getPlatform();
    const timeStr = startedAt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    const notifications: LocalNotificationSchema[] = [
      {
        id: BREAK_NOTIFICATION_ID,
        title: 'On break — tracking paused',
        body: `Break started at ${timeStr}. Tap Resume in the app when you're back.`,
        // `ongoing` (un-swipeable) and `autoCancel` (survive a tap) are Android-only fields
        // per the plugin's definitions; harmless no-ops on iOS.
        ongoing: platform === 'android',
        autoCancel: false,
      },
    ];

    if (platform === 'ios') {
      BREAK_REMINDER_OFFSETS_MIN.forEach((offsetMin, index) => {
        notifications.push({
          id: BREAK_REMINDER_IDS[index],
          title: 'Still on break',
          body: `Tracking has been paused since ${timeStr}.`,
          schedule: { at: new Date(startedAt.getTime() + offsetMin * 60_000) },
          // `sound` on iOS resolves via `UNNotificationSound(named:)` (see
          // LocalNotificationsPlugin.swift), which looks up a bundled audio file by this exact
          // name — this app doesn't ship one. Passing a name that can't be resolved is an
          // undocumented-but-consistently-observed way to make iOS fall back to the system's
          // default alert sound instead of delivering silently (see e.g.
          // https://github.com/expo/expo/issues/40954 and Apple developer forum reports of the
          // same fallback). Android needs no `sound` field — it already plays its channel's
          // default notification sound.
          sound: 'default',
        });
      });
    }

    await LocalNotifications.schedule({ notifications });
  }

  async function clear(): Promise<void> {
    await LocalNotifications.cancel({
      notifications: ALL_NOTIFICATION_IDS.map((id) => ({ id })),
      // Cancelling an id with nothing pending (e.g. Android, which never scheduled reminders)
      // is expected, not an error — swallow so callers never need their own try/catch.
    }).catch(() => {});

    // iOS only: `cancel()` above maps to `removePendingNotificationRequests` (see cancel() in
    // LocalNotificationsPlugin.swift) — it only clears PENDING requests. A reminder that already
    // fired while the break was ongoing stays visible in Notification Center as a DELIVERED
    // notification until explicitly removed. Android's `cancel()` already dismisses the visible
    // notification too (LocalNotificationManager.cancel -> dismissVisibleNotification), so this
    // second call would be a no-op there. Scoped to our own id list — never
    // removeAllDeliveredNotifications(), which would also wipe notifications unrelated to the
    // break feature (e.g. push).
    if (Capacitor.getPlatform() === 'ios') {
      // DeliveredNotificationSchema requires `title`/`body` even though only `id` is used for
      // matching on the native side (see removeDeliveredNotifications() in
      // LocalNotificationsPlugin.swift, which reads only "id" off each entry) — fill them with
      // placeholders to satisfy the type.
      const delivered: DeliveredNotificationSchema[] = ALL_NOTIFICATION_IDS.map((id) => ({
        id,
        title: '',
        body: '',
      }));
      await LocalNotifications.removeDeliveredNotifications({ notifications: delivered }).catch(() => {});
    }
  }

  return { show, clear };
}
