import * as Sentry from '@sentry/capacitor';
import { Network } from '@capacitor/network';
import { uploadSensor } from '~/mutations/mobile/uploadSensors';
import {
  deletePayloadsByIds,
  getAllByType,
  getMaxPayloadId,
  getAllByWorkShift,
  getPendingPayloadCount,
} from '~/utils/useDb';
import { uploadShiftEnd } from '~/mutations/mobile/uploadShiftEnd';
import { uploadShiftBreakEventBatch } from '~/utils/mobile/uploadShiftBreakEventBatch';
import { useRecorderStore } from '~/stores/mobile/vadRecorder';
import { sendEventBatch } from '~/mutations/mobile/sendDeviceEvent';
import { useDeviceInfoStore } from '~/stores/mobile/deviceInfo';
import { setOfflineFlag } from '~/utils/offlineCache';
import { sendMobileEvent } from '~/utils/mobile/mobileEvents';
import { getDeviceStatePayload } from '~/utils/mobile/deviceInfoUtils';
import { AppExitReason } from 'app-exit-reason-plugin';
import { SENSOR_TYPES, MESSAGE_TYPES } from '~/types/mobile/trackingSensors';
import { uploadAllCachedAudioIfExists } from '~/utils/mobile/uploadAllCachedAudio';
import { ensureDeviceLinked } from '~/utils/mobile/ensureDeviceLinked';
import { sendWakeWordEvent } from '~/mutations/mobile/sendWakeWordEvent';
import type { WakeWordEventRequest } from '~/client';
import { getAppConfig } from '~/composables/mobile/config/useMobileConfig';
import {
  setUnsyncedShiftIds,
  setUploadProgress,
  incrementUploadProgress,
  setLastUploadHadErrors,
} from '~/composables/mobile/useMobileRuntimeState';
import { isNetworkConnectivityError } from '~/utils/offlineCache';

let inFlight: Promise<void> | null = null;

type Rows = Awaited<ReturnType<typeof getAllByType>>;

export function useUploader() {
  const deviceInfo = useDeviceInfoStore().info;

  // shift_end only uploads when all other payload types for the same shift have been drained,
  // so it manages its own partial deletion rather than using the standard delete-all path.
  async function uploadShiftEndBatch(rows: Rows): Promise<number> {
    const payloads = rows.map(({ _rowId, ...data }) => ({ ...data, data_complete: false }));
    const workshiftIds = [...new Set(payloads.map((p) => p.work_shift_id).filter(Boolean))];
    const remainingByShift = await Promise.all(workshiftIds.map((id) => getAllByWorkShift(id, 1)));

    const idsToDelete: number[] = [];
    const payloadsToUpload: typeof payloads = [];

    for (let i = 0; i < workshiftIds.length; i++) {
      const workshiftId = workshiftIds[i];
      const remaining = remainingByShift[i];
      const shiftEndPayloads = payloads.filter((p) => p.work_shift_id === workshiftId);
      const shiftEndIds = rows.filter((r) => r.work_shift_id === workshiftId).map((r) => r._rowId);

      if (!remaining.length) {
        shiftEndPayloads.forEach((p) => {
          p.data_complete = true;
        });
        payloadsToUpload.push(...shiftEndPayloads);
        idsToDelete.push(...shiftEndIds);
      } else {
        console.info(`[Uploader] Deferring shift_end for ${workshiftId}: ${remaining.length} payloads still pending`);
      }
    }

    if (payloadsToUpload.length > 0) {
      await uploadShiftEnd(payloadsToUpload);
      await deletePayloadsByIds(idsToDelete);
    }

    return payloadsToUpload.length;
  }

  async function uploadMobileEventBatch(rows: Rows) {
    const deviceId = deviceInfo.id;
    if (!deviceId) throw new Error('[Uploader] DeviceId is null during mobile event sending');
    // Guarantee the device→user link before draining queued events — otherwise the
    // backend 403s the batch. Single-flight, so this shares the request with the
    // direct-send path. Swallow failures: sendEventBatch then fails and the rows stay
    // queued (flushType won't delete them) for the next tick to retry.
    await ensureDeviceLinked().catch(() => {});
    await sendEventBatch({ device_id: deviceId, events: rows.map(({ _rowId, ...data }) => data) });
  }

  async function uploadWakeWordBatch(rows: Rows) {
    for (const { _rowId, ...data } of rows) {
      try {
        await sendWakeWordEvent(data as WakeWordEventRequest);
      } catch (err: any) {
        const status = err?.statusCode ?? err?.status;
        if (status === 400 || status === 404) {
          Sentry.captureException(err);
          continue;
        }
        throw err;
      }
    }
  }

  async function flushType(type: string, maxId?: number): Promise<number> {
    const rows = await getAllByType(type, getAppConfig().UploaderBatchSize, maxId);
    if (!rows.length) return 0;
    try {
      if (type === MESSAGE_TYPES.shift_end) return await uploadShiftEndBatch(rows);
      if (type === MESSAGE_TYPES.shift_break_event) return await uploadShiftBreakEventBatch(rows);
      if (type === MESSAGE_TYPES.mobile_event) await uploadMobileEventBatch(rows);
      else if (type === MESSAGE_TYPES.wake_word_event) await uploadWakeWordBatch(rows);
      else await uploadSensor(rows.map(({ _rowId, ...data }) => data));

      await deletePayloadsByIds(rows.map((r) => r._rowId));
      return rows.length;
    } catch (err) {
      console.error(`[Uploader] ${type} batch failed: ${err}`);
      if (!isNetworkConnectivityError(err)) Sentry.captureException(err);
      throw err;
    }
  }

  async function drainType(type: string, maxId: number, showProgress: boolean, limitIterations: boolean) {
    const MAX_ITERATIONS = 50;
    let flushed: number;
    let iterations = 0;
    do {
      flushed = await flushType(type, maxId);
      if (showProgress && flushed > 0) incrementUploadProgress(flushed);
      iterations++;
    } while (flushed > 0 && (!limitIterations || iterations < MAX_ITERATIONS));
    if (limitIterations && iterations >= MAX_ITERATIONS) {
      console.warn(`[Uploader] drainType(${type}) hit iteration limit (${MAX_ITERATIONS})`);
    }
  }

  async function sendDeviceStateSyncEvent() {
    const payload = await getDeviceStatePayload();
    // Live resource-pressure sample; also persists natively so the last sample survives an OS
    // kill and can be read on the next launch. Tolerate older native builds (live updates) / web.
    let resourceSnapshot: unknown = null;
    try {
      resourceSnapshot = await AppExitReason.getResourceSnapshot();
    } catch {
      resourceSnapshot = null;
    }
    await sendMobileEvent(MESSAGE_TYPES.device_state_sync, { ...payload, resourceSnapshot });
  }

  async function runTick({
    showProgress,
    limitIterations,
  }: {
    showProgress: boolean;
    limitIterations: boolean;
  }): Promise<void> {
    let hadErrors = false;
    try {
      // Skip cleanly when the session is gone (e.g. background fetch firing after logout)
      // so we don't run drain loops against protected routes and spew Sentry errors.
      if (isSessionUnrecoverable()) {
        console.debug('[Uploader] Skipping tick — user is not authenticated.');
        return;
      }

      const net = await Network.getStatus();
      if (!net.connected) {
        await setOfflineFlag();
        hadErrors = true;
        return;
      }

      await sendDeviceStateSyncEvent();

      const maxId = await getMaxPayloadId();
      const total = await getPendingPayloadCount(maxId);
      if (showProgress && total > 0) setUploadProgress({ isUploading: true, total, uploaded: 0 });
      await sendMobileEvent(MESSAGE_TYPES.data_upload, { timestamp: Date.now(), data: { maxId } });

      const independentTypes = [
        ...Object.values(SENSOR_TYPES),
        ...Object.values(MESSAGE_TYPES).filter((t) => t !== MESSAGE_TYPES.shift_end),
      ];
      const results = await Promise.allSettled(
        independentTypes.map((type) => drainType(type, maxId, showProgress, limitIterations))
      );
      if (results.some((r) => r.status === 'rejected')) hadErrors = true;

      try {
        await drainType(MESSAGE_TYPES.shift_end, maxId, showProgress, limitIterations);
      } catch (err) {
        hadErrors = true;
        console.error('[Uploader] shift_end drain failed:', err);
        if (!isNetworkConnectivityError(err)) Sentry.captureException(err);
      }

      const recorderStore = useRecorderStore();
      const tail = await Promise.allSettled([recorderStore.sendFullBuffer(), uploadAllCachedAudioIfExists()]);
      if (tail.some((r) => r.status === 'rejected')) hadErrors = true;
    } catch (err) {
      hadErrors = true;
      console.error('[Uploader] tick failed:', err);
      if (!isNetworkConnectivityError(err)) Sentry.captureException(err);
    } finally {
      setUnsyncedShiftIds(await checkForUnsyncedData());
      setUploadProgress({ isUploading: false, total: 0, uploaded: 0 });
      setLastUploadHadErrors(hadErrors);
    }
  }

  // Concurrent callers join the in-flight tick so `lastUploadHadErrors` always
  // reflects the result of the tick they actually awaited.
  async function tick(opts: { showProgress?: boolean; limitIterations?: boolean } = {}): Promise<void> {
    const { showProgress = false, limitIterations = true } = opts;
    if (inFlight) {
      // Don't let an unlimited drain (sync now / end shift) ride on an in-flight
      // limited tick — that would silently cap it at MAX_ITERATIONS. Run a fresh
      // tick once the current one settles instead of joining the weaker request.
      if (!limitIterations) return inFlight.catch(() => {}).then(() => tick(opts));
      return inFlight;
    }
    inFlight = runTick({ showProgress, limitIterations }).finally(() => {
      inFlight = null;
    });
    return inFlight;
  }

  return { tick, sendDeviceStateSync: sendDeviceStateSyncEvent };
}
