import { registerPlugin } from '@capacitor/core';
import type { PermissionsManagerPlugin, ModuleName } from './definitions';

export type { PermissionsManagerPlugin, ModuleName, ModuleResult, PermissionsSummary } from './definitions';

export const PermissionsManager = registerPlugin<PermissionsManagerPlugin>('PermissionsManager', {
  web: () => import('./web').then((m) => new m.PermissionsManagerWeb()),
});

export const ALL_MODULES: ModuleName[] = ['ble', 'location', 'motion', 'wifi', 'microphone', 'camera'];

export const requestAll = () => PermissionsManager.requestPermissions({ modules: ALL_MODULES });

export const getAllStatuses = () => PermissionsManager.getStatuses({ modules: ALL_MODULES });

export const request = (modules: ModuleName[] = ALL_MODULES) =>
  PermissionsManager.requestPermissions({ modules: normalizeModules(modules) });

export const getStatuses = (modules: ModuleName[] = ALL_MODULES) =>
  PermissionsManager.getStatuses({ modules: normalizeModules(modules) });

function normalizeModules(mods: readonly string[] = []): ModuleName[] {
  const set = new Set<ModuleName>();
  for (const m of mods) {
    const v = m.toLowerCase() as ModuleName;
    if ((ALL_MODULES as readonly string[]).includes(v)) set.add(v);
  }
  return set.size ? Array.from(set) : ALL_MODULES;
}
