import { cva, type VariantProps } from 'class-variance-authority';

export { default as LargeAlert } from './LargeAlert.vue';

export const largeAlertVariants = cva('relative w-full rounded-lg border p-4', {
  variants: {
    variant: {
      default: 'bg-background text-foreground',
      destructive: 'border-destructive/50 dark:border-destructive [&>svg]:text-destructive',
      warning: 'border-warning-foreground/50 dark:border-warning-foreground [&>svg]:text-warning-foreground',
      success:
        'border-success-foreground/50 text-foreground dark:border-success-foreground [&>svg]:text-success-foreground',
    },
  },
  defaultVariants: {
    variant: 'default',
  },
});

export type LargeAlertVariants = VariantProps<typeof largeAlertVariants>;
