import { defineNuxtPlugin, useAuth, useAuthState } from '#imports';
import { CustomRefreshHandler } from '~/config/AuthRefreshHandler';

export default defineNuxtPlugin(async (nuxtApp) => {
  // 1. Initialize authentication state, potentially fetch current session
  const { data, lastRefreshedAt, token, refreshToken, hydrateFromSecureStorage } = useAuthState();

  // Hydrate native tokens from SecureStorage before any auth logic
  await hydrateFromSecureStorage();

  const { getSession, refresh } = useAuth();

  // Prioritize `routeRules` setting over `runtimeConfig` settings, fallback to false
  // loading.value = true;

  // Check user status on app start and initialize session if valid token exists
  const shouldFetchSession = typeof data.value === 'undefined';

  if (shouldFetchSession) {
    try {
      if (!token.value && refreshToken.value) {
        await refresh();
      } else if (token.value) {
        await getSession();
      }
    } catch (e) {
      // Do not throw the configuration error as it can lead to infinite recursion
      if (!(e instanceof Error)) {
        throw e;
      }
    }
  }

  // 2. Setup session maintenance, e.g., auto refreshing or refreshing on focus
  const refreshHandler = new CustomRefreshHandler({
    enableProactiveRefresh: true,
    enableOnWindowFocus: true,
    proactiveLeadTimeMs: 60_000,
  });

  nuxtApp.hook('app:mounted', () => {
    refreshHandler.init();
  });

  const _unmount = nuxtApp.vueApp.unmount;
  nuxtApp.vueApp.unmount = function () {
    refreshHandler.destroy();

    // Clear session
    lastRefreshedAt.value = undefined;
    data.value = undefined;

    // Call original unmount
    _unmount();
  };
});
