import * as Sentry from '@sentry/capacitor';
import { Dialog } from '@capacitor/dialog';
import { Preferences } from '@capacitor/preferences';
import type { CheckWorkShiftStatusV2Response } from '~/client';
import { useMobileConfig } from '~/composables/mobile/config/useMobileConfig';
import { useWorkShiftProject } from '~/composables/mobile/projects/useWorkShiftProject';
import { useWorkShiftTimer } from '~/composables/mobile/shift/useMobileShiftTimer';
import { useDeviceInfoStore } from '~/stores/mobile/deviceInfo';
import { useUploader } from '~/composables/mobile/useUploader';
import { findSelectorProjectByIdViaList } from '~/mutations/mobile/findSelectorProjectByIdViaList';
import { generateWorkShiftId } from '~/mutations/mobile/generateWorkShiftId';
import { getWorkShiftStatus } from '~/mutations/mobile/getWorkShiftStatus';
import { uploadShiftEnd } from '~/mutations/mobile/uploadShiftEnd';
import { MESSAGE_TYPES } from '~/types/mobile/trackingSensors';
import { getDeviceStatePayload } from '~/utils/mobile/deviceInfoUtils';
import { addPayload } from '~/utils/useDb';
import { setIsPaused } from '~/composables/mobile/useMobileRuntimeState';

export class WorkShiftRunningError extends Error {
  workShiftId: string;

  constructor(message: string, workShiftId: string) {
    super(message);
    this.name = 'WorkShiftRunningError';
    this.workShiftId = workShiftId;
  }
}

export class ProjectRecoveryFailedError extends Error {
  projectId: string;

  constructor(projectId: string) {
    super(`Failed to recover project ${projectId} from server during work shift restore.`);
    this.name = 'ProjectRecoveryFailedError';
    this.projectId = projectId;
  }
}

const CURRENT_WORK_SHIFT_KEY = 'current_work_shift_id';
const SHIFT_PAUSED_KEY = 'work_shift_paused';
// Set "unclean-assumed" (cleared) when a shift starts; set true on a graceful stop/pause.
// Read on next launch to tell a graceful exit apart from the OS killing the app mid-shift.
const CLEAN_SHUTDOWN_KEY = 'session_clean_shutdown';

export async function getCurrentWorkShiftId(): Promise<string | null> {
  const preference = await Preferences.get({ key: CURRENT_WORK_SHIFT_KEY });
  console.debug('Getting work shift id from preferences storage. ID:', preference.value);
  return preference.value;
}

async function setCurrentWorkShiftId(value: string): Promise<void> {
  console.debug('Setting work shift id to preferences storage. ID:', value);
  await Preferences.set({ key: CURRENT_WORK_SHIFT_KEY, value });
}

async function removeCurrentWorkShiftId(): Promise<void> {
  console.debug('Removing work shift id from preferences storage');
  await Preferences.remove({ key: CURRENT_WORK_SHIFT_KEY });
}

export async function getShiftPaused(): Promise<boolean> {
  const pref = await Preferences.get({ key: SHIFT_PAUSED_KEY });
  return pref.value === 'true';
}

export async function saveShiftPaused(value: boolean): Promise<void> {
  if (value) {
    await Preferences.set({ key: SHIFT_PAUSED_KEY, value: 'true' });
  } else {
    await Preferences.remove({ key: SHIFT_PAUSED_KEY });
  }
}

export async function getCleanShutdown(): Promise<boolean> {
  const pref = await Preferences.get({ key: CLEAN_SHUTDOWN_KEY });
  return pref.value === 'true';
}

export async function setCleanShutdown(value: boolean): Promise<void> {
  if (value) {
    await Preferences.set({ key: CLEAN_SHUTDOWN_KEY, value: 'true' });
  } else {
    await Preferences.remove({ key: CLEAN_SHUTDOWN_KEY });
  }
}

type WorkShiftStatusForCurrentDevice = {
  activeOnAnotherDevice: boolean | undefined;
  shiftExists: boolean | undefined;
  workShiftId: string | null | undefined;
};

export async function transformToStatusForCurrentDevice(
  statusResponse: CheckWorkShiftStatusV2Response
): Promise<WorkShiftStatusForCurrentDevice> {
  const deviceInfoStore = useDeviceInfoStore();

  const status = statusResponse;
  if (status == null) {
    return { activeOnAnotherDevice: undefined, shiftExists: undefined, workShiftId: undefined };
  } else {
    const deviceId = deviceInfoStore.info.id;

    const activeOnAnotherDevice = status?.device_id != null && status.device_id !== deviceId;
    const shiftExists = status?.device_id === deviceId && !!status?.work_shift_id;
    const workShiftId = status?.work_shift_id;

    return { activeOnAnotherDevice, shiftExists, workShiftId };
  }
}

async function promptAndInterruptWorkShiftOnAnotherDevice(workShiftId: string): Promise<boolean> {
  const { value } = await Dialog.confirm({
    title: 'Shift is running...',
    message:
      'The work shift is running on another device. To start a new shift you need to end the previous one. Do you want to proceed? All unsaved data will be lost.',
    okButtonTitle: 'Start Shift',
    cancelButtonTitle: 'Cancel',
  });
  const confirmed = Boolean(value);
  if (confirmed) {
    const payload = { work_shift_id: workShiftId, end_time: new Date().toISOString(), data_complete: null };
    await uploadShiftEnd([payload]);
    return true;
  } else return false;
}

export function useShiftSession() {
  const { fetchAndSync } = useMobileConfig();
  const uploader = useUploader();
  const timer = useWorkShiftTimer();
  const deviceInfoStore = useDeviceInfoStore();

  async function registerWorkShift(projectId: string): Promise<string> {
    const startTime = new Date();
    const statePayload = await getDeviceStatePayload();

    const res = await generateWorkShiftId({
      device_id: deviceInfoStore.info.id,
      project_id: projectId,
      start_time: startTime.toISOString(),
      state_payload: statePayload,
      time_zone: deviceInfoStore.info.timezone,
    });

    await timer.init(new Date(res.start_time));
    return res.work_shift_id;
  }

  async function requestNewWorkShiftSession(projectId: string): Promise<string | null> {
    const currentWorkShiftId = await getCurrentWorkShiftId();
    if (currentWorkShiftId)
      throw new WorkShiftRunningError(
        'Work shift session is running locally. Stop the previous session before starting a new one.',
        currentWorkShiftId
      );

    const status = await getWorkShiftStatus();
    if (status) {
      const { activeOnAnotherDevice, shiftExists, workShiftId } = await transformToStatusForCurrentDevice(status);
      if (!activeOnAnotherDevice && shiftExists && workShiftId) {
        await setCurrentWorkShiftId(workShiftId);
        throw new WorkShiftRunningError('An unfinished work shift is already registered on this device.', workShiftId);
      } else if (activeOnAnotherDevice && workShiftId) {
        try {
          const interrupted = await promptAndInterruptWorkShiftOnAnotherDevice(workShiftId);
          if (interrupted) {
            const newWorkShiftId = await registerWorkShift(projectId);
            await setCurrentWorkShiftId(newWorkShiftId);
            return newWorkShiftId;
          } else return null;
        } catch (error: unknown) {
          throw Error(`Failed to interrupt and create a new work shift`);
        }
      } else if (workShiftId === null) {
        const newWorkShiftId = await registerWorkShift(projectId);
        await setCurrentWorkShiftId(newWorkShiftId);
        return newWorkShiftId;
      } else return null;
    } else {
      throw Error('Failed to call work shift status from the server');
    }
  }

  /**
   * Restore an in-progress work shift session from server state.
   *
   * @remarks
   * Side effect: if the server's `project_id` differs from the locally cached
   * project, fetches the project and overwrites local storage so downstream
   * permission/audio/event code can rely on `useWorkShiftProject().project`.
   */
  async function restoreWorkShiftSession(
    options: { syncData?: boolean; skipServerStatusCheck?: boolean } = {}
  ): Promise<string | null> {
    const { syncData = true, skipServerStatusCheck = false } = options;
    if (syncData) {
      try {
        await syncAndUploadWorkShiftData();
      } catch (error: unknown) {
        if (isNetworkConnectivityError(error)) {
          console.info(`[MobileShift] Offline during work shift restoration attempt — sync skipped.`);
        } else {
          console.error(`[MobileShift] Failed to sync and upload work shift data on restore:`, error);
          Sentry.captureException(error);
        }
      }
    }

    const wasPaused = await getShiftPaused();
    setIsPaused(wasPaused);

    if (!skipServerStatusCheck) {
      try {
        const status = await getWorkShiftStatus();
        if (status) {
          const { activeOnAnotherDevice, shiftExists, workShiftId } = await transformToStatusForCurrentDevice(status);
          if (!activeOnAnotherDevice && shiftExists && workShiftId) {
            await setCurrentWorkShiftId(workShiftId);
            await recoverWorkShiftProjectIfNeeded(status.project_id);
            return workShiftId;
          } else {
            await removeCurrentWorkShiftId();
            return null;
          }
        }
      } catch (error: unknown) {
        if (error instanceof ProjectRecoveryFailedError) throw error;
        console.error('[MobileShift] Failed to call work shift status on work shift restore:', error);
      }
    }

    const currentWorkShiftId = await getCurrentWorkShiftId();
    return currentWorkShiftId;
  }

  async function recoverWorkShiftProjectIfNeeded(serverProjectId: string | null | undefined): Promise<void> {
    if (!serverProjectId) return;
    const { userId } = useUserRole();
    if (!userId.value) return;
    const workShiftProject = useWorkShiftProject();
    await workShiftProject.load();
    if (workShiftProject.project.value?.id === serverProjectId) return;

    const fetched = await findSelectorProjectByIdViaList(serverProjectId, userId.value);
    if (fetched && fetched.id === serverProjectId) {
      await workShiftProject.save(fetched);
      console.info('[MobileShift] Recovered project data from server during work shift restore.');
    } else {
      await workShiftProject.save(null);
      console.warn(`[MobileShift] Failed to recover project ${serverProjectId} from server during work shift restore.`);
      throw new ProjectRecoveryFailedError(serverProjectId);
    }
  }

  async function discardLocalWorkShift(): Promise<void> {
    await removeCurrentWorkShiftId();
  }

  async function pauseWorkShiftSession() {
    const workShiftId = await getCurrentWorkShiftId();
    await saveShiftPaused(true);
    setIsPaused(true);
    await timer.startBreak();
    const buttonPressedTime = new Date().toISOString();
    if (workShiftId) {
      const pausePayload = { type: 'pause', work_shift_id: workShiftId, button_pressed_time: buttonPressedTime };
      await addPayload(MESSAGE_TYPES.shift_break_event, pausePayload);
      syncAndUploadWorkShiftData().catch(() => {});
    }
  }

  async function resumeWorkShiftSession(): Promise<boolean> {
    const wasPaused = await getShiftPaused();
    if (wasPaused) {
      const workShiftId = await getCurrentWorkShiftId();
      await saveShiftPaused(false);
      setIsPaused(false);
      await timer.endBreak();
      const buttonPressedTime = new Date().toISOString();
      if (workShiftId) {
        const resumePayload = { type: 'resume', work_shift_id: workShiftId, button_pressed_time: buttonPressedTime };
        await addPayload(MESSAGE_TYPES.shift_break_event, resumePayload);
        syncAndUploadWorkShiftData().catch(() => {});
      }
    }
    return wasPaused;
  }

  async function finishWorkShiftSession() {
    const wasPaused = await getShiftPaused();
    if (wasPaused) {
      await timer.endBreak();
      await saveShiftPaused(false);
      setIsPaused(false);
    }

    const statePayload = await getDeviceStatePayload();
    const shiftId = await getCurrentWorkShiftId();
    await addPayload(MESSAGE_TYPES.shift_end, {
      work_shift_id: shiftId,
      end_time: new Date().toISOString(),
      state_payload: statePayload,
    });

    try {
      await uploader.tick({ showProgress: true, limitIterations: false });
    } catch (err) {
      console.error('[WorkShift] Upload failed during finish, will retry on the next sync. Error:', err);
    }
    await timer.destroy();
    await removeCurrentWorkShiftId();
    console.info('[WorkShift] Session has been finished successfully.');
  }

  async function cancelWorkShiftSession() {
    const shiftId = await getCurrentWorkShiftId();
    if (!shiftId) return;

    try {
      const statePayload = await getDeviceStatePayload();
      await addPayload(MESSAGE_TYPES.shift_end, {
        work_shift_id: shiftId,
        end_time: new Date().toISOString(),
        state_payload: statePayload,
      });
      await uploader.tick();
    } catch (err) {
      console.error('[WorkShift] Failed to upload cancellation, will retry on the next sync. Error:', err);
    }

    await timer.destroy();
    await removeCurrentWorkShiftId();
    console.info('[WorkShift] Session cancelled and cleaned up successfully.');
  }

  async function syncAndUploadWorkShiftData() {
    console.info('[WorkShift] Syncing and uploading data.');
    await fetchAndSync();
    await uploader.tick();
  }

  async function syncAndUploadDataWithProgress() {
    console.info('[WorkShift] Syncing and uploading data with progress.');
    await fetchAndSync();
    await uploader.tick({ showProgress: true, limitIterations: false });
  }

  return {
    cancelWorkShiftSession,
    pauseWorkShiftSession,
    resumeWorkShiftSession,
    finishWorkShiftSession,
    requestNewWorkShiftSession,
    restoreWorkShiftSession,
    syncAndUploadWorkShiftData,
    syncAndUploadDataWithProgress,
    discardLocalWorkShift,

    timer,
  };
}
