import { FirebaseMessaging } from '@capacitor-firebase/messaging';
import { useDeviceInfoStore } from '~/stores/mobile/deviceInfo';
import { useMobilePermissions } from '~/composables/mobile/useMobilePermissions';
import { uploadDeviceInfo } from '~/mutations/mobile/uploadDeviceInfo';
import { getPushDisabledByUser } from '~/utils/mobile/pushNotificationPrefs';

export async function sendUpdateDeviceInfo() {
  const { granted } = useMobilePermissions();
  const deviceInfoStore = useDeviceInfoStore();

  const deviceId = await deviceInfoStore.ensureDeviceId();

  if (!deviceId) {
    console.warn('[DeviceInfo] Device id unavailable after init. Skipping device info upload.');
    return;
  }

  const info = deviceInfoStore.info;

  // Push state: OS permission (granted) vs the in-app switch (user opt-out).
  let pushPermissionGranted = false;
  try {
    const { receive } = await FirebaseMessaging.checkPermissions();
    pushPermissionGranted = receive === 'granted';
  } catch (e) {
    console.warn('[DeviceInfo] Failed to read push permission state:', e);
  }
  const pushNotificationsEnabled = !(await getPushDisabledByUser());

  const payload = {
    model: info.model,
    device_id: deviceId,
    name: info.name,
    is_complete_sensors: info.is_complete_sensors,
    is_root: info.is_root,
    os_version: info.os_version,
    permission_gps: granted.value.location,
    permission_ble: granted.value.ble,
    permission_wifi: granted.value.wifi,
    permission_motion: granted.value.motion,
    push_permission_granted: pushPermissionGranted,
    push_notifications_enabled: pushNotificationsEnabled,
    platform: info.platform,
    software_version: info.software_version,
    timezone: info.timezone,
  };

  await uploadDeviceInfo(payload);
}
