// @ts-nocheck
import { FirebaseRemoteConfig, GetValueSource } from '@capacitor-firebase/remote-config';
import type { AppConfig } from '~/types/database/config';
import { AppConfigKeys, DefaultAppConfig } from '~/types/database/config';
import { FirebaseAnalytics } from '@capacitor-community/firebase-analytics';

export const useMobileRemoteConfig = () => {
  FirebaseRemoteConfig.setSettings({
    fetchTimeoutInSeconds: 10,
    minimumFetchIntervalInSeconds: 10 * 60, // no cache, always fetch, must increase it later
  }).catch((e) => console.warn('[RemoteConfig] Failed to configure Firebase Remote Config:', e));

  async function loadRemoteConfig(): Promise<AppConfig | null> {
    try {
      const environment = useRuntimeConfig().public.environment;
      FirebaseAnalytics.setUserProperty({
        name: 'environment',
        value: environment,
      });

      await FirebaseRemoteConfig.fetchAndActivate();

      const cfg: AppConfig = { ...DefaultAppConfig };

      for (const key of AppConfigKeys) {
        try {
          const defaultVal = DefaultAppConfig[key];

          if (typeof defaultVal === 'boolean') {
            const { value, source } = await FirebaseRemoteConfig.getBoolean({ key });
            if (source === GetValueSource.Remote) {
              if (typeof value === 'boolean') {
                cfg[key] = value;
              } else {
                console.warn(
                  `[RemoteConfig] remote key "${key}" expected boolean but got "${typeof value}", keeping default`
                );
              }
            }
          } else if (typeof defaultVal === 'number') {
            const { value, source } = await FirebaseRemoteConfig.getNumber({ key });
            if (source === GetValueSource.Remote) {
              if (typeof value === 'number' && !Number.isNaN(value)) {
                cfg[key] = value;
              } else {
                console.warn(
                  `[RemoteConfig] remote key "${key}" expected number but got ` +
                    `"${Number.isNaN(value) ? 'NaN' : typeof value}", keeping default`
                );
              }
            }
          } else {
            console.warn(
              `[RemoteConfig] key "${key}" has unsupported default type "${typeof defaultVal}", keeping default`
            );
          }
        } catch (e) {
          console.warn(`[RemoteConfig] failed to fetch "${key}", keeping default`, e);
        }
      }

      return cfg;
    } catch (e) {
      console.error('[RemoteConfig] Remote config fetch failed. Will be using config from DB. Error:', e);
      return null;
    }
  }

  return { loadRemoteConfig };
};
