import { App as CapApp } from '@capacitor/app';
import { Capacitor } from '@capacitor/core';
import { routePathFromUrl } from '../utils/routePathFromUrl';

export default defineNuxtPlugin((nuxtApp) => {
  if (!Capacitor.isNativePlatform()) return;

  const router = useRouter();

  const handleDeepLink = async (url: string) => {
    const path = routePathFromUrl(url);
    if (!path || path === '/') return;

    await router.isReady();

    if (router.currentRoute.value.fullPath === path) return;

    try {
      await router.push(path);
    } catch (err) {
      console.error(`[Deeplinks] Failed to open deep link: ${url}.`, err);
    }
  };

  CapApp.addListener('appUrlOpen', ({ url }) => {
    handleDeepLink(url);
  });

  nuxtApp.hook('app:mounted', () => {
    CapApp.getLaunchUrl().then((res) => {
      if (res?.url) {
        handleDeepLink(res.url);
      }
    });
  });
});
