<template>
  <LargeAlert
    variant="destructive"
    :title="title"
    :md-description="processedMessage"
    :icon="errorCode(statusCode).icon"
    icon-class="stroke-destructive"
    :card="variants[variant].card"
    :class="cn('mx-auto p-0 px-0 sm:px-8 flex items-center justify-center', variants[variant].class)"
  >
    <slot />
    <p v-if="Boolean(suggestion)" class="text-center">{{ suggestion }}</p>
    <NuxtLink v-if="to" :to="to">
      <Button>{{ actionText }}</Button>
    </NuxtLink>
    <Button v-else-if="errorCode(statusCode).action && actionText" @click="errorCode(statusCode).action">{{
      actionText
    }}</Button>
  </LargeAlert>
</template>

<script setup lang="ts">
import { cn } from '@/lib/utils';
import { AlertOctagonIcon, ShieldAlertIcon, CircleXIcon, WifiOffIcon, TimerOffIcon } from 'lucide-vue-next';
import { FetchError } from 'ofetch';
import type { TypedNuxtLink } from '#build/typed-router/typed-router';
import { servingOffline } from '~/utils/offlineCache';
import { getErrorMessage } from '~/utils/getErrorMessage';

interface Props {
  title?: string;
  message?: string;
  error?: FetchError<any> | null;
  suggestion?: string | null;
  action?: () => void;
  actionText?: string | null;
  variant?: 'table' | 'page';
  to?: TypedNuxtLink['to'];
}

const props = withDefaults(defineProps<Props>(), {
  title: 'Global error',
  message: 'An error occurred while loading data.',
  error: null,
  suggestion: null,
  action: () => window.location.reload(),
  actionText: 'Reload',
  variant: 'page',
  to: undefined,
});

const isOffline = computed(() => servingOffline.value);

const isTimeout = computed(
  () => !!(props.error?.name === 'TimeoutError' || (props.error?.cause as any)?.name === 'TimeoutError')
);

const processedMessage = computed(() => {
  if (isOffline.value) return 'You are currently offline. Please try again when you are back online.';
  if (!props.message && !props.error) return null;
  if (props.error) return getErrorMessage(props.error);
  return props.message;
});

const statusCode = computed(() => {
  if (isOffline.value) return undefined;
  if (props.error) return props.error?.statusCode;
  return undefined;
});

const variants = {
  table: {
    card: false,
    class: 'min-h-48 py-4',
  },
  page: {
    card: true,
    class: 'min-h-80',
  },
};

function errorCode(code: number | undefined) {
  if (isOffline.value) {
    return { action: undefined, icon: WifiOffIcon };
  }
  if (isTimeout.value) {
    return { action: props.action, icon: TimerOffIcon };
  }
  switch (code) {
    case 404:
      return { action: undefined, icon: CircleXIcon };
    case 403:
      return { action: undefined, icon: ShieldAlertIcon };
    default:
      return { action: props.action, icon: AlertOctagonIcon };
  }
}
</script>

<style scoped lang="scss"></style>
