export const DefaultAppConfig = {
  LocationDistanceFilter: 0,
  LocationBufferSize: 60, // GPS readings buffered before forced flush
  LocationFlushIntervalMs: 30_000, // Wall-clock flush cadence (safety net)
  LocationAndroidPriority: 0, // Android FusedLocation priority (0=high accuracy, 1=balanced power, 2=low power, 3=no power)
  LocationDesiredAccuracy: 2, // iOS CLLocationAccuracy level (-1=auto, 0=bestForNavigation, 1=best, 2=nearestTenMeters, 3=hundredMeters, 4=kilometer, 5=threeKilometers)
  LocationPausesAutomatically: true, // iOS: let CLLocationManager auto-pause updates to save battery when stationary
  LocationActivityType: 3, // iOS CLActivityType (1=other, 2=automotiveNavigation, 3=fitness, 4=otherNavigation, 5=airborne)

  BleScanDurationMs: 10_000,
  BleScanIntervalMs: 30_000,
  BleScanAllowDuplicates: true, // Whether to allow duplicate BLE scan results

  WifiScanIntervalMs: 30_000,

  PhysicalSensorBufferSize: 200, // Items to store in memory before flushing to DB
  PhysicalClassifierBufferSize: 5,
  MotionActivityIntervalMs: 10_000, // Requested cadence for OS motion-activity inference (Android only; iOS is OS-managed)
  PhysicalSensorWindowMs: 1_000, // IMU per-window aggregation cadence on devices without classifier

  UploaderBatchSize: 100, // Number of items to upload in a single batch
  UploaderPeriodMs: 60_000, // Interval to wake the uploader

  VadEnabled: true, // Enable Voice Activity Detection

  VadMaxBufferSize: 120, // Max seconds of VAD audio to keep in memory
  VadMaxSegmentSeconds: 3, // Max seconds of a single VAD segment
  VadModelThreshold: 0.8, // VAD sensitivity threshold

  VadGateWakeWord: true, // Only run the (battery-heavy) wake-word pipeline while VAD detects voice
  VadWakeWordHangoverMs: 800, // Keep wake-word running this long after voice drops (tail/intra-word dips)

  GeofenceFetchRadiusKm: 50, // Radius to fetch geofence zones around current location
  GeofenceRefreshDistanceKm: 10, // Refresh geofence zones when user moves this far from last fetch center
  GeofenceWarningDistanceKm: 1, // Warn when within this distance of restricted zone
  GeofenceRestrictionQueueSize: 4, // Number of consecutive allowed location updates required before recording audio

  AudioCacheTTLDays: 4,
  AudioUploadBatchSize: 64,
} as const;

export type AppConfigKey = keyof typeof DefaultAppConfig;

export type AppConfig = typeof DefaultAppConfig;

export const AppConfigKeys = Object.keys(DefaultAppConfig) as AppConfigKey[];
