<template>
  <NuxtLayout>
    <VitePwaManifest />
    <NuxtPage />
  </NuxtLayout>
  <Toaster />
</template>

<script setup lang="ts">
import { client } from '~/client/client.gen';
import type { HTTPMethod } from 'h3';
import { isRegistered, requestAndRegisterPushNotifications } from './plugins/notifications';
import { sendUpdateDeviceInfo } from './utils/mobile/updateDeviceInfo';
import { createCachingFetch, servingOffline } from '~/utils/offlineCache';
import { authOnResponse, authPreRequest, type FetchCtx } from '~/composables/auth/httpInterceptors';

useSeoMeta({
  ogTitle: 'Patriot Grassroots App',
  ogDescription: 'Patriot Grassroots App is a system for gathering and verifying signatures',
  ogImage: 'logo.png',
  twitterCard: 'summary_large_image',
  twitterTitle: 'Patriot Grassroots App',
  twitterDescription: 'Patriot Grassroots App is a system for gathering and verifying signatures',
  twitterImage: 'logo.png',
});

useHead({
  titleTemplate: (titleChunk) => {
    return titleChunk ? `${titleChunk} | Patriot Grassroots App` : 'Patriot Grassroots App';
  },
});

const { token, refresh, signOut, pendingRefresh } = useAuth();
const route = useRoute();

useSentryContext();

const mobile = await useMobile();

client.setConfig({
  $fetch: createCachingFetch($fetch as any) as any,
  auth: async () =>
    authPreRequest({
      pendingRefresh,
      refresh,
      token,
    }),
  baseURL: useRuntimeConfig().public.apiBaseURL,
  onResponse: async (ctx) =>
    authOnResponse(ctx as FetchCtx, {
      refresh,
      // Preserve where the user was so login redirects them back, matching
      // the supabase and mobile-native 401 paths.
      signOut: () => signOut({ redirect: true, callbackUrl: buildLoginCallbackUrl(route.fullPath) }),
      token,
      retryRequest: async (c, authorization) => {
        const { method, body, query, params } = c.options;
        return await $fetch.raw(c.request as RequestInfo, {
          method: method as HTTPMethod,
          body: body as BodyInit | Record<string, unknown>,
          query,
          params,
          headers: { Authorization: authorization },
        });
      },
      cancelQueries: () => useQueryCache().cancelQueries(),
      showToastError,
      isOffline: () => servingOffline.value,
    }),
  onResponseError({ response, error }) {
    console.log('Error in response:', { response, error });
  },
});

if (mobile) {
  const { isAuthenticated } = useUserRole();

  useTimeoutPoll(
    async () => {
      if (servingOffline.value) return;
      if (!isAuthenticated.value) return;

      await mobile.checkAndStopIfClosed().catch((error) => {
        console.error('Error while looking for active work shifts for device', error);
      });

      await sendUpdateDeviceInfo().catch((error) => {
        console.error(`Failed to upload device info. (${error})`);
      });

      if (!isRegistered.value) {
        try {
          await requestAndRegisterPushNotifications();
        } catch (err: any) {
          console.error('Failed to register push notification token');
        }
      }
    },
    5 * 60 * 1000
  ); // 5 minutes
}
</script>

<style>
html,
body {
  overscroll-behavior: none;
}
</style>
