import { createClient } from '@supabase/supabase-js';
import type { SupabaseClient, RealtimeChannel } from '@supabase/supabase-js';
import type { Database } from '~/types/schema';
import * as Sentry from '@sentry/nuxt';
import {
  cacheStore,
  cacheGet,
  clearOfflineFlag,
  setOfflineFlag,
  isNetworkConnectivityError,
  hashBody,
  servingOffline,
} from '~/utils/offlineCache';

type SubscribeFn = (supabase: SupabaseClient<Database>) => RealtimeChannel | RealtimeChannel[] | void;

async function checkAccessToken() {
  const { refresh, refreshToken } = useAuth();

  // Refresh token cookie gone — session is truly expired
  if (!refreshToken.value) {
    await handleSessionExpired();
    return;
  }

  try {
    await refresh();
  } catch (err: any) {
    const statusCode = err?.statusCode ?? err?.status;

    if (statusCode === 401) {
      await handleSessionExpired();
    } else {
      // Error (network, 500) — don't sign out, let the caller handle the failed request
      console.error('[Supabase] Token refresh failed:', err);
      throw err;
    }
  }
}

async function handleSessionExpired() {
  if (servingOffline.value) return;

  const { signOut } = useAuth();
  const route = useRoute();

  showToastError('Session expired. Please log in again.');
  useQueryCache().cancelQueries();

  await signOut({ redirect: true, callbackUrl: buildLoginCallbackUrl(route.fullPath) });
}

export default defineNuxtPlugin(async () => {
  const { status } = useAuth();
  const { rawToken } = useAuthState();

  const config = useRuntimeConfig().public;
  const subscribeFns = new Set<SubscribeFn>();
  const activeChannels = new Map<SubscribeFn, RealtimeChannel[]>();

  let supabase: SupabaseClient<Database> | undefined = undefined;

  if (config.supabase.url && config.supabase.key) {
    try {
      supabase = createClient<Database>(config.supabase.url, config.supabase.key, {
        auth: {
          persistSession: false,
          autoRefreshToken: false,
          detectSessionInUrl: false,
        },
        global: {
          fetch: async (input, init = {}) => {
            const headers = new Headers(init.headers || {});
            const tokenValue = useAuth().token.value;

            if (tokenValue) {
              headers.set('Authorization', tokenValue);
            }

            const doFetch = (hdrs: Headers) => {
              const timeout = 5000;
              // AbortSignal is ignored by CapacitorHttp's patched fetch on mobile,
              // so we race against a manual timeout to avoid hanging for 48s+ on network loss.
              const fetchPromise = fetch(input, { ...init, headers: hdrs, signal: AbortSignal.timeout(timeout) });
              const timeoutPromise = new Promise<never>((_, reject) => {
                setTimeout(
                  () => reject(new DOMException('The operation was aborted due to timeout', 'TimeoutError')),
                  timeout
                );
              });
              return Promise.race([fetchPromise, timeoutPromise]);
            };

            const url = typeof input === 'string' ? input : input instanceof Request ? input.url : String(input);

            const method = (init.method ?? 'GET').toUpperCase();
            const isRestGet = method === 'GET' && url.includes('/rest/v1/');
            const isRpc = url.includes('/rest/v1/rpc/');
            const cacheKey = isRestGet || isRpc ? `supabase:${method}:${url}:${hashBody(init.body)}` : '';

            try {
              let res = await doFetch(headers);

              if (res.status === 401) {
                try {
                  await checkAccessToken();

                  const retryHeaders = new Headers(init.headers || {});
                  const newToken = useAuth().token.value;
                  if (newToken) {
                    retryHeaders.set('Authorization', newToken);
                  }

                  res = await doFetch(retryHeaders);
                } catch (e) {
                  console.error('[Supabase] Failed to refresh access token and retry request', e);
                }
              }

              if (cacheKey && res.ok) {
                const clone = res.clone();
                clone
                  .json()
                  .then(async (json) => {
                    const storePromise = cacheStore(cacheKey, json);
                    if (servingOffline.value) {
                      pingGoogle().then((reachable) => {
                        if (reachable) clearOfflineFlag();
                      });
                    }
                    return storePromise;
                  })
                  .catch(() => {});
              }

              return res;
            } catch (err: any) {
              if (isNetworkConnectivityError(err)) {
                await setOfflineFlag();

                if (cacheKey) {
                  const cached = await cacheGet(cacheKey);
                  if (cached !== undefined) {
                    return new Response(JSON.stringify(cached), {
                      status: 200,
                      headers: {
                        'Content-Type': 'application/json',
                        'X-Offline-Cache': 'true',
                      },
                    });
                  }
                }
              }

              throw err;
            }
          },
        },
        db: {
          schema: 'private',
        },
      });

      if (rawToken.value) await supabase?.realtime?.setAuth(rawToken.value);
    } catch (e) {
      Sentry.captureException(e);
      console.error('[Supabase] Failed to create client', e);
    }
  } else {
    const error = new Error('Supabase URL or Key is missing in environment variables');
    Sentry.captureException(error);
    console.warn('[Supabase] Cannot initialize connection to server');
  }

  function runFn(fn: SubscribeFn) {
    if (!supabase) return [];
    const res = fn(supabase);
    const chans = !res ? [] : Array.isArray(res) ? res : [res];
    activeChannels.set(fn, chans);
    return chans;
  }

  function cleanupFn(fn: SubscribeFn) {
    if (!supabase) return;
    const chans = activeChannels.get(fn) ?? [];
    for (const ch of chans) supabase.removeChannel(ch);
    activeChannels.delete(fn);
  }

  function register(fn: SubscribeFn) {
    subscribeFns.add(fn);
    if (supabase) runFn(fn);

    return () => {
      subscribeFns.delete(fn);
      cleanupFn(fn);
    };
  }

  function closeSocketConnection() {
    if (!supabase) return;
    if (activeChannels.size === 0) supabase.realtime.disconnect();
  }

  async function reconnect(newJwt?: string) {
    if (!supabase) return;

    if (newJwt) await supabase.realtime.setAuth(newJwt);

    for (const fn of subscribeFns) cleanupFn(fn);

    for (const fn of subscribeFns) runFn(fn);
  }

  watch(
    () => [rawToken.value, status.value],
    async ([token, status], [prevToken]) => {
      if (token) await supabase?.realtime?.setAuth(token);
      if (token && status === 'authenticated' && supabase && prevToken !== token) {
        reconnect(token);
      }
    }
  );

  return {
    provide: {
      supabase,
      realtimeManager: {
        register,
        reconnect,
        refresh: checkAccessToken,
        closeSocketConnection,
      },
    },
  };
});
