export interface PauseDeps {
  isTracking: () => boolean;
  stopModules: () => Promise<{ stopped: string[]; failed: string[] }>;
  restartModules: () => Promise<void>;
  recordPause: () => Promise<void>;
  rollbackPause: () => Promise<void>;
  markCleanShutdown: () => Promise<void>;
  setTracking: (v: boolean) => void;
  onBreakStarted: () => Promise<void>;
  notifyFailure: (message: string) => void;
  reportEvent: (payload: Record<string, unknown>) => Promise<void>;
}

export interface ReconcileDeps {
  isPaused: () => boolean;
  isTracking: () => boolean;
  aliveModules: () => string[];
  nativeWatcherCount: () => Promise<number>; // errors → 0 handled by caller wiring
  stopModules: () => Promise<{ stopped: string[]; failed: string[] }>;
  removeAllNativeWatchers: () => Promise<void>;
  reportEvent: (payload: Record<string, unknown>) => Promise<void>;
  notifyStillTracking: (message: string) => void;
}

export const PAUSE_FAILED_MESSAGE = "Couldn't start break — tracking is still active. Try again.";

export async function executeReconcile(deps: ReconcileDeps): Promise<void> {
  // Tracking is on — there is no legitimate state where tracking is active AND the watchdog
  // should tear modules down (that includes isTracking && isPaused, which should never occur,
  // but if it somehow did, ripping modules out from under active tracking would be worse than
  // leaving it alone). Only reconcile while nothing is supposed to be running.
  if (deps.isTracking()) return;
  const alive = deps.aliveModules();
  const nativeCount = await deps.nativeWatcherCount();
  if (alive.length === 0 && nativeCount === 0) return;

  await deps.reportEvent({ aliveModules: alive, nativeWatcherCount: nativeCount }).catch(() => {});
  const { failed } = await deps.stopModules();
  if (nativeCount > 0) {
    await deps.removeAllNativeWatchers().catch(() => {});
  }
  if (failed.length > 0) {
    deps.notifyStillTracking(PAUSE_FAILED_MESSAGE);
  }
}

export async function executePause(deps: PauseDeps): Promise<boolean> {
  if (!deps.isTracking()) return false;
  const { failed } = await deps.stopModules();
  if (failed.length > 0) {
    await deps.restartModules().catch(() => {});
    deps.notifyFailure(PAUSE_FAILED_MESSAGE);
    await deps.reportEvent({ stage: 'module_stop', failed }).catch(() => {});
    return false;
  }
  try {
    await deps.recordPause();
    await deps.markCleanShutdown();
    deps.setTracking(false);
    await deps.onBreakStarted().catch(() => {});
    return true;
  } catch (err) {
    // recordPause() may have partially persisted the pause (e.g. saved the paused flag before
    // throwing on a later step) before modules are restarted below — undo that first, otherwise
    // the shift is left believing it's paused while tracking modules are actually running again.
    await deps.rollbackPause().catch(() => {});
    await deps.restartModules().catch(() => {});
    deps.notifyFailure(PAUSE_FAILED_MESSAGE);
    Sentry.captureException(err);
    await deps.reportEvent({ stage: 'record_pause', error: String(err) }).catch(() => {});
    return false;
  }
}

export function createTrackingController() {
  const { isCanvasserOrSubCanvasser, userId } = useUserRole();
  const { isTracking, isPaused, startStatus, modules: modulesRef } = useMobileRuntimeState();
  const mutex = createMutex();
  const { fetchAndSync } = useMobileConfig();
  const workShift = useShiftSession();
  const permsStore = useMobilePermissions();
  const { project: workShiftProject, load: loadWorkShiftProject, save: saveWorkShiftProject } = useWorkShiftProject();
  const moduleManager = createModuleManager();
  const breakNotification = useBreakNotification();
  // Registered here (rather than at module scope) so importing this module for unit tests
  // never touches the real @capacitor/core registerPlugin — see useMobileLocationTracking.ts
  // for the same plugin registered again there, which is the established pattern in this codebase.
  const BackgroundGeolocation = registerPlugin<BackgroundGeolocationPlugin>('BackgroundGeolocation');

  async function initialize(): Promise<void> {
    const deviceInfoStore = useDeviceInfoStore();
    await deviceInfoStore.init();

    const environment = useRuntimeConfig().public.environment;
    await initDB(userId, environment);

    const { initConfig } = useMobileConfig();
    await initConfig();
    console.debug('[Mobile] Tracking controller initialized', JSON.stringify(deviceInfoStore.info));
  }

  async function startGrantedModules(workShiftId: string, resuming: boolean = false): Promise<void> {
    const requiredPermissions = getRequiredPermissions(permsStore.platform, workShiftProject.value);
    await permsStore.ensureGrantedAllOf(requiredPermissions);
    const modulesToStart = requiredPermissions.filter((m) => permsStore.granted.value[m]);
    await startModules(workShiftId, modulesToStart, resuming);
  }

  async function ensurePermissions(): Promise<ModuleName[]> {
    const requiredPermissions = getRequiredPermissions(permsStore.platform, workShiftProject.value);
    const startPermitted = await permsStore.ensureGrantedAllOf(requiredPermissions);
    if (!startPermitted) {
      startStatus.value = 'cancelled';
      throw new Error('Tracking is not permitted. Necessary permissions are not granted.');
    }
    return requiredPermissions;
  }

  async function startModules(
    workShiftId: string,
    modulesToStart: ModuleName[],
    resuming: boolean = false
  ): Promise<void> {
    // Resume button must never block on network — fire-and-forget the remote config
    // refresh; the in-memory config from app boot remains the source of truth until
    // it succeeds. Start flow still awaits to honour any first-mount config changes.
    if (resuming) {
      fetchAndSync().catch(() => {});
    } else {
      await fetchAndSync();
    }

    const deviceId = useDeviceInfoStore().info.id;
    if (!deviceId) {
      throw new Error('Failed to get device id during work shift start');
    }
    await workShift.timer.ensureInitialised();

    if (!resuming) {
      await sendUpdateDeviceInfo();
    }

    await initBackgroundFetch(async () => {
      await workShift.syncAndUploadWorkShiftData();
      // Fire-and-forget: a stuck background tick must never block BackgroundFetch.finish().
      reconcileTrackerState().catch((err: unknown) => {
        console.error('[Mobile] Background-fetch reconcile failed:', err);
      });
    });
    const succeededModules = await moduleManager.start(workShiftId, deviceId, modulesToStart);

    if (succeededModules.length === 0) {
      startStatus.value = 'failed';
      throw new Error('No tracking modules started successfully. Cannot start work shift.');
    }

    // Mark the session "unclean-assumed" until a graceful stop/pause clears it. If the OS
    // kills the app mid-shift, this flag (read on next launch) reveals the unclean exit.
    await setCleanShutdown(false);

    setIsTracking(true);
    startStatus.value = 'success';

    if (succeededModules.length < modulesToStart.length) {
      startStatus.value = 'failed';
    }

    console.info(
      `[Mobile] Tracking ${resuming ? 'resumed' : 'started'} (${succeededModules.join(', ')}), session ID: ${workShiftId}`
    );
  }

  async function tryRestoreWorkShift(
    options: { syncData?: boolean; skipServerStatusCheck?: boolean } = {}
  ): Promise<string | null> {
    const workShiftId = await workShift.restoreWorkShiftSession(options);
    if (!workShiftId) {
      console.info('[Mobile] No work shift found to restore.');
      return null;
    }
    if (!workShiftProject.value) {
      await workShift.discardLocalWorkShift();
      console.warn('[Mobile] Persisted work shift exists but project data is missing; local shift ID cleared.');
      return null;
    }
    return workShiftId;
  }

  async function start(p?: SelectorProjectItem): Promise<string | undefined> {
    return mutex.run(async () => {
      try {
        if (p) await saveWorkShiftProject(p);
        await loadWorkShiftProject();
        const modulesToStart = await ensurePermissions();
        if (!workShiftProject.value?.id) {
          throw new Error('No project selected');
        }

        await ensureAudioSessionAvailable(workShiftProject.value);

        startStatus.value = 'pending';
        let newWorkShiftId: string | null;

        try {
          newWorkShiftId = await workShift.requestNewWorkShiftSession(workShiftProject.value.id);
        } catch (error: unknown) {
          console.error('Error while requesting new work shift session:', error);
          if (error instanceof WorkShiftRunningError) {
            newWorkShiftId = await workShift.restoreWorkShiftSession();
          } else {
            throw error;
          }
        }

        if (newWorkShiftId == undefined) {
          startStatus.value = 'cancelled';
          throw new Error('Failed to obtain work shift id.');
        }

        await startModules(newWorkShiftId, modulesToStart);
        return newWorkShiftId;
      } catch (err: any) {
        if (err instanceof AudioSessionBusyError) {
          startStatus.value = 'cancelled';
        } else if (startStatus.value !== 'cancelled') {
          startStatus.value = 'panic';
        }
        await moduleManager.stop();
        await destructBackgroundFetch().catch(() => {});
        await workShift.cancelWorkShiftSession().catch(() => {});
        if (err instanceof AudioSessionBusyError) {
          showToastError(audioBusyToastMessage(err.reason));
          console.warn('[Mobile] Start cancelled: audio session busy', err.reason);
        } else if (err instanceof ProjectRecoveryFailedError) {
          showToastError("Couldn't restore your previous shift. Please start a new one.");
          console.warn('[Mobile] Start cancelled: project recovery failed', err);
        } else {
          showToastError('Failed to start tracking due to\n' + err);
          console.error('Failed to start tracking due to\n' + err);
          Sentry.captureException(err);
        }
        return undefined;
      }
    });
  }

  async function pause(): Promise<void> {
    return mutex.run(async () => {
      console.info('[Mobile] Trying to pause mobile shift.');
      try {
        await executePause({
          isTracking: () => isTracking.value,
          stopModules: () => moduleManager.stop(),
          restartModules: async () => {
            const workShiftId = await getCurrentWorkShiftId();
            if (workShiftId) await startGrantedModules(workShiftId, true);
          },
          recordPause: () => workShift.pauseWorkShiftSession(),
          // Undo what pauseWorkShiftSession() may have persisted before throwing. It calls
          // saveShiftPaused(true) + setIsPaused(true) synchronously up front, then awaits
          // timer.startBreak() and addPayload() which can still fail — so on any failure path
          // the paused flag/state may already be set. workShift.resumeWorkShiftSession() is
          // wrong here: it records a *resume* event (server-visible), whereas this pause never
          // successfully started — we just need to erase the local paused bookkeeping.
          rollbackPause: async () => {
            await saveShiftPaused(false);
            setIsPaused(false);
            // pauseWorkShiftSession() calls timer.startBreak() BEFORE addPayload(), which is the
            // step most likely to fail (network/db) — so a break segment can already be open in
            // the timer even though the flags above just got rolled back. Left open, nobody ever
            // calls endBreak() for it: breakElapsedMs grows unboundedly and the shift's displayed
            // net elapsed time freezes at ~0 for the rest of the shift. endBreak() is a safe
            // no-op when no segment is open (see useMobileShiftTimer.ts), so it's correct to call
            // unconditionally here — the failed pause attempt becomes a real (if brief) break in
            // the timer's bookkeeping, which is the accurate semantic remnant of what happened.
            await workShift.timer.endBreak().catch(() => {});
          },
          markCleanShutdown: () => setCleanShutdown(true),
          setTracking: setIsTracking,
          onBreakStarted: () => breakNotification.show(new Date()),
          notifyFailure: showToastError,
          reportEvent: (payload) => sendMobileEvent(MESSAGE_TYPES.pause_stop_failed, payload),
        });
        console.info('[Mobile] Pause flow finished.');
      } catch (err: any) {
        console.error('[Mobile] Error during transition to break:', err);
        Sentry.captureException(err);
      }
    });
  }

  async function resume(): Promise<void> {
    return mutex.run(async () => {
      console.info('[Mobile] Trying to resume mobile shift.');
      try {
        await loadWorkShiftProject();

        // Resume must never block on network — skip both the data-sync tick and the
        // server status lookup. Local state is the source of truth for the button press;
        // server reconciliation happens on the next background fetch / app foregrounding /
        // pause.
        const workShiftId = await tryRestoreWorkShift({ syncData: false, skipServerStatusCheck: true });
        if (!workShiftId) return;

        const modulesToStart = await ensurePermissions();

        await ensureAudioSessionAvailable(workShiftProject.value);

        const wasPaused = isPaused.value;
        try {
          // Bring tracking modules up *before* committing the shift to "resumed" server-side.
          // A transient module failure (e.g. another app holding audio) then aborts the resume
          // with nothing to undo — the shift simply stays paused — instead of leaving a resume
          // event we'd have to compensate for with a pause. The shift ID was already restored
          // above, so modules don't depend on the resume having happened first.
          await startModules(workShiftId, modulesToStart, true);

          if (wasPaused) {
            // Clear the break notification as soon as tracking is back up — BEFORE
            // resumeWorkShiftSession(), not after. That call sets isPaused=false
            // synchronously but can still throw afterwards (Preferences.set / addPayload);
            // clearing only on its success would strand the Android "on break" ongoing
            // notification (and any pending iOS reminders) with the shift left in a
            // neither-tracking-nor-paused state.
            await breakNotification.clear().catch(() => {});
            await workShift.resumeWorkShiftSession();
          }

          console.info('[Mobile] Work shift has been resumed successfully.');
        } catch (mutationOrAudioErr) {
          setIsTracking(false);
          // Modules may have come up before a later step (resume bookkeeping) failed — tear
          // them back down. The audio-busy abort path already stops modules internally, so
          // this is a no-op there.
          await moduleManager.stop().catch(() => {});
          await destructBackgroundFetch().catch(() => {});
          // Safety net for the case where the success-path clear already ran (right after
          // startModules) and workShift.resumeWorkShiftSession() then threw: it flips
          // isPaused=false synchronously before its own awaited calls that can fail, so by
          // the time we're here isPaused.value is already false — redundant with the earlier
          // clear, but harmless (clear() is idempotent). Guarded so it does NOT fire when
          // startModules itself failed: in that case isPaused is still true (the break never
          // ended, resumeWorkShiftSession was never reached), and the banner still legitimately
          // shows "on break" — clearing the notification there would desync it from the banner.
          if (!isPaused.value) {
            await breakNotification.clear().catch(() => {});
          }
          throw mutationOrAudioErr;
        }
      } catch (err: unknown) {
        if (err instanceof AudioSessionBusyError) {
          showToastError(audioBusyToastMessage(err.reason));
          console.warn('[Mobile] Resume cancelled: audio session busy', err.reason);
        } else {
          console.error('[Mobile] Failed to resume tracking:', err);
          Sentry.captureException(err);
        }
      }
    });
  }

  /**
   * Reads how the previous app process exited and emits an `app_termination` backend event.
   * MUST run on launch BEFORE restoreAfterTermination — once tracking resumes, startModules
   * re-arms the clean-shutdown flag and the previous session's value would be lost.
   * Runs even when no shift is active (still captures the OS exit reason).
   */
  async function reportLastExitReason(): Promise<void> {
    try {
      // A page refresh / live-update apply recreates the JS context (re-running this) without the
      // native process dying. Only report once per real native process launch; the native flag
      // resets only on a true process restart. (UNIMPLEMENTED on older native → fall through.)
      try {
        const { firstLaunch } = await AppExitReason.claimLaunchReport();
        if (!firstLaunch) return;
      } catch {
        // older native binary lacks the method — proceed and report
      }

      // The OS commits ApplicationExitInfo asynchronously, so right after a kill the record may
      // not be queryable yet on this early-startup call. Retry once briefly. Records persist across
      // launches, so anything still missed here is reported (with its timestamp) on the next launch.
      // Only the single most recent exit record is reported. Records are most-recent-first and
      // persist across launches, so sending the full history would re-send the same records on
      // every reopen and bloat the payload.
      let result = await AppExitReason.getLastExitReasons({ max: 1 });
      if (result.platform === 'android' && result.supported && result.reasons.length === 0) {
        await new Promise((resolve) => setTimeout(resolve, 600));
        result = await AppExitReason.getLastExitReasons({ max: 1 });
      }

      const workShiftId = await getCurrentWorkShiftId();
      // `was_clean_shutdown` is only meaningful when a shift was in progress.
      const wasCleanShutdown = workShiftId != null ? await getCleanShutdown() : null;
      const wasPaused = await getShiftPaused();

      const rawReason = result.reasons[0] ?? null;
      // A timestamp of 0 means "no known time" (e.g. an iOS guess without a graceful marker) —
      // surface it as null explicitly rather than a misleading epoch 0.
      const reason = rawReason ? { ...rawReason, timestamp: rawReason.timestamp || null } : null;
      // Last resource-pressure sample before the previous death (includes battery) — lets the
      // backend infer an OS memory/thermal kill. Wrapped so an older native build (live updates)
      // can't break the event.
      let lastResourceSnapshot: unknown = null;
      try {
        lastResourceSnapshot = (await AppExitReason.getLastResourceSnapshot()).snapshot;
      } catch {
        lastResourceSnapshot = null;
      }
      const eventPayload = {
        platform: result.platform,
        reason,
        wasGracefulMarker: result.was_graceful_marker ?? null,
        wasCleanShutdown,
        workShiftId: workShiftId ?? null,
        wasPaused,
        lastResourceSnapshot,
      };
      await sendMobileEvent(MESSAGE_TYPES.app_termination, eventPayload);
    } catch (err: unknown) {
      console.error('[Mobile] Failed to report last exit reason:', err);
    } finally {
      // Consume the previous value; the next shift start re-arms "unclean-assumed".
      await setCleanShutdown(false).catch(() => {});
    }
  }

  async function restoreAfterTermination(): Promise<void> {
    if (!isCanvasserOrSubCanvasser.value) return;
    return mutex.run(async () => {
      try {
        await loadWorkShiftProject();

        const workShiftId = await tryRestoreWorkShift();
        if (!workShiftId) return;

        console.info('[Mobile] Restoring mobile shift after termination.');

        await permsStore.refresh(workShiftProject.value);

        await workShift.timer.ensureInitialised();

        const wasPaused = isPaused.value;
        try {
          const { config, ...statePayload } = await getDeviceStatePayload();
          const eventPayload = { wasPaused, workShiftId, projectId: workShiftProject.value?.id, ...statePayload };
          await sendMobileEvent(MESSAGE_TYPES.restored_after_termination, eventPayload);
        } catch (error: unknown) {
          console.error('[Mobile] Failed to send restored_after_termination event:', error);
        }

        if (wasPaused) {
          // A break is a graceful stop of tracking. reportLastExitReason cleared the flag after
          // reporting this launch; re-assert it so a subsequent OS kill during the *same* ongoing
          // break is still classified as a clean exit rather than a false unclean termination.
          await setCleanShutdown(true);
          setIsTracking(false);
          // Re-show the notification (the OS/app process death may have cleared it). The real
          // break-start time is persisted via the timer (workShift.timer.lastBreakTime, written
          // by pauseWorkShiftSession -> timer.startBreak()), which ensureInitialised() above
          // already restored from storage — so this is the actual break start, not "now".
          const lastBreakTime = workShift.timer.lastBreakTime.value;
          await breakNotification.show(lastBreakTime ? new Date(lastBreakTime) : new Date()).catch(() => {});
          // Fire-and-forget, deliberately NOT awaited: we're inside mutex.run() here, and
          // reconcileTrackerState() itself calls mutex.run() — the mutex is a non-reentrant FIFO
          // queue, so awaiting it from within an already-running mutex.run() callback would
          // deadlock (this call would sit in the queue behind itself, which never finishes).
          // Scheduling it (rather than skipping it) still lets the watchdog catch a module/native
          // watcher orphaned by the termination this function is recovering from.
          void reconcileTrackerState().catch(() => {});
          return;
        }

        await startGrantedModules(workShiftId, true);
      } catch (err: unknown) {
        console.error('[Mobile] Failed to restore mobile shift after termination:', err);
        Sentry.captureException(err);
      }
    });
  }

  async function stop(): Promise<void> {
    return mutex.run(async () => {
      const wasTracking = isTracking.value;
      const wasPaused = isPaused.value;
      if (!wasTracking && !wasPaused) return;

      try {
        // Clear FIRST, before anything else in this try — including setCleanShutdown() below,
        // which is itself a throwable Preferences write. A throw anywhere in this block must
        // never strand the un-swipeable Android "on break" ongoing notification (or pending iOS
        // reminders). clear() is idempotent/self-catching, so calling it this early costs
        // nothing even on the wasTracking-only (never-paused) path.
        await breakNotification.clear().catch(() => {});
        // Graceful stop — clear the "unclean-assumed" flag so next launch reports a clean exit.
        await setCleanShutdown(true);
        setIsTracking(false);
        setIsPaused(false);
        if (wasTracking) {
          await moduleManager.stop();
        }
        await workShift.finishWorkShiftSession();
        await destructBackgroundFetch();
      } catch (err: any) {
        console.error('[Mobile] Error during mobile shift stop:', err);
        Sentry.captureException(err);
      }
    });
  }

  async function checkAndStopIfClosed(): Promise<void> {
    if ((!isTracking.value && !isPaused.value) || !isCanvasserOrSubCanvasser.value) return;
    try {
      console.info('[Mobile] Trying to check if the work shift is still running.');
      const status = await getWorkShiftStatus();
      if (status) {
        const { shiftExists } = await transformToStatusForCurrentDevice(status);
        if (!shiftExists && shiftExists !== undefined) {
          await stop();
        }
      }
    } catch (err: any) {
      console.error('[Mobile] Error checking shift status:', err);
      Sentry.captureException(err);
    }
  }

  /**
   * Watchdog (SGVS-2678): catches the case where the JS-side pause/stop believes tracking has
   * ended but a module handle or a native watcher is actually still running (e.g. a module stop
   * that failed and was kept for retry, or a native watcher orphaned by a live-update webview
   * reload). Safe to call opportunistically — it is a no-op while genuinely tracking, and a
   * no-op when both sides already agree nothing is running.
   */
  async function reconcileTrackerState(): Promise<void> {
    return mutex.run(() =>
      executeReconcile({
        isPaused: () => isPaused.value,
        isTracking: () => isTracking.value,
        aliveModules: () => modulesRef.value.filter((m) => m.isAlive()).map((m) => m.name),
        nativeWatcherCount: async () => {
          try {
            return (await BackgroundGeolocation.containsWatchers()).count;
          } catch {
            return 0; // older native binary under live update
          }
        },
        stopModules: () => moduleManager.stop(),
        removeAllNativeWatchers: async () => {
          await BackgroundGeolocation.removeAllWatchers();
        },
        reportEvent: (payload) => sendMobileEvent(MESSAGE_TYPES.tracker_state_divergence, payload),
        notifyStillTracking: showToastError,
      })
    );
  }

  return {
    initialize,
    start,
    pause,
    reportLastExitReason,
    restoreAfterTermination,
    stop,
    resume,
    checkAndStopIfClosed,
    reconcileTrackerState,
    timer: workShift.timer,
    syncData: workShift.syncAndUploadWorkShiftData,
    syncDataWithProgress: workShift.syncAndUploadDataWithProgress,
  };
}
