import { registerPlugin } from '@capacitor/core';
import type { PluginListenerHandle } from '@capacitor/core';
import { v4 as uuidv4 } from 'uuid';
import type { MobileModule } from '~/types/mobile/module';
import { addPayload } from '~/utils/useDb';

import type {
  AccelerometerEvent,
  GyroscopeEvent,
  MagnetometerEvent,
  MotionActivityEvent,
  MotionActivityPlugin,
} from 'motion-activity-plugin';
import { SENSOR_TYPES } from '~/types/mobile/trackingSensors';
import { getAppConfig } from '~/composables/mobile/config/useMobileConfig';

type SensorEvent = AccelerometerEvent | GyroscopeEvent | MagnetometerEvent | MotionActivityEvent;
type MotionSensorKeys = 'accelerometer' | 'gyroscope' | 'magnetometer' | 'motionActivity';

type MotionSensorType = (typeof SENSOR_TYPES)[MotionSensorKeys];

interface SensorDef {
  type: MotionSensorType;
  startMethod: keyof MotionActivityPlugin;
  stopMethod: keyof MotionActivityPlugin;
  bufferSize: number;
  startOptions?: Record<string, unknown>;
}

interface SensorQueue {
  buf: SensorEvent[];
  maxInMemory: number;
  batchId?: string;
  listener: PluginListenerHandle | null;
}

const MotionActivity = registerPlugin<MotionActivityPlugin>('MotionActivity');

function eventStartTs(event: SensorEvent): number | undefined {
  // MotionActivityEvent carries `timestamp`; IMU aggregate events carry `t_start`.
  return 't_start' in event ? event.t_start : event.timestamp;
}

function eventEndTs(event: SensorEvent): number | undefined {
  return 't_end' in event ? event.t_end : event.timestamp;
}

export function createSensorTracker(shiftId: string, deviceId: string): MobileModule {
  const config = getAppConfig();

  const activityDef: SensorDef = {
    type: SENSOR_TYPES.motionActivity,
    startMethod: 'startActivityUpdates',
    stopMethod: 'stopActivityUpdates',
    bufferSize: config.PhysicalClassifierBufferSize,
    startOptions: { intervalMs: config.MotionActivityIntervalMs },
  };

  const fallbackDefs: SensorDef[] = [
    {
      type: SENSOR_TYPES.accelerometer,
      startMethod: 'startAccelerometerUpdates',
      stopMethod: 'stopAccelerometerUpdates',
      bufferSize: config.PhysicalSensorBufferSize,
      startOptions: { windowMs: config.PhysicalSensorWindowMs },
    },
    {
      type: SENSOR_TYPES.gyroscope,
      startMethod: 'startGyroUpdates',
      stopMethod: 'stopGyroUpdates',
      bufferSize: config.PhysicalSensorBufferSize,
      startOptions: { windowMs: config.PhysicalSensorWindowMs },
    },
    {
      type: SENSOR_TYPES.magnetometer,
      startMethod: 'startMagnetometerUpdates',
      stopMethod: 'stopMagnetometerUpdates',
      bufferSize: config.PhysicalSensorBufferSize,
      startOptions: { windowMs: config.PhysicalSensorWindowMs },
    },
  ];

  let sensorDefs: SensorDef[] = [activityDef];

  const queues = new Map<MotionSensorType, SensorQueue>();

  function initQueues() {
    queues.clear();
    for (const def of sensorDefs) {
      queues.set(def.type, { buf: [], maxInMemory: def.bufferSize, listener: null });
    }
  }

  const pendingFlushes = new Set<Promise<void>>();

  async function flushQueue(type: MotionSensorType) {
    const q = queues.get(type)!;
    if (!q.buf.length) return;

    const batchId = q.batchId;
    const readings = q.buf;
    q.buf = [];
    q.batchId = undefined;

    const batch = {
      record_id: batchId,
      work_shift_id: shiftId,
      device_id: deviceId,
      sensor_type: type,
      started_at: eventStartTs(readings[0]) ?? Date.now(),
      ended_at: eventEndTs(readings[readings.length - 1]) ?? Date.now(),
      sensor_readings: readings,
    };

    try {
      await addPayload(type, batch);
      console.log(`[${type}] Flushed batch ${batchId} with ${readings.length} readings.`);
    } catch (error) {
      console.error(`[${type}] Failed to flush batch ${batchId}:`, error);
    }
  }

  function enqueue(type: MotionSensorType, event: SensorEvent) {
    const q = queues.get(type)!;
    if (!q.batchId) {
      q.batchId = uuidv4();
      console.debug(`[${type}] New batchId generated: ${q.batchId}`);
    }
    q.buf.push(event);
    if (q.buf.length >= q.maxInMemory) {
      const p = flushQueue(type);
      pendingFlushes.add(p);
      p.finally(() => pendingFlushes.delete(p));
    }
  }

  async function startSensor(def: SensorDef) {
    console.debug(
      `[motion] starting sensor ${def.type} via ${String(def.startMethod)} ` +
        (def.startOptions ? `opts=${JSON.stringify(def.startOptions)}` : 'opts=none')
    );
    await (MotionActivity[def.startMethod] as (opts?: Record<string, unknown>) => Promise<void>)(def.startOptions);
    const q = queues.get(def.type)!;
    type AddListenerFn = (
      eventName: MotionSensorType,
      listenerFunc: (event: SensorEvent) => void
    ) => Promise<PluginListenerHandle>;
    let lastMotionTs = 0;
    q.listener = await (MotionActivity.addListener as unknown as AddListenerFn)(def.type, (event) => {
      if (def.type === SENSOR_TYPES.motionActivity) {
        const ma = event as MotionActivityEvent;
        const now = Date.now();
        const dt = lastMotionTs ? now - lastMotionTs : -1;
        lastMotionTs = now;
        console.debug(
          `[motionActivity] event activity=${ma.activity} confidence=${ma.confidence} ` +
            `accel_std=${ma.accelerometer_std} ts=${ma.timestamp} dt_since_prev_ms=${dt}`
        );
      }
      enqueue(def.type, event);
    });
    console.debug(`[motion] listener attached for ${def.type}`);
  }

  async function stopSensor(def: SensorDef) {
    const q = queues.get(def.type)!;
    if (!q.listener) return; // idempotent: already stopped (e.g. a retry re-running all sensorDefs)
    try {
      await (MotionActivity[def.stopMethod] as () => Promise<void>)();
    } catch (e) {
      // Keep q.listener set so isAlive() still reports true and a retry targets this sensor
      // again (SGVS-2678) — do not swallow the error, the module manager needs it to count
      // this sensor as failed-to-stop.
      console.warn(`[${def.type}] Error stopping sensor:`, e);
      throw e;
    }
    q.listener.remove();
    q.listener = null;
  }

  async function resolveSensorDefs() {
    let activityAvailable = false;
    try {
      const res = await MotionActivity.isMotionActivityAvailable();
      activityAvailable = Boolean(res?.available);
      console.info(`[motion] isMotionActivityAvailable -> ${activityAvailable}`);
    } catch (e) {
      console.warn('[motion] isMotionActivityAvailable failed, falling back to raw sensors:', e);
    }
    sensorDefs = activityAvailable ? [activityDef] : fallbackDefs;
    initQueues();
    console.info(
      `[motion] mode=${activityAvailable ? 'classifier' : 'fallback'} sensors=${sensorDefs.map((d) => d.type).join(',')}`
    );
  }

  async function start() {
    await resolveSensorDefs();
    const results = await Promise.allSettled(sensorDefs.map((def) => startSensor(def)));
    for (let i = 0; i < results.length; i++) {
      if (results[i].status === 'rejected') {
        console.warn(`[${sensorDefs[i].type}] unavailable:`, (results[i] as PromiseRejectedResult).reason);
      }
    }
  }

  async function stop() {
    const results = await Promise.allSettled(sensorDefs.map((def) => stopSensor(def)));
    await Promise.all(pendingFlushes);
    await Promise.all([...queues.keys()].map((type) => flushQueue(type)));
    const failures = results.filter((r): r is PromiseRejectedResult => r.status === 'rejected');
    if (failures.length > 0) {
      throw new Error(
        `[motion] ${failures.length} sensor(s) failed to stop: ${failures.map((f) => String(f.reason)).join('; ')}`
      );
    }
  }

  const isAlive = () => [...queues.values()].some((q) => q.listener !== null);
  return { name: 'motion', isAlive, start, stop };
}
