import booleanPointInPolygon from '@turf/boolean-point-in-polygon';
import pointToPolygonDistance from '@turf/point-to-polygon-distance';
import distance from '@turf/distance';
import { point } from '@turf/helpers';
import type { MultiPolygon, Polygon } from 'geojson';
import { fetchRestrictedAreas } from '~/mutations/mobile/fetchRestrictedAreas';
import { type AppConfig } from '~/types/database/config';
import { getAppConfig } from '~/composables/mobile/config/useMobileConfig';
import type {
  ProjectState,
  RestrictedZone,
  RestrictionCheckResult,
  RestrictionStatusEntry,
} from '~/types/mobile/geofencing';
import { AUDIO_RECORDING_PERMISSION } from '~/types/mobile/geofencing';
import type { MobileLocation } from '~/types/mobile/location';
import type { AudioRecordingPermission, RestrictedAreaFeature } from '~/client';

const projectStates = new Map<string, Ref<ProjectState>>();
const inFlightFetches = new Map<string, Promise<void>>();

// After a fetch error, retry no sooner than this many ms. Keeps offline/flaky devices
// from hammering a failing endpoint on every VAD chunk while still recovering quickly
// once connectivity returns.
const ERROR_BACKOFF_MS = 30_000;

// Map API features to local RestrictedZone. The generated client types properties as
// { [key: string]: unknown }, so we normalize both zipCode and zip_code and fall back
// to a synthetic id when neither is present — restrictions must stay enforceable even
// if the identifier field drifts or is missing. Dropping the polygon would silently
// hide a real restricted zone, which is strictly worse than an opaque id.
function featuresToZones(features: RestrictedAreaFeature[]): RestrictedZone[] {
  return features.map((f, i) => {
    const props = (f.properties ?? {}) as Record<string, unknown>;
    const raw = props.zipCode ?? props.zip_code;
    const zipCode = typeof raw === 'string' ? raw : `unknown-${i}`;
    if (typeof raw !== 'string') {
      console.warn('[RestrictionZones] Feature missing zipCode/zip_code, using fallback id:', f);
    }
    return {
      type: 'Feature',
      geometry: f.geometry as unknown as Polygon | MultiPolygon,
      properties: { zipCode },
    };
  });
}

function getProjectState(projectId: string, config: AppConfig): Ref<ProjectState> {
  const key = projectId;

  if (!projectStates.has(key)) {
    projectStates.set(
      key,
      ref<ProjectState>({
        zones: [],
        centerPoint: null,
        fetchRadiusKm: config.GeofenceFetchRadiusKm,
        lastFetchedAt: null,
        nextRetryAfter: null,
        permission: null,
        isLoading: false,
        error: null,
        status: { isRestricted: false, isApproaching: false, distanceKm: null },
        recentRestrictionStatuses: [],
      })
    );
  }

  return projectStates.get(key)!;
}

export function useAudioRestrictionZones(projectId: string) {
  const config = getAppConfig();
  const state = getProjectState(projectId, config);

  function shouldRefreshZones(currentPoint: MobileLocation): boolean {
    const { centerPoint, lastFetchedAt, permission, nextRetryAfter } = state.value;

    if (
      permission === AUDIO_RECORDING_PERMISSION.FULL_RECORDING ||
      permission === AUDIO_RECORDING_PERMISSION.NO_RECORDING
    )
      return false;

    if (nextRetryAfter !== null && Date.now() < nextRetryAfter) return false;

    if (lastFetchedAt === null) return true;

    if (!centerPoint) return true;

    const distanceFromCenter = distance(
      point([currentPoint.longitude, currentPoint.latitude]),
      point([centerPoint.longitude, centerPoint.latitude]),
      { units: 'kilometers' }
    );

    return distanceFromCenter > config.GeofenceRefreshDistanceKm;
  }

  function hasCoverageFor(gpsPoint: MobileLocation): boolean {
    const { centerPoint, fetchRadiusKm, lastFetchedAt } = state.value;
    if (lastFetchedAt === null || !centerPoint) return false;
    const d = distance(
      point([gpsPoint.longitude, gpsPoint.latitude]),
      point([centerPoint.longitude, centerPoint.latitude]),
      { units: 'kilometers' }
    );
    return d <= fetchRadiusKm;
  }

  async function fetchZonesNear(
    centerPoint: MobileLocation,
    radiusKm: number = config.GeofenceFetchRadiusKm
  ): Promise<void> {
    if (!centerPoint || centerPoint.latitude == null || centerPoint.longitude == null) {
      console.warn('[RestrictionZones] fetchZonesNear called with invalid centerPoint:', centerPoint);
      return;
    }

    state.value.isLoading = true;
    state.value.error = null;

    try {
      const response = await fetchRestrictedAreas({
        projectId,
        payload: {
          lat: centerPoint.latitude,
          lon: centerPoint.longitude,
          radius_km: radiusKm,
        },
      });
      state.value.zones = featuresToZones(response.features);
      state.value.centerPoint = centerPoint;
      state.value.fetchRadiusKm = radiusKm;
      state.value.lastFetchedAt = Date.now();
      state.value.nextRetryAfter = null;
      state.value.permission = response.permission as AudioRecordingPermission;

      console.info(`[RestrictionZones] Loaded ${response.features.length} zones, permission: ${response.permission}`);
    } catch (error) {
      state.value.error = error instanceof Error ? error : new Error('Unknown error');
      // Throttle retries so a failing endpoint isn't hit on every VAD chunk.
      // lastFetchedAt is intentionally left alone — it represents the last SUCCESSFUL
      // fetch, so cached zones remain authoritative until a refresh actually succeeds.
      state.value.nextRetryAfter = Date.now() + ERROR_BACKOFF_MS;
      console.error('[RestrictionZones] Failed to fetch zones:', error);
    } finally {
      state.value.isLoading = false;
    }
  }

  function isPointRestricted(gpsPoint: MobileLocation): boolean {
    const pt = point([gpsPoint.longitude, gpsPoint.latitude]);
    return state.value.zones.some((zone) => booleanPointInPolygon(pt, zone));
  }

  function checkRestriction(gpsPoint: MobileLocation): RestrictionCheckResult {
    const pt = point([gpsPoint.longitude, gpsPoint.latitude]);
    const { zones } = state.value;

    if (zones.length === 0) {
      return { isRestricted: false, distanceToNearestZoneKm: null, nearestZoneId: null };
    }

    let isRestricted = false;
    let minDistance = Infinity;
    let nearestZoneId: string | null = null;

    for (const zone of zones) {
      if (booleanPointInPolygon(pt, zone)) {
        return { isRestricted: true, distanceToNearestZoneKm: 0, nearestZoneId: zone.properties.zipCode };
      }

      const dist = pointToPolygonDistance(pt, zone, { units: 'kilometers' });
      if (dist < minDistance) {
        minDistance = dist;
        nearestZoneId = zone.properties.zipCode;
      }
    }

    return {
      isRestricted,
      distanceToNearestZoneKm: minDistance === Infinity ? null : minDistance,
      nearestZoneId,
    };
  }

  function isApproachingRestriction(gpsPoint: MobileLocation): boolean {
    const result = checkRestriction(gpsPoint);
    if (result.distanceToNearestZoneKm === null) return false;
    return result.distanceToNearestZoneKm <= config.GeofenceWarningDistanceKm && !result.isRestricted;
  }

  async function ensureZonesLoaded(gpsPoint: MobileLocation): Promise<void> {
    if (!gpsPoint || gpsPoint.latitude == null || gpsPoint.longitude == null) return;

    const existing = inFlightFetches.get(projectId);
    if (existing) return existing;

    if (shouldRefreshZones(gpsPoint)) {
      const p = fetchZonesNear(gpsPoint).finally(() => {
        inFlightFetches.delete(projectId);
      });
      inFlightFetches.set(projectId, p);
      await p;
    }
  }

  // Updates the live banner status only — safe for display-driven callers (GPS watcher)
  // that shouldn't mutate the decision queue.
  function refreshDisplayStatus(gpsPoint: MobileLocation): void {
    const result = checkRestriction(gpsPoint);
    state.value.status = {
      isRestricted: result.isRestricted,
      isApproaching: isApproachingRestriction(gpsPoint),
      distanceKm: result.distanceToNearestZoneKm,
    };
  }

  // Advances the decision queue used by isRecentlyAllowed. Intended for the VAD
  // pipeline, which owns the record/drop decision per voice segment.
  function updateStatus(gpsPoint: MobileLocation): void {
    refreshDisplayStatus(gpsPoint);

    state.value.recentRestrictionStatuses.push({
      isRestricted: state.value.status.isRestricted,
      hasCoverage: hasCoverageFor(gpsPoint),
      timestamp: Date.now(),
      point: gpsPoint,
    });

    if (state.value.recentRestrictionStatuses.length > config.GeofenceRestrictionQueueSize) {
      state.value.recentRestrictionStatuses.shift();
    }
  }

  function isRecentlyAllowed(): boolean {
    if (state.value.permission === AUDIO_RECORDING_PERMISSION.FULL_RECORDING) return true;

    if (state.value.permission === AUDIO_RECORDING_PERMISSION.NO_RECORDING) return false;

    // Never successfully fetched zones for this project → nothing to trust.
    if (state.value.lastFetchedAt === null) return false;

    const queue = state.value.recentRestrictionStatuses;

    if (queue.length < config.GeofenceRestrictionQueueSize) {
      return false;
    }

    // Every recent point must fall inside the cached fetch radius AND be outside any
    // restricted zone. hasCoverage=false means we drifted past the pre-fetched area and
    // a refresh hasn't succeeded yet — fail closed rather than trust zones we don't have.
    return queue.every((entry) => entry.hasCoverage && !entry.isRestricted);
  }

  function getRecentRestrictionStatuses(): RestrictionStatusEntry[] {
    return state.value.recentRestrictionStatuses.slice();
  }

  function clearCache(): void {
    state.value.zones = [];
    state.value.centerPoint = null;
    state.value.lastFetchedAt = null;
    state.value.nextRetryAfter = null;
    state.value.permission = null;
    state.value.error = null;
    state.value.status = { isRestricted: false, isApproaching: false, distanceKm: null };
    state.value.recentRestrictionStatuses = [];
  }

  const isLoading = computed(() => state.value.isLoading);
  const lastError = computed(() => state.value.error);
  const zones = computed(() => state.value.zones);
  const status = computed(() => state.value.status);
  const permission = computed(() => state.value.permission);

  return {
    isLoading,
    lastError,
    zones,
    status,
    permission,

    ensureZonesLoaded,
    isPointRestricted,
    checkRestriction,
    isApproachingRestriction,
    refreshDisplayStatus,
    updateStatus,
    clearCache,
    isRecentlyAllowed,
    getRecentRestrictionStatuses,
  };
}
