/**
 * True when there is no usable access token AND no refresh token to recover with —
 * i.e. the session cannot produce an authenticated request and must not be used to
 * call routes that require a logged-in user.
 *
 * Deliberately returns `false` when the access token is merely expired but a refresh
 * token is still present, so the normal 401 → refresh → retry path keeps working.
 *
 * Used to short-circuit iterative / background mobile requests (uploader ticks,
 * polling, native requests) before they fire against protected routes while the
 * user is logged out — which would otherwise trigger a spurious refresh / sign-out
 * cascade.
 */
export function isSessionUnrecoverable(): boolean {
  const { isAuthenticated } = useUserRole();
  const { refreshToken } = useAuthState();
  return !isAuthenticated.value && !refreshToken.value;
}
