import { CapacitorHttp, type HttpOptions } from '@capacitor/core';
import { App } from '@capacitor/app';
import {
  cacheStore,
  cacheGet,
  servingOffline,
  isNetworkConnectivityError,
  setOfflineFlag,
  clearOfflineFlag,
} from '~/utils/offlineCache';

export async function refreshAccessToken(): Promise<void> {
  const { refresh, refreshToken } = useAuth();

  if (!refreshToken.value) {
    throw createError({ statusCode: 401, message: 'No refresh token available' });
  }

  await refresh();
}

let signingOut = false;

async function handleSessionExpired(): Promise<void> {
  if (signingOut || isSigningOut() || servingOffline.value) return;
  signingOut = true;

  try {
    const { signOut } = useAuth();
    const route = useRoute();

    showToastError('Session expired. Please log in again.');
    useQueryCache().cancelQueries();

    await signOut({ redirect: true, callbackUrl: buildLoginCallbackUrl(route.fullPath) });
  } finally {
    signingOut = false;
  }
}

export async function doNativeRequest<T>(options: HttpOptions, subject?: string, requiresAuth = true): Promise<T> {
  //No need for guarding with isOffline here because mobile user actions guarded in components and background tasks should act without this check and toast trigger.

  // Short-circuit protected requests when the session is unrecoverable: firing them
  // would send no Authorization header, get a 401, and run the refresh → sign-out
  // cascade (toast, signOut) even though the user is already logged out. Public
  // routes opt out via `requiresAuth: false`.
  if (requiresAuth && isSessionUnrecoverable()) {
    throw createError({ statusCode: 401, message: 'User is not authenticated' });
  }

  const { token } = useAuth();
  const apiBase = useRuntimeConfig().public.apiBaseURL;

  function buildOptions(): HttpOptions {
    return {
      ...options,
      url: `${apiBase}${options.url}`,
      headers: {
        ...(method !== 'GET' ? { 'Content-Type': 'application/json' } : {}),
        ...options.headers,
        ...(token.value ? { Authorization: token.value } : {}),
      },
      connectTimeout: 15000,
      readTimeout: 15000,
    };
  }

  const method = (options.method ?? 'GET').toUpperCase();
  const isGet = method === 'GET';
  const cacheKey = `${apiBase}${options.url}:${method}:${hashBody(options.data)}`;

  async function execute(): Promise<T> {
    try {
      const response = await CapacitorHttp.request(buildOptions());
      clearOfflineFlag();

      if (response.status === 200) {
        if (isGet) {
          cacheStore(cacheKey, response.data).catch(() => {});
        }
        return response.data as T;
      }

      throw createError({
        statusCode: response.status,
        message: `${response.data?.detail || response.data?.message || (subject ? `[${subject}] failed` : 'Unknown error')}`,
        data: response.data,
      });
    } catch (e: any) {
      if (isNetworkConnectivityError(e)) {
        await setOfflineFlag();
        if (isGet) {
          const cached = await cacheGet<T>(cacheKey);
          if (cached !== undefined) return cached;
        }
      }
      throw e;
    }
  }

  try {
    return await execute();
  } catch (e: any) {
    console.warn(`${subject ? `[${subject}] ` : ''}Request failed:`, e);
    if (e?.statusCode !== 401) throw e;

    // 401 — attempt token refresh and retry once
    try {
      await refreshAccessToken();
      return await execute();
    } catch (refreshErr: any) {
      console.warn(`${subject ? `[${subject}] ` : ''}Refreshed request failed:`, refreshErr);
      const statusCode = refreshErr?.statusCode ?? refreshErr?.status;

      if (statusCode === 401 || statusCode === 403) {
        /* Refresh token rejected — sign out in foreground, silently fail in background
          This may cause data loss in work shift case. Untill we don't have refresh logic for refresh token, this is the best we can do.
        */
        const state = await App.getState();
        if (state.isActive) {
          await handleSessionExpired();
        }
      }

      throw refreshErr;
    }
  }
}
