import { CapacitorHttp, type HttpOptions } from '@capacitor/core';
import { FetchError } from 'ofetch';
import { isNetworkConnectivityError, servingOffline, setOfflineFlag, clearOfflineFlag } from '~/utils/offlineCache';

export async function doMobileRequest<T>(options: HttpOptions): Promise<T | undefined> {
  const apiBase = useRuntimeConfig().public.apiBaseURL;

  const updatedOptions = {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
    url: `${apiBase}${options.url}`,
    connectTimeout: 5000,
    readTimeout: 5000,
  };
  try {
    const response = await CapacitorHttp.request(updatedOptions);
    clearOfflineFlag();

    if (response.status !== 200) {
      throw createError({
        statusCode: response.status ?? 500,
        message: `${response.data?.detail || response.data?.message || 'Unknown error'}`,
      });
    }
    return response.data as T;
  } catch (error: any) {
    if (isNetworkConnectivityError(error)) {
      await setOfflineFlag();
      return;
    } else throw error;
  }
}

export async function doWebRequest<T>(
  path: string,
  fetchOptions: Parameters<typeof $fetch>[1] = {}
): Promise<T | undefined | void> {
  const apiBase = useRuntimeConfig().public.apiBaseURL;

  const url = `${apiBase}${path}`;

  return $fetch
    .raw(url, fetchOptions)
    .then((res) => {
      return res._data as T;
    })
    .catch(async (error: FetchError) => {
      if (isNetworkConnectivityError(error)) {
        await setOfflineFlag();
        return;
      } else {
        throw createError({
          statusCode: error.response?.status ?? 500,
          message: `${error?.data?.detail || error.message}`,
        });
      }
    });
}
