export default defineNuxtRouteMiddleware(async (to, from) => {
  const { userRole } = useUserRole();

  const requiredRoles = Array.isArray(to.meta.roles) ? to.meta.roles : undefined;

  if (requiredRoles && !requiredRoles.includes(userRole.value)) {
    if (from.meta.layout !== 'login')
      //TODO: TBD: if (from.meta.layout !== 'login')
      throw createError({ statusCode: 404, statusMessage: `Page not found: ${to.path}` });
    else return await navigateTo({ name: 'projects' }, { replace: true });
  }
});
