import type { HttpOptions } from '@capacitor/core';
import type {
  UnlinkMobileDeviceFromCurrentUserData,
  MobileDeviceUnlinkRequest,
  MobileDeviceUnlinkResponse,
} from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function unlinkDeviceFromUser(payload: MobileDeviceUnlinkRequest): Promise<MobileDeviceUnlinkResponse> {
  const url: UnlinkMobileDeviceFromCurrentUserData['url'] = '/api/mobile/device/unlink';
  const options: HttpOptions = {
    url,
    method: 'POST',
    data: payload,
  };
  return doNativeRequest<MobileDeviceUnlinkResponse>(options, 'UnlinkDeviceFromUser');
}
